// Format date as dd-mm-yyyy
function formatDateDDMMYYYY(dateStr: string | null | undefined): string {
  if (!dateStr) return "";
  try {
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return dateStr;
    const day = date.getDate().toString().padStart(2, '0');
    const month = (date.getMonth() + 1).toString().padStart(2, '0');
    const year = date.getFullYear();
    return `${day}-${month}-${year}`;
  } catch {
    return dateStr;
  }
}

// Format number with thousand separators
function formatCurrency(value: number | string | null | undefined): string {
  if (value === null || value === undefined) return "";
  const num = typeof value === 'string' ? parseFloat(value) : value;
  if (isNaN(num)) return String(value);
  return num.toLocaleString('en-US');
}

// Wrap value in bold tags for contract display (returns Handlebars.SafeString to prevent escaping)
function boldValue(value: string): Handlebars.SafeString {
  if (!value) return new Handlebars.SafeString(value || "");
  return new Handlebars.SafeString(`<strong>${Handlebars.escapeExpression(value)}</strong>`);
}

function calculateYearsOfService(startDate: string | Date): string {
  const start = new Date(startDate);
  const now = new Date();
  const years = Math.floor((now.getTime() - start.getTime()) / (365.25 * 24 * 60 * 60 * 1000));
  const months = Math.floor(((now.getTime() - start.getTime()) % (365.25 * 24 * 60 * 60 * 1000)) / (30.44 * 24 * 60 * 60 * 1000));
  if (years === 0) return `${months} month${months !== 1 ? 's' : ''}`;
  if (months === 0) return `${years} year${years !== 1 ? 's' : ''}`;
  return `${years} year${years !== 1 ? 's' : ''} ${months} month${months !== 1 ? 's' : ''}`;
}

