async function requireAuthOrKiosk(req: Request, res: Response, next: NextFunction) {
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith("Bearer ")) {
    const token = authHeader.substring(7);
    const session = await validateKioskSession(hashSessionToken(token));
    if (session) {
      req.kioskSession = session;
      return next();
    }
  }

  if (req.isAuthenticated && req.isAuthenticated() && req.user) {
    return next();
  }

  return res.status(401).json({ message: "Authentication required" });
}

// Helper function to get default tenant ID
async function getDefaultTenantId(): Promise<string> {
  // First try to find the default tenant by slug
  const result = await db
    .select({ id: tenants.id })
    .from(tenants)
    .where(eq(tenants.slug, DEFAULT_TENANT_SLUG))
    .limit(1);
  if (result.length > 0) {
    return result[0].id;
  }
  
  // Fallback: get any existing tenant
  const anyTenant = await db
    .select({ id: tenants.id })
    .from(tenants)
    .limit(1);
  if (anyTenant.length > 0) {
    return anyTenant[0].id;
  }
  
  // Final fallback: create the default tenant
  const newTenant = await db
    .insert(tenants)
    .values({
      name: "Default",
      slug: DEFAULT_TENANT_SLUG,
    })
    .returning({ id: tenants.id });
  return newTenant[0].id;
}

// Helper function to resolve tenantId with multiple fallbacks
// Priority: 1) user session, 2) existing branches, 3) default tenant
async function resolveTenantId(userTenantId?: string | null): Promise<string> {
  // First try user's tenant from session
  if (userTenantId) {
    return userTenantId;
  }
  
  // Fallback: get from existing branches
  const existingBranches = await db.select({ tenantId: branches.tenantId }).from(branches).limit(1);
  if (existingBranches.length > 0 && existingBranches[0].tenantId) {
    return existingBranches[0].tenantId;
  }
  
  // Final fallback: default tenant
  return getDefaultTenantId();
}

type ChecklistResponsibleStaff = {
  employeeId?: string | null;
  userId?: string | null;
  name: string;
  roleName?: string | null;
};

type ChecklistPeriod = {
  start: Date;
  end: Date;
  dueAt: Date;
};

function addLocalDays(dateString: string, days: number): string {
  const date = new Date(`${dateString}T12:00:00Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

function getChecklistPeriod(
  template: { recurrence?: string | null; weeklyDays?: string[] | null; monthlyDay?: number | null; scheduledTime?: string | null },
  referenceDate: Date,
  timezone: string,
): ChecklistPeriod {
  const localDate = getLocalDateString(referenceDate, timezone);
  const recurrence = template.recurrence || "once";
  const [year, month, day] = localDate.split("-").map(Number);
  const localNoon = new Date(Date.UTC(year, month - 1, day, 12));
  const weekday = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"][localNoon.getUTCDay()];
  const scheduledTime = template.scheduledTime || getLocalTimeString(referenceDate, timezone).slice(0, 5);
  const startDate = recurrence === "monthly"
    ? `${year}-${String(month).padStart(2, "0")}-01`
    : recurrence === "weekly"
      ? addLocalDays(localDate, -(localNoon.getUTCDay() === 0 ? 6 : localNoon.getUTCDay() - 1))
      : localDate;
  const endDate = recurrence === "monthly"
    ? (month === 12 ? `${year + 1}-01-01` : `${year}-${String(month + 1).padStart(2, "0")}-01`)
    : recurrence === "weekly"
      ? addLocalDays(startDate, 7)
      : addLocalDays(startDate, 1);
  const dueDate = recurrence === "monthly" && template.monthlyDay
    ? `${year}-${String(month).padStart(2, "0")}-${String(Math.min(template.monthlyDay, new Date(Date.UTC(year, month, 0)).getUTCDate())).padStart(2, "0")}`
    : recurrence === "weekly" && template.weeklyDays?.length && !template.weeklyDays.includes(weekday)
      ? localDate
      : localDate;

  return {
    start: getMidnightInTimezone(startDate, timezone),
    end: getMidnightInTimezone(endDate, timezone),
    dueAt: createDateTimeInTimezone(dueDate, scheduledTime, timezone),
  };
}

async function getChecklistResponsibleStaff(
  tenantId: string,
  branchId: string,
  template: {
    assignedEmployeeId?: string | null;
    assignedRoleId?: string | null;
    assignedDepartmentId?: string | null;
    departmentId?: string | null;
  },
  dueAt: Date,
  timezone: string,
  scheduledTime: string | null | undefined,
): Promise<ChecklistResponsibleStaff[]> {
  const dateString = getLocalDateString(dueAt, timezone);
  const scheduled = scheduledTime || "00:00";
  const assignments = await db.select({
    employeeId: scheduleAssignments.employeeId,
    fullName: employees.fullName,
    nickname: employees.nickname,
    employeeDepartmentId: employees.primaryDepartmentId,
    roleId: scheduleAssignments.roleId,
    roleName: roles.name,
    shiftDepartmentId: scheduleShiftRows.departmentId,
    startTime: scheduleShiftRows.startTime,
    endTime: scheduleShiftRows.endTime,
  })
    .from(scheduleAssignments)
    .innerJoin(scheduleShiftRows, eq(scheduleAssignments.shiftRowId, scheduleShiftRows.id))
    .leftJoin(employees, eq(scheduleAssignments.employeeId, employees.id))
    .leftJoin(roles, eq(scheduleAssignments.roleId, roles.id))
    .where(and(
      eq(scheduleAssignments.tenantId, tenantId),
      eq(scheduleAssignments.shiftDate, dateString),
      eq(scheduleShiftRows.branchId, branchId),
    ));

  const inScheduledWindow = (startTime: string | null, endTime: string | null) => {
    if (!startTime || !endTime) return true;
    const toMinutes = (value: string) => {
      const [hours, minutes] = value.slice(0, 5).split(":").map(Number);
      return hours * 60 + minutes;
    };
    const target = toMinutes(scheduled);
    const start = toMinutes(startTime);
    let end = toMinutes(endTime);
    if (end <= start) end += 24 * 60;
    return target >= start && target <= end;
  };

  const filtered = assignments.filter((assignment) => {
    if (!assignment.employeeId) return false;
    if (!inScheduledWindow(assignment.startTime, assignment.endTime)) return false;
    if (template.assignedEmployeeId) return assignment.employeeId === template.assignedEmployeeId;
    if (template.assignedRoleId) return assignment.roleId === template.assignedRoleId;
    const departmentId = template.assignedDepartmentId || template.departmentId;
    if (departmentId) {
      return assignment.shiftDepartmentId === departmentId
        || assignment.employeeDepartmentId === departmentId;
    }
    return true;
  });

  return filtered.map((assignment) => ({
    employeeId: assignment.employeeId,
    name: assignment.nickname || assignment.fullName || "On-shift staff",
    roleName: assignment.roleName,
  }));
}

// Helper function to compute probation end date
async function computeProbationEndDate(
  startDate: Date | null | undefined,
  probationDays: number | null | undefined
): Promise<Date | null> {
  if (!startDate) return null;
  
  // Get company default if probationDays is null
  let daysToUse = probationDays;
  if (daysToUse === null || daysToUse === undefined) {
    const setting = await storage.getSetting("probation_days_default");
    daysToUse = setting?.value ? parseInt(setting.value, 10) : 120; // Default 120 days
  }
  
  const endDate = new Date(startDate);
  endDate.setDate(endDate.getDate() + daysToUse);
  return endDate;
}

