  // Fix employees who have signed contracts but still have PENDING status
  // This is a one-time fix for employees created before the contract-signing status update was implemented
  app.post("/api/admin/fix-pending-with-signed-contracts", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      // Find all employees with PENDING status who have signed contracts
      const allEmployees = await storage.getEmployees();
      const pendingEmployees = allEmployees.filter(e => 
        e.status === "pending" || e.employmentState === "PENDING"
      );
      
      const fixed: { id: string; name: string }[] = [];
      
      for (const emp of pendingEmployees) {
        // Check if they have a signed contract
        const contracts = await storage.getContractsForEmployee(emp.id);
        const hasSignedContract = contracts.some(c => c.signingStatus === "signed");
        
        if (hasSignedContract) {
          await storage.updateEmployee(emp.id, {
            status: "active",
            employmentState: "ACTIVE"
          });
          fixed.push({ id: emp.id, name: emp.fullName });
          console.log(`[FixPending] Updated employee ${emp.fullName} to ACTIVE status`);
        }
      }
      
      res.json({
        message: `Fixed ${fixed.length} employee(s)`,
        fixed
      });
    } catch (error) {
      next(error);
    }
  });

  // ============================================
  // PERMISSIONS DEBUG (Admin only)
  // ============================================
  
  // Get full permissions debug info for a user (Global Admin only for security)
  app.get("/api/admin/users/:id/perms-debug", requireAuth, async (req, res, next) => {
    try {
      const requestingUser = req.user!;
      
      // Only allow global_admin and admin to access debug info for security
      if (!["global_admin", "admin"].includes(requestingUser.role)) {
        return res.status(403).json({ message: "Access denied" });
      }
      
      const userId = req.params.id;
      
      // Get user record
      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }
      
      // Get user with branch access (includes modules)
      const userWithAccess = await storage.getUserWithBranchAccess(userId);
      
      // Get employee record if linked
      const employees = await storage.getEmployees();
      const employeeRecord = employees.find(e => e.userId === userId);
      
      // Get access policy if exists
      let accessPolicy = null;
      if (employeeRecord?.personId) {
        accessPolicy = await storage.getAccessPolicy(employeeRecord.personId);
      }
      
      // Compute effective permissions (matches frontend use-mode.tsx logic).
      // Use the effective role from userWithAccess (advisors get staff/manager/admin
      // resolved from their access policy access level, not the raw "advisor" DB value).
      const effectiveRole = userWithAccess?.role ?? user.role;
      const isElevatedRole = ["global_admin", "admin", "operator_admin", "manager"].includes(effectiveRole);

      const getRoleDefaults = (role: string): string[] => {
        if (["global_admin", "admin", "operator_admin", "manager"].includes(role)) {
          return ["core", "ops", "studio", "events", "hr", "setup"];
        }
        return ["core", "ops", "events"];
      };

      // Modules that a given effective role is permitted to use.
      // Staff-level users cannot access HR, Setup, or Studio regardless of
      // what an access policy says — those require manager or admin level.
      const getRoleAllowedModules = (role: string): Set<string> => {
        if (["global_admin", "admin", "operator_admin", "manager"].includes(role)) {
          return new Set(["core", "ops", "studio", "events", "hr", "setup"]);
        }
        return new Set(["core", "ops", "events"]);
      };
      
      let effectiveModules: string[] = [];
      const roleDefaults = getRoleDefaults(effectiveRole);
      const roleAllowed = getRoleAllowedModules(effectiveRole);
      
      if (userWithAccess?.modules) {
        const policyModules: string[] = [];
        if (userWithAccess.modules.core) policyModules.push("core");
        if (userWithAccess.modules.ops || userWithAccess.modules.studio) policyModules.push("ops");
        if (userWithAccess.modules.studio) policyModules.push("studio");
        if (userWithAccess.modules.events || userWithAccess.modules.studio) policyModules.push("events");
        if (userWithAccess.modules.hr) policyModules.push("hr");
        if (userWithAccess.modules.setup || userWithAccess.modules.studio) policyModules.push("setup");

        // Cap policy modules to what the effective role actually permits so that
        // a STAFF advisor with hr:true in their access policy cannot see HR.
        const cappedPolicyModules = policyModules.filter(m => roleAllowed.has(m));
        
        if (cappedPolicyModules.length > 0) {
          // For managers/admins, merge policy modules with role defaults
          if (isElevatedRole) {
            effectiveModules = [...new Set([...cappedPolicyModules, ...roleDefaults])];
          } else {
            effectiveModules = cappedPolicyModules;
          }
        } else {
          // All allowed modules false (or all capped), use role defaults
          effectiveModules = roleDefaults;
        }
      } else {
        // No access policy modules, use role defaults
        effectiveModules = roleDefaults;
      }
      
      const shouldShowModuleSwitcher = effectiveModules.length >= 2;
      
      const { password: _, ...safeUser } = user;
      
      res.json({
        environment: process.env.NODE_ENV || "development",
        userId: user.id,
        email: user.email,
        role: user.role,
        user: safeUser,
        employeeRecord: employeeRecord ? {
          id: employeeRecord.id,
          personId: employeeRecord.personId,
          fullName: employeeRecord.fullName,
          branchId: employeeRecord.branchId,
        } : null,
        accessPolicy: accessPolicy ? {
          personId: accessPolicy.personId,
          modules: accessPolicy.modules,
          coreUserId: accessPolicy.coreUserId,
        } : null,
        computedPermissions: {
          modulesFromAccessPolicy: userWithAccess?.modules || null,
          effectiveModules,
          effectiveBranches: userWithAccess?.allowedBranchIds || [],
          hasAllBranchesAccess: userWithAccess?.hasAllBranchesAccess || false,
        },
        shouldShowModuleSwitcher,
        reason: userWithAccess?.modules 
          ? `Policy: ${JSON.stringify(userWithAccess.modules)} merged with role defaults (${effectiveRole})`
          : `Role-based defaults for: ${effectiveRole}`,
      });
    } catch (error) {
      next(error);
    }
  });

