  // Assign employees to a department (bulk update primaryDepartmentId)
  app.patch("/api/departments/:id/employees", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { employeeIds } = req.body;
      if (!Array.isArray(employeeIds)) {
        return res.status(400).json({ message: "employeeIds must be an array" });
      }

      const dept = await storage.getDepartmentWithBranches(req.params.id);
      if (!dept) {
        return res.status(404).json({ message: "Department not found" });
      }
      
      const userWithAccess = req.userWithAccess;
      if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        const hasAccess = dept.branches?.some(b => userWithAccess.allowedBranchIds.includes(b.id));
        if (!hasAccess) {
          return res.status(403).json({ message: "Access denied" });
        }
      }

      // Get all active employees
      const allEmployees = await storage.getEmployees();
      let accessibleEmployees = allEmployees.filter(e => e.status === 'active');
      
      if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        accessibleEmployees = accessibleEmployees.filter(e => 
          userWithAccess.allowedBranchIds.includes(e.branchId)
        );
      }
      
      const accessibleEmployeeIds = accessibleEmployees.map(e => e.id);
      const invalidIds = employeeIds.filter((id: string) => !accessibleEmployeeIds.includes(id));
      if (invalidIds.length > 0) {
        return res.status(403).json({ message: "You don't have access to some of the selected employees" });
      }
      
      // Get employees currently in this department (only those user has access to)
      const currentlyAssigned = accessibleEmployees.filter(e => e.primaryDepartmentId === req.params.id);
      const currentlyAssignedIds = currentlyAssigned.map(e => e.id);
      
      // Employees to add to this department
      const toAdd = employeeIds.filter((id: string) => !currentlyAssignedIds.includes(id));
      // Employees to remove from this department
      const toRemove = currentlyAssignedIds.filter(id => !employeeIds.includes(id));

      // Update employees being added to this department
      for (const empId of toAdd) {
        await storage.updateEmployee(empId, { primaryDepartmentId: req.params.id });
      }

      // Remove department from employees being removed (set to null)
      for (const empId of toRemove) {
        await storage.updateEmployee(empId, { primaryDepartmentId: null });
      }

      res.json({ success: true, added: toAdd.length, removed: toRemove.length });
    } catch (error) {
      next(error);
    }
  });

