  // Get employee onboarding status (derived from actual data)
  app.get("/api/employees/:id/onboarding-status", requireAuth, async (req, res, next) => {
    try {
      const employee = await storage.getEmployee(req.params.id);
      if (!employee) {
        return res.status(404).json({ message: "Employee not found" });
      }
      
      // Check branch access
      const userWithAccess = req.userWithAccess;
      if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        if (!employee.branchId || !userWithAccess.allowedBranchIds.includes(employee.branchId)) {
          return res.status(403).json({ message: "Access denied to this employee" });
        }
      }

      // Get related data to compute onboarding status
      const [contracts, accessPolicy, assets, enrollmentSessions] = await Promise.all([
        storage.getContractsForEmployee(employee.id),
        employee.personId ? storage.getAccessPolicy(employee.personId) : Promise.resolve(undefined),
        storage.getEmployeeAssets(employee.id),
        storage.getEnrollmentSessionsForEmployee(employee.id),
      ]);

      // Filter to only employment contracts (not archived, not offboarding letters)
      const employmentContracts = contracts.filter((c: ContractInstance) => !c.archivedAt);
      const latestContract = employmentContracts.length > 0 ? employmentContracts[0] : null;

      // Step 1: Essential info completed
      const step1Complete = Boolean(
        employee.fullName && 
        employee.email && 
        employee.branchId
      );

      // Step 2: Employment contract generated
      const step2Complete = Boolean(
        latestContract && 
        ["draft", "finalized", "active"].includes(latestContract.status)
      );

      // Step 4: Signed contract received
      const step4Complete = Boolean(
        latestContract && 
        latestContract.signingStatus === "signed" && 
        latestContract.signedAt
      );

      // Step 3: Contract sent/shared (signing link created, or already signed which implies it was sent)
      const step3Complete = Boolean(
        latestContract && 
        (latestContract.signingToken || latestContract.sentAt || step4Complete)
      );

      // Step 5: User login created (Core account provisioned OR userId linked)
      const step5Complete = Boolean(
        employee.userId || (
          accessPolicy && 
          accessPolicy.coreAccountEnabled === true && 
          accessPolicy.provisioningStatus === "SUCCESS" && 
          accessPolicy.coreUserId
        )
      );

      // Step 6: Face enrollment complete
      const step6Complete = employee.faceEnrollmentStatus === "ENROLLED";
      const hasEnrollmentQr = enrollmentSessions.some((s: EnrollmentSession) => !s.usedAt && s.expiresAt > new Date());

      // Step 7: Company property assigned (or marked as not required)
      const step7Complete = assets.length > 0;

      // Build response
      const onboardingStatus = {
        employeeId: employee.id,
        employeeName: employee.fullName,
        isOnboardingComplete: step1Complete && step2Complete && step3Complete && step4Complete && step5Complete && step6Complete && step7Complete,
        steps: {
          step1_essentialInfo: {
            complete: step1Complete,
            label: "Essential employee info",
            description: "Name, email, and branch assignment",
            missingFields: [
              ...(!employee.fullName ? ["Full name"] : []),
              ...(!employee.email ? ["Email address"] : []),
              ...(!employee.branchId ? ["Home branch"] : []),
            ],
          },
          step2_contractGenerated: {
            complete: step2Complete,
            label: "Employment contract generated",
            description: "Create employment contract from template",
            contractId: latestContract?.id || null,
            contractStatus: latestContract?.status || null,
            unlocked: step1Complete,
          },
          step3_contractSent: {
            complete: step3Complete,
            label: "Contract sent/shared",
            description: "Generate signing link for employee",
            hasSigningToken: Boolean(latestContract?.signingToken),
            sentAt: latestContract?.sentAt || null,
            unlocked: step2Complete,
          },
          step4_contractSigned: {
            complete: step4Complete,
            label: "Signed contract received",
            description: "Employee has signed the contract",
            signingStatus: latestContract?.signingStatus || null,
            signedAt: latestContract?.signedAt || null,
            signedPdfPath: latestContract?.signedPdfPath || null,
            unlocked: step3Complete,
          },
          step5_loginCreated: {
            complete: step5Complete,
            label: "User login created",
            description: "Provision Core account for system access",
            provisioningStatus: accessPolicy?.provisioningStatus || null,
            coreUserId: accessPolicy?.coreUserId || null,
            userId: employee.userId || null,
            unlocked: step4Complete,
          },
          step6_faceEnrollment: {
            complete: step6Complete,
            label: "Face enrollment completed",
            description: "Enroll face for timeclock recognition",
            faceEnrollmentStatus: employee.faceEnrollmentStatus,
            hasActiveEnrollmentQr: hasEnrollmentQr,
            unlocked: step5Complete,
          },
          step7_companyProperty: {
            complete: step7Complete,
            label: "Company property assigned",
            description: "Assign equipment, uniforms, or access cards",
            assignedAssetsCount: assets.length,
            unlocked: step6Complete,
          },
        },
        currentStep: !step1Complete ? 1 : !step2Complete ? 2 : !step3Complete ? 3 : !step4Complete ? 4 : !step5Complete ? 5 : !step6Complete ? 6 : !step7Complete ? 7 : 8,
      };

      res.json(onboardingStatus);
    } catch (error) {
      next(error);
    }
  });

  // Secure profile photo access endpoint
  app.get("/api/employees/:id/profile-photo", requireAuth, async (req, res, next) => {
    try {
      const employee = await storage.getEmployee(req.params.id);
      if (!employee) {
        return res.status(404).json({ message: "Employee not found" });
      }
      
      // Check branch access
      const userWithAccess = req.userWithAccess;
      const user = req.user as any;
      
      // Staff can only view their own photo (via linked employee record)
      if (user.role === "staff") {
        const linkedEmp = await db.select({ id: employees.id }).from(employees).where(eq(employees.userId, user.id)).limit(1);
        if (!linkedEmp.length || linkedEmp[0].id !== employee.id) {
          return res.status(403).json({ message: "Access denied" });
        }
      } else if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        if (!employee.branchId || !userWithAccess.allowedBranchIds.includes(employee.branchId)) {
          return res.status(403).json({ message: "Access denied to this employee" });
        }
      }
      
      if (!employee.profilePhotoPath) {
        return res.status(404).json({ message: "No profile photo available" });
      }
      
      const photoFilename = path.basename(employee.profilePhotoPath);

      const photoFile = await getFileFromObjectStorage("profile-photos", photoFilename);
      if (!photoFile) {
        return res.status(404).json({ message: "Profile photo file not found" });
      }
      res.setHeader("Content-Type", photoFile.contentType);
      res.setHeader("Cache-Control", "public, max-age=86400");
      photoFile.stream.pipe(res);
      return;
    } catch (error) {
      next(error);
    }
  });

