  // Schema for employee creation with optional login setup
  const createEmployeeWithLoginSchema = insertEmployeeSchema.extend({
    setupLogin: z.boolean().optional(),
    loginPassword: z.string().min(6).optional(),
    accessLevel: z.enum(["STAFF", "MANAGER"]).optional(),
    enableHrModule: z.boolean().optional(),
    enableCoreModule: z.boolean().optional(),
  });

  // Staff can only read, managers can create/edit employees
  app.post("/api/employees", requireAuth, requireManager, async (req, res, next) => {
    try {
      // Convert date strings to Date objects or undefined for optional date fields
      const body = { ...req.body };
      const dateFields = ["startDate", "visaExpiryDate", "workPermitExpiryDate", "probationEndDate", "probationReviewCompletedAt", "lastWorkingDay"];
      for (const field of dateFields) {
        if (body[field] === "" || body[field] === null || body[field] === undefined) {
          body[field] = undefined;
        } else if (typeof body[field] === "string") {
          body[field] = new Date(body[field]);
        }
      }
      
      // Extract login setup fields before parsing
      const { setupLogin, loginPassword, accessLevel, enableHrModule, enableCoreModule, ...employeeBody } = body;
      
      // Add tenantId from authenticated user with fallbacks
      employeeBody.tenantId = await resolveTenantId(req.user?.tenantId);
      
      const parsed = insertEmployeeSchema.safeParse(employeeBody);
      if (!parsed.success) {
        return res.status(400).json({ message: parsed.error.message });
      }

      // Validate login setup if requested
      if (setupLogin && (!loginPassword || loginPassword.length < 6)) {
        return res.status(400).json({ message: "Password must be at least 6 characters when setting up login" });
      }

      // Compute probation end date if start date is provided
      const employeeData = { ...parsed.data };
      if (employeeData.startDate) {
        employeeData.probationEndDate = await computeProbationEndDate(
          new Date(employeeData.startDate),
          employeeData.probationDays ?? null
        );
      }

      // If setting up login, create person record first
      let personId: string | null = null;
      let linkedUserId: string | null = null;
      if (setupLogin && loginPassword) {
        // Check if email already exists as user
        const existingUser = await storage.getUserByEmail(parsed.data.email);
        if (existingUser) {
          return res.status(400).json({ message: "A user with this email already exists" });
        }
        
        // Create person record
        const person = await storage.createPerson({
          fullName: parsed.data.fullName,
          email: parsed.data.email,
          phone: parsed.data.phone || null,
          personType: "EMPLOYEE",
        });
        personId = person.id;
        
        // Create user account
        const hashedPassword = await hashPassword(loginPassword);
        const user = await storage.createUser({
          email: parsed.data.email,
          password: hashedPassword,
          fullName: parsed.data.fullName,
          role: accessLevel?.toLowerCase() as "manager" | "staff" || "staff",
          isActive: true,
          mustChangePassword: true,
          createdBy: req.user?.id,
        });
        linkedUserId = user.id;
        
        // Set branch access
        await storage.setUserBranchAccess(
          user.id,
          "selected_branches",
          parsed.data.branchId ? [parsed.data.branchId] : []
        );
        
        // Create access policy
        await storage.createAccessPolicy({
          tenantId: employeeBody.tenantId,
          personId: person.id,
          accessLevel: accessLevel || "STAFF",
          modules: { 
            core: enableCoreModule || false, 
            hr: enableHrModule || false, 
            studio: false 
          },
          branchScope: "SELECTED",
          branchIds: parsed.data.branchId ? [parsed.data.branchId] : [],
          coreAccountEnabled: false,
        });
        
      }

      // Create employee with optional personId and userId links
      const employee = await storage.createEmployee({
        ...employeeData,
        personId: personId,
        userId: linkedUserId,
      });
      
      // Log activity
      try {
        await storage.createActivityLog({
          branchId: employee.branchId || null,
          employeeId: employee.id,
          contractInstanceId: null,
          activityType: "employee_created",
          summaryText: `New employee "${getEmployeeDisplayName(employee)}" was added`,
          createdBy: req.user?.id || null,
        });
      } catch (logError) {
        console.error("Failed to log activity:", logError);
      }
      
      // Trigger attention engine for new employee
      evaluateForEmployee(employee.id).catch(err => console.error("[AttentionEngine] Employee create trigger failed:", err));
      
      res.status(201).json(employee);
    } catch (error) {
      next(error);
    }
  });

  app.patch("/api/employees/:id", requireAuth, requireManager, async (req, res, next) => {
    try {
      const oldEmployee = await storage.getEmployee(req.params.id);
      if (!oldEmployee) {
        return res.status(404).json({ message: "Employee not found" });
      }
      
      // Check branch access
      const userWithAccess = req.userWithAccess;
      if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        if (!oldEmployee.branchId || !userWithAccess.allowedBranchIds.includes(oldEmployee.branchId)) {
          return res.status(403).json({ message: "Access denied to this employee" });
        }
      }

      // Convert date strings to Date objects or null for optional date fields
      const updateData = { ...req.body };
      const dateFields = ["startDate", "visaExpiryDate", "workPermitExpiryDate", "probationEndDate", "probationReviewCompletedAt", "lastWorkingDay"];
      for (const field of dateFields) {
        if (updateData[field] === "" || updateData[field] === null) {
          updateData[field] = null;
        } else if (typeof updateData[field] === "string") {
          updateData[field] = new Date(updateData[field]);
        }
      }
      const startDateChanged = updateData.startDate !== undefined;
      const probationDaysChanged = updateData.probationDays !== undefined;
      
      if (startDateChanged || probationDaysChanged) {
        const startDate = updateData.startDate !== undefined 
          ? (updateData.startDate ? new Date(updateData.startDate) : null)
          : oldEmployee.startDate;
        const probationDays = updateData.probationDays !== undefined 
          ? updateData.probationDays 
          : oldEmployee.probationDays;
        
        updateData.probationEndDate = await computeProbationEndDate(startDate, probationDays);
      }

      const employee = await storage.updateEmployee(req.params.id, updateData);

      // Flag user for permission review if branch changed
      if (updateData.branchId !== undefined && oldEmployee.branchId !== updateData.branchId && employee.userId) {
        await storage.updateUser(employee.userId, { permissionReviewRequired: true } as any);
      }

      // Flag future shifts if lastWorkingDay was moved earlier
      if (updateData.lastWorkingDay !== undefined && employee.lastWorkingDay) {
        const lastDay = new Date(employee.lastWorkingDay);
        const lastDayStr = lastDay.toISOString().split('T')[0];
        // Find assignments for this employee after the new last working day
        const conflictingAssignments = await db.select({
          id: scheduleAssignments.id,
          shiftDate: scheduleAssignments.shiftDate,
        })
          .from(scheduleAssignments)
          .where(and(
            eq(scheduleAssignments.employeeId, employee.id),
            sql`${scheduleAssignments.shiftDate} > ${lastDayStr}`,
          ));
        if (conflictingAssignments.length > 0) {
          await storage.createAttentionItem({
            type: 'SHIFT_NEEDS_COVERAGE',
            severity: 'high',
            branchId: employee.branchId || undefined,
            employeeId: employee.id,
            title: `${conflictingAssignments.length} shift(s) after departure date`,
            description: `${getEmployeeDisplayName(employee)} has ${conflictingAssignments.length} shift(s) scheduled after their last working day (${lastDayStr}). These need to be reassigned or removed.`,
          });
        }
      }
      
      // Sync overlapping fields to linked user account (phone, email, fullName)
      if (employee.userId) {
        const syncFields: any = {};
        
        // Sync phone if updated
        if (updateData.phone !== undefined) {
          let phoneE164 = null;
          if (employee.phone) {
            const cleaned = employee.phone.replace(/\D/g, '');
            if (cleaned.startsWith('66')) {
              phoneE164 = '+' + cleaned;
            } else if (cleaned.startsWith('0')) {
              phoneE164 = '+66' + cleaned.substring(1);
            } else if (cleaned.length > 0) {
              phoneE164 = '+' + cleaned;
            }
          }
          syncFields.phoneNumber = employee.phone || null;
          syncFields.phoneE164 = phoneE164;
          syncFields.phoneVerified = phoneE164 ? true : false;
          syncFields.phoneVerifiedAt = phoneE164 ? new Date() : null;
        }
        
        // Sync email if updated
        if (updateData.email !== undefined) {
          syncFields.email = employee.email;
        }
        
        // Sync fullName if updated
        if (updateData.fullName !== undefined) {
          syncFields.fullName = employee.fullName;
        }
        
        if (Object.keys(syncFields).length > 0) {
          try {
            await storage.updateUser(employee.userId, syncFields);
            console.log(`[EmployeeUserSync] Synced fields to user ${employee.userId}:`, Object.keys(syncFields));
          } catch (syncError) {
            console.error("[EmployeeUserSync] Failed to sync to user:", syncError);
          }
        }
      }
      
      // Log employment status changes (resignations/terminations)
      if (oldEmployee.status === "active" && (employee.status === "resigned" || employee.status === "terminated")) {
        try {
          const actionWord = employee.status === "terminated" ? "terminated" : "resigned";
          const endReason = employee.endReason ? ` - ${employee.endReason}` : "";
          await storage.createActivityLog({
            branchId: employee.branchId || null,
            employeeId: employee.id,
            contractInstanceId: null,
            activityType: "employment_ended",
            summaryText: `${getEmployeeDisplayName(employee)} ${actionWord}${endReason}`,
            createdBy: req.user?.id || null,
          });
        } catch (logError) {
          console.error("Failed to log employment_ended activity:", logError);
        }
      }
      
      // Log salary/position changes if detected
      if (oldEmployee && req.body.defaultMergeData) {
        const oldData = oldEmployee.defaultMergeData;
        const newData = req.body.defaultMergeData;
        
        try {
          if (oldData?.positionTitle && newData?.positionTitle && oldData.positionTitle !== newData.positionTitle) {
            await storage.createActivityLog({
              branchId: employee.branchId || null,
              employeeId: employee.id,
              contractInstanceId: null,
              activityType: "promotion",
              summaryText: `${getEmployeeDisplayName(employee)} position changed from "${oldData.positionTitle}" to "${newData.positionTitle}"`,
              metadataJson: JSON.stringify({ oldValue: oldData.positionTitle, newValue: newData.positionTitle }),
              createdBy: req.user?.id || null,
            });
          }
          
          if (oldData?.salaryThb && newData?.salaryThb && oldData.salaryThb !== newData.salaryThb) {
            await storage.createActivityLog({
              branchId: employee.branchId || null,
              employeeId: employee.id,
              contractInstanceId: null,
              activityType: "salary_change",
              summaryText: `${getEmployeeDisplayName(employee)} salary changed from ฿${oldData.salaryThb.toLocaleString()} to ฿${newData.salaryThb.toLocaleString()}`,
              metadataJson: JSON.stringify({ oldValue: oldData.salaryThb, newValue: newData.salaryThb }),
              createdBy: req.user?.id || null,
            });
          }
        } catch (logError) {
          console.error("Failed to log activity:", logError);
        }
      }
      
      // Trigger attention engine for updated employee
      evaluateForEmployee(employee.id).catch(err => console.error("[AttentionEngine] Employee update trigger failed:", err));
      
      res.json(employee);
    } catch (error) {
      next(error);
    }
  });

  // Enable login access for existing employee
  app.post("/api/employees/:id/enable-login", requireAuth, requireManager, async (req, res, next) => {
    try {
      const employee = await storage.getEmployee(req.params.id);
      if (!employee) {
        return res.status(404).json({ message: "Employee not found" });
      }
      
      // Check branch access
      const userWithAccess = req.userWithAccess;
      if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        if (!employee.branchId || !userWithAccess.allowedBranchIds.includes(employee.branchId)) {
          return res.status(403).json({ message: "Access denied to this employee" });
        }
      }
      
      // Validate request body
      const { email, accessLevel, enableHrModule, enableCoreModule, enableStudioModule, enableEventsModule, enableOpsModule, enableSetupModule, branchScope, branchIds, password } = req.body;
      
      // Permission checks
      if (!req.user) {
        return res.status(401).json({ message: "Not authenticated" });
      }
      
      // Only admin can set ADMIN access level
      const effectiveCallerRole = req.userWithAccess?.role ?? req.user.role;
      if (accessLevel === "ADMIN" && effectiveCallerRole !== "admin") {
        return res.status(403).json({ message: "Only administrators can grant ADMIN access level" });
      }
      
      // Only admin can grant ALL branches
      if (branchScope === "ALL" && effectiveCallerRole !== "admin") {
        return res.status(403).json({ message: "Only administrators can grant access to all branches" });
      }
      
      // Validate password
      if (!password || password.length < 6) {
        return res.status(400).json({ message: "Password must be at least 6 characters" });
      }
      
      // Use employee email if not provided
      const loginEmail = email || employee.email;
      if (!loginEmail) {
        return res.status(400).json({ message: "Email is required for login access" });
      }
      
      // Check if email already exists as user
      const existingUser = await storage.getUserByEmail(loginEmail);
      if (existingUser) {
        return res.status(400).json({ message: "A user with this email already exists" });
      }
      
      // Check if employee already has a person record
      let personId = employee.personId;
      if (!personId) {
        // Check if a person with this email already exists
        const existingPerson = await storage.getPersonByEmail(loginEmail);
        if (existingPerson) {
          // Use existing person record and link to employee
          personId = existingPerson.id;
          await storage.updateEmployee(employee.id, { personId: existingPerson.id });
        } else {
          // Create person record
          const person = await storage.createPerson({
            fullName: employee.fullName,
            preferredName: employee.preferredName || null,
            email: loginEmail,
            phone: employee.phone || null,
            personType: "EMPLOYEE",
          });
          personId = person.id;
          
          // Link person to employee
          await storage.updateEmployee(employee.id, { personId: person.id });
        }
      } else {
        // Check if access policy already exists
        const existingPolicy = await storage.getAccessPolicy(personId);
        if (existingPolicy) {
          return res.status(400).json({ message: "This employee already has an access policy configured" });
        }
      }
      
      // Determine branch scope and IDs
      const finalBranchScope = branchScope || "SELECTED";
      const finalBranchIds = branchScope === "ALL" ? [] : (branchIds || (employee.branchId ? [employee.branchId] : []));
      
      // Resolve tenantId with fallbacks
      const resolvedTenantId = await resolveTenantId(req.user?.tenantId);
      
      // Defensive cleanup: Delete any orphaned access policy for this personId
      // This can happen if a previous user was deleted without proper cleanup
      const existingOrphanedPolicy = await storage.getAccessPolicy(personId);
      if (existingOrphanedPolicy) {
        // Check if this policy is actually orphaned (no linked user, or the user was deleted)
        // We also check userId (HR module user) not just coreUserId
        const linkedCoreUser = existingOrphanedPolicy.coreUserId 
          ? await storage.getUser(existingOrphanedPolicy.coreUserId)
          : null;
        const linkedHrUser = existingOrphanedPolicy.userId 
          ? await storage.getUser(existingOrphanedPolicy.userId)
          : null;
        if (!linkedCoreUser && !linkedHrUser) {
          // Orphaned policy - delete it
          await storage.deleteAccessPolicy(personId);
          console.log(`[Enable Login] Cleaned up orphaned access policy for personId: ${personId}`);
        }
      }
      
      // Create user account
      const hashedPassword = await hashPassword(password);
      const userRole = accessLevel?.toLowerCase() as "admin" | "manager" | "staff" || "staff";
      const user = await storage.createUser({
        email: loginEmail,
        password: hashedPassword,
        fullName: employee.fullName,
        role: userRole,
        isActive: true,
        mustChangePassword: true,
        createdBy: req.user.id,
      });
      
      // Set branch access (pass tenantId since users table doesn't have it)
      if (finalBranchScope === "ALL") {
        await storage.setUserBranchAccess(user.id, "all_branches", [], resolvedTenantId);
      } else {
        await storage.setUserBranchAccess(user.id, "selected_branches", finalBranchIds, resolvedTenantId);
      }
      
      // Create access policy
      const accessPolicy = await storage.createAccessPolicy({
        tenantId: resolvedTenantId,
        personId: personId,
        accessLevel: accessLevel || "STAFF",
        modules: { 
          core: enableCoreModule ?? true, 
          hr: enableHrModule ?? (accessLevel === "MANAGER" || accessLevel === "ADMIN"), 
          studio: enableStudioModule ?? false,
          events: enableEventsModule ?? false,
          ops: enableOpsModule ?? false,
          setup: enableSetupModule ?? false,
        },
        branchScope: finalBranchScope,
        branchIds: finalBranchIds,
        coreAccountEnabled: false,
        provisioningStatus: "NOT_STARTED",
      });
      
      // Trigger attention engine to resolve MISSING_LOGIN_ACCESS
      evaluateForEmployee(employee.id).catch(err => console.error("[AttentionEngine] Enable login trigger failed:", err));
      
      res.json({
        success: true,
        personId,
        userId: user.id,
        accessPolicyId: accessPolicy.id,
        message: "Login access enabled successfully",
      });
    } catch (error) {
      next(error);
    }
  });

  // Generate login for employee (auto-username, no email required)
  app.post("/api/employees/:id/generate-login", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { generateUniqueUsername, generateTempPassword } = await import("./utils/username-generator");
      
      const employee = await storage.getEmployee(req.params.id);
      if (!employee) {
        return res.status(404).json({ message: "Employee not found" });
      }
      
      // Check if employee already has a user account
      if (employee.userId) {
        return res.status(409).json({ message: "Employee already has a login account" });
      }
      
      // Check branch access
      const userWithAccess = req.userWithAccess;
      if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        if (!employee.branchId || !userWithAccess.allowedBranchIds.includes(employee.branchId)) {
          return res.status(403).json({ message: "Access denied to this employee" });
        }
      }
      
      if (!req.user) {
        return res.status(401).json({ message: "Not authenticated" });
      }
      
      // Role restriction: only allow STAFF or MANAGER roles from employee flow
      const { role = "staff" } = req.body;
      const allowedRoles = ["staff", "manager"];
      if (!allowedRoles.includes(role)) {
        return res.status(403).json({ message: "Can only create staff or manager accounts from employee flow" });
      }
      
      // Generate unique username
      const nameParts = employee.fullName.split(" ");
      const firstName = nameParts[0] || null;
      const lastName = nameParts.length > 1 ? nameParts[nameParts.length - 1] : null;
      const username = await generateUniqueUsername(firstName, lastName, null, employee.id);
      
      // Generate temp password
      const tempPassword = generateTempPassword(12);
      const hashedPassword = await hashPassword(tempPassword);
      
      // Get operator ID from employee's branch
      let operatorId = null;
      if (employee.branchId) {
        const branch = await storage.getBranch(employee.branchId);
        operatorId = branch?.operatorId || null;
      }
      
      // Create user account with auto-generated username
      // Sync phone from employee but do NOT mark as verified - user must verify on first login
      const user = await storage.createUser({
        username,
        email: employee.email || `${username}@placeholder.local`,
        password: hashedPassword,
        fullName: employee.fullName,
        role: role as "staff" | "manager",
        operatorId,
        phoneNumber: employee.phoneNumber || null,
        phoneE164: employee.phoneE164 || null,
        phoneVerified: false, // User must verify phone on first login
        isActive: true,
        mustChangePassword: true,
        createdBy: req.user.id,
      });
      
      // Set branch access
      if (employee.branchId) {
        await storage.setUserBranchAccess(user.id, "selected_branches", [employee.branchId]);
      }
      
      // Link user to employee
      await storage.updateEmployee(employee.id, { userId: user.id });
      
      // Trigger attention engine
      evaluateForEmployee(employee.id).catch(err => console.error("[AttentionEngine] Generate login trigger failed:", err));
      
      res.json({
        success: true,
        userId: user.id,
        username,
        tempPassword, // Shown once only
        tempPasswordShownOnce: true,
        message: "Login created successfully. Save the password - it will not be shown again.",
      });
    } catch (error) {
      next(error);
    }
  });

  // Reset password for employee's user account
  app.post("/api/employees/:id/reset-password", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { generateTempPassword } = await import("./utils/username-generator");
      
      const employee = await storage.getEmployee(req.params.id);
      if (!employee) {
        return res.status(404).json({ message: "Employee not found" });
      }
      
      // Check for either new userId or legacy personId
      let targetUserId = employee.userId;
      if (!targetUserId && employee.personId) {
        // Legacy account - get user from access policy using personId
        const accessPolicy = await storage.getAccessPolicy(employee.personId);
        if (accessPolicy?.coreUserId) {
          targetUserId = accessPolicy.coreUserId;
        }
      }
      
      if (!targetUserId) {
        return res.status(400).json({ message: "Employee does not have a login account" });
      }
      
      // Verify the user actually exists
      const targetUser = await storage.getUser(targetUserId);
      if (!targetUser) {
        // User was deleted but access policy still exists - clean up orphaned data
        if (employee.personId) {
          const accessPolicy = await storage.getAccessPolicy(employee.personId);
          if (accessPolicy) {
            // Delete the orphaned access policy
            await storage.deleteAccessPolicy(employee.personId);
            console.log(`[Reset Password] Cleaned up orphaned access policy for personId: ${employee.personId}`);
          }
        }
        return res.status(400).json({ 
          message: "User account was deleted. The orphaned data has been cleaned up. Please use 'Enable Login' to create a new account for this employee.",
          needsReprovisioning: true
        });
      }
      
      // Check branch access
      const userWithAccess = req.userWithAccess;
      if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        if (!employee.branchId || !userWithAccess.allowedBranchIds.includes(employee.branchId)) {
          return res.status(403).json({ message: "Access denied to this employee" });
        }
      }
      
      // Generate new temp password
      const tempPassword = generateTempPassword(12);
      const hashedPassword = await hashPassword(tempPassword);
      
      // Update user password
      await storage.updateUser(targetUserId, { 
        password: hashedPassword,
        mustChangePassword: true,
      });
      
      res.json({
        success: true,
        tempPassword,
        tempPasswordShownOnce: true,
        message: "Password reset successfully. Save the new password - it will not be shown again.",
      });
    } catch (error) {
      next(error);
    }
  });

