  // Get cost allocations for an employee
  app.get("/api/employees/:id/cost-allocations", requireAuth, async (req, res, next) => {
    try {
      const employeeId = req.params.id;
      const employee = await storage.getEmployee(employeeId);
      if (!employee) {
        return res.status(404).json({ message: "Employee not found" });
      }

      // Check branch access
      const userWithAccess = req.userWithAccess;
      if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        if (!employee.branchId || !userWithAccess.allowedBranchIds.includes(employee.branchId)) {
          return res.status(403).json({ message: "Access denied to this employee" });
        }
      }

      // Get allocations with branch names
      const allocations = await db
        .select({
          id: staffCostAllocations.id,
          tenantId: staffCostAllocations.tenantId,
          employeeId: staffCostAllocations.employeeId,
          branchId: staffCostAllocations.branchId,
          allocationPercent: staffCostAllocations.allocationPercent,
          createdAt: staffCostAllocations.createdAt,
          updatedAt: staffCostAllocations.updatedAt,
          branchName: branches.name,
        })
        .from(staffCostAllocations)
        .leftJoin(branches, eq(staffCostAllocations.branchId, branches.id))
        .where(eq(staffCostAllocations.employeeId, employeeId))
        .orderBy(desc(staffCostAllocations.allocationPercent));

      res.json(allocations);
    } catch (error) {
      next(error);
    }
  });

  // Update cost allocations for an employee (replace all allocations)
  app.put("/api/employees/:id/cost-allocations", requireAuth, requireManager, async (req, res, next) => {
    try {
      const employeeId = req.params.id;
      const employee = await storage.getEmployee(employeeId);
      if (!employee) {
        return res.status(404).json({ message: "Employee not found" });
      }

      // Check branch access
      const userWithAccess = req.userWithAccess;
      if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        if (!employee.branchId || !userWithAccess.allowedBranchIds.includes(employee.branchId)) {
          return res.status(403).json({ message: "Access denied to this employee" });
        }
      }

      // Validate request body
      const allocationsSchema = z.array(z.object({
        branchId: z.string(),
        allocationPercent: z.number().min(0).max(100),
      }));

      const parsed = allocationsSchema.safeParse(req.body.allocations);
      if (!parsed.success) {
        return res.status(400).json({ message: "Invalid allocations format", errors: parsed.error.issues });
      }

      const allocations = parsed.data;

      // Validate total is 100%
      const total = allocations.reduce((sum, a) => sum + a.allocationPercent, 0);
      if (Math.abs(total - 100) > 0.01) {
        return res.status(400).json({ message: `Allocations must total 100%. Current total: ${total}%` });
      }

      // Validate no duplicate branch IDs
      const branchIds = allocations.map(a => a.branchId);
      if (new Set(branchIds).size !== branchIds.length) {
        return res.status(400).json({ message: "Duplicate branch allocations not allowed" });
      }

      // Validate all branches exist
      const validBranches = await db.select({ id: branches.id }).from(branches).where(inArray(branches.id, branchIds));
      if (validBranches.length !== branchIds.length) {
        return res.status(400).json({ message: "One or more invalid branch IDs" });
      }

      // Get tenant ID
      const tenantId = employee.tenantId || (await resolveTenantId(req.user?.tenantId));

      // Transaction: delete existing and insert new
      await db.delete(staffCostAllocations).where(eq(staffCostAllocations.employeeId, employeeId));

      if (allocations.length > 0) {
        await db.insert(staffCostAllocations).values(
          allocations.map(a => ({
            tenantId,
            employeeId,
            branchId: a.branchId,
            allocationPercent: a.allocationPercent,
          }))
        );
      }

      // Return updated allocations
      const updatedAllocations = await db
        .select({
          id: staffCostAllocations.id,
          tenantId: staffCostAllocations.tenantId,
          employeeId: staffCostAllocations.employeeId,
          branchId: staffCostAllocations.branchId,
          allocationPercent: staffCostAllocations.allocationPercent,
          createdAt: staffCostAllocations.createdAt,
          updatedAt: staffCostAllocations.updatedAt,
          branchName: branches.name,
        })
        .from(staffCostAllocations)
        .leftJoin(branches, eq(staffCostAllocations.branchId, branches.id))
        .where(eq(staffCostAllocations.employeeId, employeeId))
        .orderBy(desc(staffCostAllocations.allocationPercent));

      res.json(updatedAllocations);
    } catch (error) {
      next(error);
    }
  });

