  // Delete a contract (admin only, with safety checks)
  app.delete("/api/contracts/:id", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const contract = await storage.getContract(req.params.id);
      if (!contract) {
        return res.status(404).json({ message: "Contract not found" });
      }
      
      // Check branch access via employee
      const userWithAccess = req.userWithAccess;
      if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        const employee = await storage.getEmployee(contract.employeeId);
        if (!employee?.branchId || !userWithAccess.allowedBranchIds.includes(employee.branchId)) {
          return res.status(403).json({ message: "Access denied to this contract" });
        }
      }
      
      // Safety check: Cannot delete active, signed, or awaiting signature contracts
      if (contract.status === "active") {
        return res.status(400).json({ 
          message: "Cannot delete an active contract. Please supersede it with a new contract first." 
        });
      }
      if (contract.signingStatus === "signed") {
        return res.status(400).json({ 
          message: "Cannot delete a signed contract. Signed contracts must be preserved for legal compliance." 
        });
      }
      // Awaiting signature contracts CAN be deleted (cancels the pending signing process)
      
      await storage.deleteContract(req.params.id);
      res.sendStatus(204);
    } catch (error) {
      next(error);
    }
  });

  // Archive a signed contract (admin only) - moves to archived state instead of deleting
  app.patch("/api/contracts/:id/archive", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const contract = await storage.getContract(req.params.id);
      if (!contract) {
        return res.status(404).json({ message: "Contract not found" });
      }
      
      // Check branch access via employee
      const userWithAccess = req.userWithAccess;
      if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        const employee = await storage.getEmployee(contract.employeeId);
        if (!employee?.branchId || !userWithAccess.allowedBranchIds.includes(employee.branchId)) {
          return res.status(403).json({ message: "Access denied to this contract" });
        }
      }
      
      // Only signed or active contracts can be archived
      if (contract.signingStatus !== "signed" && contract.status !== "active") {
        return res.status(400).json({ 
          message: "Only signed or active contracts can be archived. Draft contracts should be deleted instead." 
        });
      }
      
      // Check if already archived
      if (contract.archivedAt) {
        return res.status(400).json({ message: "Contract is already archived." });
      }
      
      const archivedContract = await storage.archiveContract(req.params.id);
      
      // Log the archive activity
      const employee = await storage.getEmployee(contract.employeeId);
      await storage.createActivityLog({
        activityType: "contract_archived",
        employeeId: contract.employeeId,
        branchId: employee?.branchId || null,
        contractInstanceId: contract.id,
        summaryText: `Contract archived for ${getEmployeeDisplayName(employee)}`,
        createdBy: req.user!.id,
        metadataJson: JSON.stringify({ contractId: contract.id }),
      });
      
      res.json(archivedContract);
    } catch (error) {
      next(error);
    }
  });

