  // Atomic endpoint: Update employee + create contract in single transaction
  app.post("/api/contracts/generate", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { 
        employeeId, 
        templateId, 
        mergeDataJson, 
        employeeUpdates,
        expectedVersion,
        generateSigningLink,
        createdBy,
        language
      } = req.body;

      if (!employeeId || !templateId) {
        return res.status(400).json({ message: "employeeId and templateId are required" });
      }

      const employee = await storage.getEmployee(employeeId);
      if (!employee) {
        return res.status(404).json({ message: "Employee not found" });
      }
      
      // Check branch access
      const userWithAccess = req.userWithAccess;
      if (userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        if (!employee.branchId || !userWithAccess.allowedBranchIds.includes(employee.branchId)) {
          return res.status(403).json({ message: "Access denied to this employee's branch" });
        }
      }

      // Optimistic concurrency check
      if (expectedVersion !== undefined && employee.version !== expectedVersion) {
        return res.status(409).json({ 
          message: "Employee was modified by another user",
          currentVersion: employee.version,
          expectedVersion: expectedVersion,
          error: "VERSION_CONFLICT"
        });
      }

      const template = await storage.getTemplate(templateId);
      if (!template) {
        return res.status(404).json({ message: "Template not found" });
      }

      let branch = null;
      if (employee.branchId) {
        branch = await storage.getBranch(employee.branchId);
      }

      // Perform atomic transaction: update employee + create contract
      const result = await db.transaction(async (tx) => {
        let updatedEmployee = employee;
        const changedFields: Record<string, { old: any; new: any }> = {};

        // Apply employee updates if provided
        if (employeeUpdates && Object.keys(employeeUpdates).length > 0) {
          // Track which fields are changing for activity log
          for (const [key, newValue] of Object.entries(employeeUpdates)) {
            const oldValue = (employee as any)[key];
            if (oldValue !== newValue) {
              changedFields[key] = { old: oldValue, new: newValue };
            }
          }

          // Update employee with version increment
          const [empResult] = await tx
            .update(employees)
            .set({
              ...employeeUpdates,
              version: (employee.version || 1) + 1,
              updatedAt: new Date(),
              updatedBy: req.user!.id,
            })
            .where(and(
              eq(employees.id, employeeId),
              eq(employees.version, employee.version || 1)
            ))
            .returning();

          if (!empResult) {
            throw new Error("VERSION_CONFLICT");
          }
          updatedEmployee = empResult;
        }

        // Create employee snapshot for audit trail
        const employeeSnapshot = {
          id: updatedEmployee.id,
          fullName: updatedEmployee.fullName,
          nickname: updatedEmployee.nickname,
          email: updatedEmployee.email,
          phone: updatedEmployee.phone,
          address: updatedEmployee.address,
          nationalId: updatedEmployee.nationalId,
          branchId: updatedEmployee.branchId,
          positionTitle: updatedEmployee.positionTitle,
          salary: updatedEmployee.salary,
          foodAllowancePerDay: updatedEmployee.foodAllowancePerDay,
          startDate: updatedEmployee.startDate,
          probationEndDate: updatedEmployee.probationEndDate,
          employmentType: updatedEmployee.employmentType,
          version: updatedEmployee.version,
          capturedAt: new Date().toISOString(),
        };

        // Derive work location from branch
        const workLocation = branch?.name || mergeDataJson?.workLocation || "";
        const today = new Date();
        const todayFormatted = formatDateDDMMYYYY(today.toISOString());

        let departmentName = "";
        if (updatedEmployee.primaryDepartmentId) {
          const dept = await storage.getDepartment(updatedEmployee.primaryDepartmentId);
          if (dept) departmentName = dept.name;
        }

        // Format and bold all variable values for contract display
        const data = {
          employee: {
            full_name: boldValue(updatedEmployee.fullName),
            email: boldValue(updatedEmployee.email),
            phone: boldValue(updatedEmployee.phone || ""),
            address: boldValue(updatedEmployee.address || ""),
            id_number: boldValue(updatedEmployee.taxIdNumber || ""),
            department: boldValue(departmentName),
            start_date_employment: boldValue(updatedEmployee.startDate ? formatDateDDMMYYYY(updatedEmployee.startDate.toString()) : ""),
            years_of_service: boldValue(updatedEmployee.startDate ? calculateYearsOfService(updatedEmployee.startDate) : ""),
          },
          contract: {
            position_title: boldValue(mergeDataJson?.positionTitle || updatedEmployee.positionTitle || ""),
            salary_thb: boldValue(formatCurrency(mergeDataJson?.salaryThb || updatedEmployee.salary)),
            start_date: boldValue(formatDateDDMMYYYY(mergeDataJson?.startDate || updatedEmployee.startDate)),
            work_location: boldValue(workLocation),
            food_allowance_per_day: boldValue(updatedEmployee.foodAllowancePerDay ? formatCurrency(updatedEmployee.foodAllowancePerDay) : ""),
          },
          branch: branch ? {
            name: boldValue(branch.name),
            address: boldValue(branch.address || ""),
          } : {
            name: "",
            address: "",
          },
          document: {
            todays_date: boldValue(todayFormatted),
          },
          today: boldValue(todayFormatted),
          termination: buildTerminationData(mergeDataJson),
          warning: buildWarningData(mergeDataJson),
          incentive_clause_block: renderIncentiveClauseBlock(mergeDataJson?.incentiveClause || updatedEmployee.incentiveClauseText, updatedEmployee.foodAllowancePerDay),
          special_terms_block: renderSpecialTermsBlock(mergeDataJson?.customClauses),
          visa_sponsorship_block: renderVisaSponsorshipBlock({
            companyHandles: updatedEmployee.visaWpCompanyHandles || false,
            companyPays: updatedEmployee.visaWpCompanyPays || false,
            costThb: updatedEmployee.visaWpCostThb,
            repaymentIfFailProbation: updatedEmployee.visaWpRepaymentIfFailProbation || false,
            repaymentIfLeaveBefore1y: updatedEmployee.visaWpRepaymentIfLeaveBefore1y || false,
            repaymentTermsText: updatedEmployee.visaWpRepaymentTermsText,
            notes: updatedEmployee.visaWpNotes,
          }),
        };

        const templateBody = (language === "th" && template.htmlBodyTh) ? template.htmlBodyTh : template.htmlBody;
        const templateSnapshotHtml = compileTemplate(templateBody, data);

        // Enhanced merge data for historical record
        const enhancedMergeData = {
          ...mergeDataJson,
          workLocation,
          todayDate: todayFormatted,
          language: language || "en",
        };

        // Create contract with employee snapshot
        const [contract] = await tx.insert(contractInstances).values({
          employeeId,
          templateId,
          templateSnapshotHtml,
          templateSnapshotVersion: template.version,
          mergeDataJson: enhancedMergeData,
          employeeSnapshotJson: employeeSnapshot,
          status: "finalized",
          createdBy: createdBy || req.user!.id,
          pdfPath: null,
          sentToEmail: null,
          signingToken: generateSigningLink ? crypto.randomBytes(32).toString("hex") : null,
          signingLinkExpiresAt: generateSigningLink ? new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) : null,
        }).returning();

        return { contract, templateSnapshotHtml, employeeSnapshot, changedFields, updatedEmployee };
      });

      // Render and store the PDF after the database transaction succeeds.
      const pdfHeader = branch && (template.headerShowLogo || template.headerShowAddress) ? {
        name: template.headerShowAddress ? branch.name : "",
        address: template.headerShowAddress ? branch.address || "" : "",
        logoUrl: template.headerShowLogo ? branch.logoUrl ?? undefined : undefined,
      } : undefined;
      const pdfBuffer = await generatePdf(result.templateSnapshotHtml, pdfHeader);
      const pdfPath = await uploadFinalizedPdf(result.contract.id, template.version, pdfBuffer);

      // Update contract with PDF path (separate from atomic transaction)
      const finalContract = await storage.updateContract(result.contract.id, { pdfPath });

      // Log activity for employee changes (outside transaction for performance)
      if (Object.keys(result.changedFields).length > 0) {
        await storage.createActivityLog({
          activityType: "employee_updated" as ActivityType,
          employeeId,
          branchId: result.updatedEmployee.branchId,
          createdBy: req.user!.id,
          summaryText: `Employee updated during contract generation`,
          metadataJson: JSON.stringify({
            source: "contract_generation",
            changes: result.changedFields,
            contractId: result.contract.id,
          }),
        });
      }

      // Log contract creation
      await storage.createActivityLog({
        activityType: "contract_created" as ActivityType,
        employeeId,
        contractInstanceId: result.contract.id,
        branchId: result.updatedEmployee.branchId,
        createdBy: req.user!.id,
        summaryText: `Contract created for ${getEmployeeDisplayName(result.updatedEmployee)}`,
        metadataJson: JSON.stringify({
          templateId,
          templateVersion: template.version,
          employeeVersion: result.updatedEmployee.version,
          hasEmployeeUpdates: Object.keys(result.changedFields).length > 0,
          changedFields: Object.keys(result.changedFields),
        }),
      });

      res.status(201).json({
        contract: finalContract,
        employeeSnapshot: result.employeeSnapshot,
        employeeUpdated: Object.keys(result.changedFields).length > 0,
        changedFields: Object.keys(result.changedFields),
      });
    } catch (error: any) {
      if (error.message === "VERSION_CONFLICT") {
        return res.status(409).json({ 
          message: "Employee was modified by another user during save",
          error: "VERSION_CONFLICT"
        });
      }
      next(error);
    }
  });

  app.post("/api/contracts/finalize", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { employeeId, templateId, mergeDataJson, createdBy, generateSigningLink, language } = req.body;

      const employee = await storage.getEmployee(employeeId);
      if (!employee) {
        return res.status(404).json({ message: "Employee not found" });
      }

      const template = await storage.getTemplate(templateId);
      if (!template) {
        return res.status(404).json({ message: "Template not found" });
      }

      // Get branch for template data, header, and work location derivation
      let branch = null;
      if (employee.branchId) {
        branch = await storage.getBranch(employee.branchId);
      }

      // Derive work location from branch (for backward compatibility)
      const workLocation = branch?.name || mergeDataJson.workLocation || "";

      // Format today's date for the {{today}} and {{document.todays_date}} variables - frozen at finalization time (dd-mm-yyyy)
      const today = new Date();
      const todayFormatted = formatDateDDMMYYYY(today.toISOString());

      let departmentName = "";
      if (employee.primaryDepartmentId) {
        const dept = await storage.getDepartment(employee.primaryDepartmentId);
        if (dept) departmentName = dept.name;
      }

      // Format and bold all variable values for contract display
      const data = {
        employee: {
          full_name: boldValue(employee.fullName),
          email: boldValue(employee.email),
          phone: boldValue(employee.phone || ""),
          address: boldValue(employee.address || ""),
          id_number: boldValue(employee.taxIdNumber || ""),
          department: boldValue(departmentName),
          start_date_employment: boldValue(employee.startDate ? formatDateDDMMYYYY(employee.startDate.toString()) : ""),
          years_of_service: boldValue(employee.startDate ? calculateYearsOfService(employee.startDate) : ""),
        },
        contract: {
          position_title: boldValue(mergeDataJson.positionTitle),
          salary_thb: boldValue(formatCurrency(mergeDataJson.salaryThb)),
          start_date: boldValue(formatDateDDMMYYYY(mergeDataJson.startDate)),
          work_location: boldValue(workLocation),
          food_allowance_per_day: boldValue(employee.foodAllowancePerDay ? formatCurrency(employee.foodAllowancePerDay) : ""),
        },
        branch: branch ? {
          name: boldValue(branch.name),
          address: boldValue(branch.address || ""),
        } : {
          name: "",
          address: "",
        },
        document: {
          todays_date: boldValue(todayFormatted),
        },
        today: boldValue(todayFormatted),
        termination: buildTerminationData(mergeDataJson),
        warning: buildWarningData(mergeDataJson),
        incentive_clause_block: renderIncentiveClauseBlock(mergeDataJson.incentiveClause || employee.incentiveClauseText, employee.foodAllowancePerDay),
        special_terms_block: renderSpecialTermsBlock(mergeDataJson.customClauses),
        visa_sponsorship_block: renderVisaSponsorshipBlock({
          companyHandles: employee.visaWpCompanyHandles || false,
          companyPays: employee.visaWpCompanyPays || false,
          costThb: employee.visaWpCostThb,
          repaymentIfFailProbation: employee.visaWpRepaymentIfFailProbation || false,
          repaymentIfLeaveBefore1y: employee.visaWpRepaymentIfLeaveBefore1y || false,
          repaymentTermsText: employee.visaWpRepaymentTermsText,
          notes: employee.visaWpNotes,
        }),
      };

      const templateBody = (language === "th" && template.htmlBodyTh) ? template.htmlBodyTh : template.htmlBody;
      const templateSnapshotHtml = compileTemplate(templateBody, data);

      // Store the derived work location and today's date in merge data for historical record
      const enhancedMergeData = {
        ...mergeDataJson,
        workLocation,
        todayDate: todayFormatted,
        language: language || "en",
      };

      // Create the contract first
      const contract = await storage.createContract({
        employeeId,
        templateId,
        templateSnapshotHtml,
        templateSnapshotVersion: template.version,
        mergeDataJson: enhancedMergeData,
        status: "draft",
        createdBy: createdBy || req.user!.id,
        pdfPath: null,
        sentToEmail: null,
        branchId: employee.branchId || null,
      });

      // Generate signing link if requested
      let signingToken = null;
      let signingTokenExpiresAt = null;
      if (generateSigningLink) {
        signingToken = crypto.randomUUID();
        signingTokenExpiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000); // 30 days
      }

      // Get the latest published policy to attach to this contract
      const latestPolicy = await storage.getLatestPublishedPolicy();

      // Finalize the contract (no PDF generated - PDF is created when employee signs)
      const finalizedContract = await storage.updateContract(contract.id, {
        status: "finalized",
        finalizedAt: new Date(),
        signingToken,
        signingTokenExpiresAt,
        signingStatus: generateSigningLink ? "awaiting_signature" : "not_sent",
        // Attach policy snapshot if one is published
        policyDocumentId: latestPolicy?.id || null,
        policyVersionInt: latestPolicy?.versionInt || null,
        policyContentHash: latestPolicy?.contentHash || null,
        policyTitleSnapshot: latestPolicy?.title || null,
        policyPublishedAtSnapshot: latestPolicy?.publishedAt || null,
        policyAcknowledged: false,
        policyAcknowledgedAt: null,
      });
      
      // Log contract creation activity
      try {
        await storage.createActivityLog({
          branchId: employee.branchId || null,
          employeeId: employee.id,
          contractInstanceId: finalizedContract.id,
          activityType: "contract_created",
          summaryText: `Contract created for ${getEmployeeDisplayName(employee)} - ${mergeDataJson.positionTitle}`,
          createdBy: req.user?.id || null,
        });
      } catch (logError) {
        console.error("Failed to log activity:", logError);
      }

      // Clear any CHANGE_NO_CONTRACT attention items for this employee
      try {
        await storage.deleteAttentionItemsByType("CHANGE_NO_CONTRACT", employee.id);
      } catch (attentionError) {
        console.error("Failed to clear attention items:", attentionError);
      }

      // Trigger attention engine for new contract
      evaluateForContract(finalizedContract.id).catch(err => console.error("[AttentionEngine] Contract finalize trigger failed:", err));
      evaluateForEmployee(employee.id).catch(err => console.error("[AttentionEngine] Contract finalize employee trigger failed:", err));

      res.status(201).json(finalizedContract);
    } catch (error) {
      next(error);
    }
  });

  app.post("/api/contracts/:id/finalize", requireAuth, requireManager, async (req, res, next) => {
    try {
      const contract = await storage.getContract(req.params.id);
      if (!contract) {
        return res.status(404).json({ message: "Contract not found" });
      }

      if (contract.status !== "draft") {
        return res.status(400).json({ message: "Contract is already finalized" });
      }

      // No PDF generated at finalize - PDF is created when employee signs
      const finalizedContract = await storage.updateContract(contract.id, {
        status: "finalized",
        finalizedAt: new Date(),
      });

      // Trigger attention engine for finalized contract
      evaluateForContract(contract.id).catch(err => console.error("[AttentionEngine] Contract finalize trigger failed:", err));

      res.json(finalizedContract);
    } catch (error) {
      next(error);
    }
  });

  app.post("/api/contracts/:id/send", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { to, subject, body } = req.body;

      const contract = await storage.getContract(req.params.id);
      if (!contract) {
        return res.status(404).json({ message: "Contract not found" });
      }

      if (contract.status !== "finalized") {
        return res.status(400).json({ message: "Contract must be finalized before sending" });
      }

      if (!contract.pdfPath) {
        return res.status(400).json({ message: "Contract PDF not found" });
      }

      const result = await sendEmail({
        to,
        subject,
        body,
        attachmentPath: contract.pdfPath,
      });

      if (!result.success) {
        const failedContract = await storage.updateContract(contract.id, {
          status: "failed",
        });
        return res.status(500).json({ message: result.error || "Failed to send email" });
      }

      const sentContract = await storage.updateContract(contract.id, {
        status: "sent",
        sentToEmail: to,
        sentAt: new Date(),
        emailMessageId: result.messageId,
      });
      
      // Log contract sent activity
      try {
        const employee = await storage.getEmployee(contract.employeeId);
        await storage.createActivityLog({
          branchId: contract.branchId || null,
          employeeId: contract.employeeId,
          contractInstanceId: contract.id,
          activityType: "contract_sent",
          summaryText: `Contract sent to ${getEmployeeDisplayName(employee)} at ${to}`,
          createdBy: req.user?.id || null,
        });
      } catch (logError) {
        console.error("Failed to log activity:", logError);
      }

      // Trigger attention engine for sent contract
      evaluateForContract(contract.id).catch(err => console.error("[AttentionEngine] Contract send trigger failed:", err));

      res.json(sentContract);
    } catch (error) {
      next(error);
    }
  });

  app.get("/api/contracts/:id/pdf", requireAuth, async (req, res, next) => {
    try {
      const contract = await storage.getContract(req.params.id);
      if (!contract) {
        return res.status(404).json({ message: "Contract not found" });
      }
      const employee = await storage.getEmployee(contract.employeeId);
      if (!employee || !req.userWithAccess || !canUserAccessBranch(req.userWithAccess, employee.branchId)) {
        return res.status(403).json({ message: "Access denied to this contract" });
      }
      if (!contract.pdfPath) {
        return res.status(404).json({ message: "PDF not found" });
      }
      if (isObjectStoragePath(contract.pdfPath)) {
        const url = await presignedPdfUrl(contract.pdfPath, `contract_${contract.id}.pdf`);
        if (!url) return res.status(404).json({ message: "PDF not found" });
        res.setHeader("Cache-Control", "private, no-store");
        return res.redirect(302, url);
      }
      const localPath = contract.pdfPath.startsWith("/uploads/")
        ? path.join(process.cwd(), contract.pdfPath.slice(1))
        : contract.pdfPath;
      if (!fs.existsSync(localPath)) return res.status(404).json({ message: "PDF not found" });
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename=contract_${contract.id}.pdf`);
      fs.createReadStream(localPath).pipe(res);
    } catch (error) {
      next(error);
    }
  });

