  // Scheduler endpoint for daily LEAVING -> LEFT transitions
  app.post("/api/scheduler/transition-left", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const userId = (req.user as any).id;
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      const leavingEmployees = await storage.getEmployeesInLeavingState();
      const transitioned: string[] = [];

      for (const employee of leavingEmployees) {
        if (employee.lastWorkingDay) {
          const lastDay = new Date(employee.lastWorkingDay);
          lastDay.setHours(0, 0, 0, 0);
          
          if (lastDay < today) {
            await storage.updateEmployeeState(employee.id, 'LEFT');
            await storage.logActivity({
              branchId: employee.branchId || undefined,
              employeeId: employee.id,
              activityType: "employment_state_changed",
              summaryText: `${getEmployeeDisplayName(employee)} employment state changed from LEAVING to LEFT`,
              createdBy: userId,
            });
            transitioned.push(employee.id);
          }
        }
      }

      res.json({ 
        message: `Transitioned ${transitioned.length} employee(s) from LEAVING to LEFT`,
        transitionedEmployees: transitioned 
      });
    } catch (error) {
      next(error);
    }
  });

