  // Enrollment session - Generate QR token for employee face enrollment
  // Advisors use an independent enrollment/session model because they are people,
  // not employees. Their access policy is the source of tenant and branch scope.
  app.post("/api/people/:personId/advisor-enrollment-session", requireAuth, requireManager, async (req, res, next) => {
    try {
      const [advisor] = await db.select({ person: people, policy: accessPolicies })
        .from(people).innerJoin(accessPolicies, eq(accessPolicies.personId, people.id))
        .where(and(eq(people.id, req.params.personId), eq(people.personType, "ADVISOR"))).limit(1);
      if (!advisor) return res.status(404).json({ message: "Advisor not found" });
      const manager = req.user as any;
      const managerTenantId = await resolveTenantId(manager.tenantId);
      const managerBranches = await storage.getUserBranchAccess(manager.id);
      const managerHasAllBranches = managerBranches.some(access => access.accessScope === "all_branches");
      const managerBranchIds = managerBranches.flatMap(access => access.branchId ? [access.branchId] : []);
      const advisorBranchIds = advisor.policy.branchScope === "ALL"
        ? await storage.getBranches().then(items => items.filter(item => item.tenantId === advisor.policy.tenantId).map(item => item.id))
        : advisor.policy.branchIds || [];
      if (advisor.policy.tenantId !== managerTenantId || (!managerHasAllBranches && !advisorBranchIds.some(id => managerBranchIds.includes(id)))) {
        return res.status(403).json({ message: "Access denied to advisor enrollment" });
      }
      const token = crypto.randomBytes(32).toString("hex");
      const [session] = await db.insert(advisorEnrollmentSessions).values({
        personId: advisor.person.id, tokenHash: crypto.createHash("sha256").update(token).digest("hex"),
        expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000), createdBy: (req.user as any).id,
      }).returning();
      res.status(201).json({ sessionId: session.id, token, expiresAt: session.expiresAt, identityType: "ADVISOR" });
    } catch (error) { next(error); }
  });

