  // POST /api/sick-leave-policy - Create or update sick leave policy (admin only)
  const sickLeavePolicySchema = z.object({
    branchId: z.string().uuid().optional().nullable(),
    annualSickLeaveDays: z.number().int().min(1).max(365).optional().default(30),
    proRateByStartDate: z.boolean().optional().default(true),
    yearStartMonth: z.number().int().min(1).max(12).optional().default(1),
  });

  app.post("/api/sick-leave-policy", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const parsed = sickLeavePolicySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ message: "Invalid input", errors: parsed.error.flatten() });
      }
      
      const { branchId, annualSickLeaveDays, proRateByStartDate, yearStartMonth } = parsed.data;
      const tenantId = await resolveTenantId(req.user?.tenantId);
      
      // Get or create the policy (tenant-wide if no branchId, or branch-specific)
      let policy = await storage.getSickLeavePolicy(branchId ?? undefined);
      
      if (policy) {
        // Update existing policy
        policy = await storage.updateSickLeavePolicy(policy.id, {
          annualSickLeaveDays,
          proRateByStartDate,
          yearStartMonth,
        });
      } else {
        // Create new policy
        policy = await storage.getOrCreateSickLeavePolicy(tenantId, branchId ?? undefined);
        policy = await storage.updateSickLeavePolicy(policy.id, {
          annualSickLeaveDays,
          proRateByStartDate,
          yearStartMonth,
        });
      }
      
      res.json(policy);
    } catch (error) {
      next(error);
    }
  });

