  // ============================================
  // STUDIO EVENTS (Birthday Parties, etc.)
  // ============================================

  // Get studio events with optional filtering
  // GET /api/admin/events?range=upcoming|today|past|all&includeArchived=true
  app.get("/api/admin/events", requireAuth, async (req, res, next) => {
    try {
      const { range, branchId, includeArchived } = req.query;
      const tenantId = await getDefaultTenantId();
      console.log("[Events] GET /api/admin/events called:", { range, branchId, includeArchived, userId: req.user?.id });
      
      const events = await storage.getStudioEvents({
        tenantId,
        branchId: branchId as string,
        range: range as "upcoming" | "today" | "past" | "all",
        includeArchived: includeArchived === "true",
      });
      console.log("[Events] Found", events.length, "events for range:", range);
      
      // Fetch party host assignments for events
      const eventIds = events.map(e => e.id);
      const partyHostAssignments = eventIds.length > 0 
        ? await db.select().from(beoPartyHostAssignments).where(inArray(beoPartyHostAssignments.eventId, eventIds))
        : [];
      
      // Batch resolve party host and entertainment host employee/user names.
      // The BEO editor stores the optional Entertainment Host in the party host
      // assignment's backup employee/user fields.
      const employeeIds = partyHostAssignments
        .flatMap(ph => [ph.assignedEmployeeId, ph.backupEmployeeId])
        .filter(Boolean) as string[];
      const userIds = partyHostAssignments
        .flatMap(ph => [ph.assignedUserId, ph.resolvedUserId, ph.backupUserId])
        .filter(Boolean) as string[];
      
      const employeeMap = new Map<string, string>();
      const userMap = new Map<string, string>();
      
      if (employeeIds.length > 0) {
        const employeeRecords = await db.select().from(employees).where(inArray(employees.id, employeeIds));
        for (const emp of employeeRecords) {
          employeeMap.set(emp.id, emp.nickname || emp.fullName || "");
        }
      }
      
      if (userIds.length > 0) {
        const userRecords = await db.select().from(users).where(inArray(users.id, userIds));
        for (const user of userRecords) {
          userMap.set(user.id, user.fullName || "");
        }
      }
      
      // Build event -> assigned host mapping, preserving responsibility labels.
      const assignedHostsMap = new Map<string, Array<{ name: string; role: "host" | "entertainment" }>>();
      for (const ph of partyHostAssignments) {
        const assignedHosts = assignedHostsMap.get(ph.eventId) || [];
        let partyHostName = "";
        if (ph.assignedEmployeeId && employeeMap.has(ph.assignedEmployeeId)) {
          partyHostName = employeeMap.get(ph.assignedEmployeeId)!;
        } else if (ph.assignedUserId && userMap.has(ph.assignedUserId)) {
          partyHostName = userMap.get(ph.assignedUserId)!;
        } else if (ph.resolvedUserId && userMap.has(ph.resolvedUserId)) {
          partyHostName = userMap.get(ph.resolvedUserId)!;
        }
        if (partyHostName) {
          assignedHosts.push({ name: partyHostName, role: "host" });
        }

        let entertainmentHostName = "";
        if (ph.backupEmployeeId && employeeMap.has(ph.backupEmployeeId)) {
          entertainmentHostName = employeeMap.get(ph.backupEmployeeId)!;
        } else if (ph.backupUserId && userMap.has(ph.backupUserId)) {
          entertainmentHostName = userMap.get(ph.backupUserId)!;
        }
        if (entertainmentHostName) {
          assignedHosts.push({ name: entertainmentHostName, role: "entertainment" });
        }

        if (assignedHosts.length > 0) {
          assignedHostsMap.set(ph.eventId, assignedHosts);
        }
      }
      
      // Fetch billing data for birthday/private events
      const billingRecords = eventIds.length > 0
        ? await db.select().from(beoEventBilling).where(inArray(beoEventBilling.eventId, eventIds))
        : [];
      const billingMap = new Map(billingRecords.map(b => [b.eventId, b]));

      // Fetch booking payment totals (amountPaid) per event — this is the real "deposit" shown in BEO/POS
      const bookingPayments = eventIds.length > 0
        ? await db.select({ eventId: studioEventBookings.eventId, amountPaid: studioEventBookings.amountPaid })
            .from(studioEventBookings)
            .where(inArray(studioEventBookings.eventId, eventIds))
        : [];
      const bookingTotalPaidMap = new Map<string, number>();
      for (const b of bookingPayments) {
        bookingTotalPaidMap.set(b.eventId, (bookingTotalPaidMap.get(b.eventId) || 0) + (b.amountPaid || 0));
      }

      // Fetch line items to calculate totals per event
      const allLineItems = eventIds.length > 0
        ? await db.select({
            eventId: eventLineItems.eventId,
            qty: eventLineItems.qty,
            unitPriceIncVat: eventLineItems.unitPriceIncVat,
            isIncluded: eventLineItems.isIncluded,
          }).from(eventLineItems).where(inArray(eventLineItems.eventId, eventIds))
        : [];
      const lineItemTotalsMap = new Map<string, number>();
      for (const li of allLineItems) {
        if (!li.isIncluded) {
          const subtotal = (li.qty || 1) * (li.unitPriceIncVat || 0);
          lineItemTotalsMap.set(li.eventId, (lineItemTotalsMap.get(li.eventId) || 0) + subtotal);
        }
      }

      // Fetch BEO section completion data for progress bars
      const [setupPlans, kitchenPlans, timelineItems, packageSnapshots, entertainmentSels] = await Promise.all([
        eventIds.length > 0 ? db.select({ eventId: beoSetupPlans.eventId, setupRequired: beoSetupPlans.setupRequired }).from(beoSetupPlans).where(inArray(beoSetupPlans.eventId, eventIds)) : [],
        eventIds.length > 0 ? db.select({ eventId: beoKitchenPlans.eventId, foodRequired: beoKitchenPlans.foodRequired }).from(beoKitchenPlans).where(inArray(beoKitchenPlans.eventId, eventIds)) : [],
        eventIds.length > 0 ? db.select({ eventId: beoTimelineItems.eventId }).from(beoTimelineItems).where(inArray(beoTimelineItems.eventId, eventIds)) : [],
        eventIds.length > 0 ? db.select({ eventId: beoPackageSnapshots.eventId }).from(beoPackageSnapshots).where(inArray(beoPackageSnapshots.eventId, eventIds)) : [],
        eventIds.length > 0 ? db.select({ eventId: beoEntertainmentSelections.eventId }).from(beoEntertainmentSelections).where(inArray(beoEntertainmentSelections.eventId, eventIds)) : [],
      ]);

      const setupPlanSet = new Set(setupPlans.map(s => s.eventId));
      const kitchenPlanSet = new Set(kitchenPlans.map(k => k.eventId));
      const timelineEventIds = new Set(timelineItems.map(t => t.eventId));
      const packageSnapshotSet = new Set(packageSnapshots.map(p => p.eventId));
      const entertainmentSelSet = new Set(entertainmentSels.map(e => e.eventId));
      
      // Add assigned host names, billing data, and section progress to events
      const eventsWithPartyHost = events.map(event => {
        const billing = billingMap.get(event.id);
        const isBirthday = event.eventType === "birthday" || event.eventType === "private_event";

        const billingAddOns = (billing as any)?.addOns;
        const hasPartyDetails = !!(billingAddOns?.partyDetails?.packageName);
        const sectionProgress = isBirthday ? {
          info: !!(event.eventDate && event.startTime && (event as any).childName && (event as any).bookingName && (event.locationId || (event as any).locationText) && ((event as any).numChildren || 0) > 0 && ((event as any).numAdults || 0) > 0),
          host: partyHostAssignments.some(ph => ph.eventId === event.id && ph.assignedEmployeeId),
          package: packageSnapshotSet.has(event.id) || hasPartyDetails,
          entertainment: entertainmentSelSet.has(event.id),
          setup: setupPlanSet.has(event.id),
          kitchen: kitchenPlanSet.has(event.id),
          billing: !!(billing && (((billing as any).depositPaidAmount || 0) > 0 || (billingAddOns?.partyDetails?.prepaymentReceived || 0) > 0)),
          timeline: timelineEventIds.has(event.id),
        } : undefined;

        return {
          ...event,
          // Keep the existing field for other admin-event consumers while
          // exposing the role-aware list for the Studio calendar.
          partyHostName: assignedHostsMap.get(event.id)?.find(host => host.role === "host")?.name || undefined,
          assignedHosts: assignedHostsMap.get(event.id) || undefined,
          billing: billing || lineItemTotalsMap.has(event.id) || bookingTotalPaidMap.has(event.id) ? {
            depositRequired: billing?.depositRequired,
            depositAmount: billing?.depositAmount,
            depositPaid: billing?.depositPaid,
            depositPaidAmount: billing?.depositPaidAmount,
            depositPaidAt: billing?.depositPaidAt,
            depositPaymentMethod: billing?.depositPaymentMethod,
            totalCalculated: lineItemTotalsMap.get(event.id) || billing?.totalCalculated || 0,
            packagePrice: billing?.packagePrice,
            totalAmountPaid: bookingTotalPaidMap.get(event.id) || 0,
            prepaymentReceived: Number((billing as any)?.addOns?.partyDetails?.prepaymentReceived) || 0,
            depositDate: (billing as any)?.addOns?.partyDetails?.depositDate || null,
          } : undefined,
          sectionProgress,
        };
      });
      
      res.json(eventsWithPartyHost);
    } catch (error) {
      next(error);
    }
  });

  // Get a single studio event
  app.get("/api/admin/events/:id", requireAuth, async (req, res, next) => {
    try {
      const { id } = req.params;
      const event = await storage.getStudioEvent(id);
      
      if (!event) {
        return res.status(404).json({ message: "Event not found" });
      }
      
      res.json(event);
    } catch (error) {
      next(error);
    }
  });

  // Create a studio event
  app.post("/api/admin/events", requireAuth, requireManager, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const user = req.user as UserWithBranchAccess;
      
      // Get user's first branch as default if not provided
      let branchId = req.body.branchId;
      if (!branchId && user.branchAccess && user.branchAccess.length > 0) {
        branchId = user.branchAccess[0].branchId;
      }
      
      if (!branchId) {
        return res.status(400).json({ message: "branchId is required" });
      }
      
      if (req.body.eventType === "studio_event" && req.body.color !== undefined && !isOtherEventColor(req.body.color)) {
        return res.status(400).json({ message: "Other Event color must be selected from the available calendar colors" });
      }
      const eventData = {
        ...req.body,
        ...(req.body.eventType === "workshop" ? { color: null } : {}),
        tenantId,
        branchId,
        createdByUserId: user.id,
        updatedByUserId: user.id,
      };
      
      const event = await storage.createStudioEvent(eventData);
      res.status(201).json(event);
    } catch (error) {
      next(error);
    }
  });

  // Update a studio event
  app.patch("/api/admin/events/:id", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { id } = req.params;
      const user = req.user as UserWithBranchAccess;
      
      const existingEvent = await storage.getStudioEvent(id);
      if (!existingEvent) {
        return res.status(404).json({ message: "Event not found" });
      }
      
      const effectiveEventType = req.body.eventType ?? existingEvent.eventType;
      const isSavedLegacyColor = isHexCalendarColor(req.body.color)
        && typeof existingEvent.color === "string"
        && existingEvent.color.toLowerCase() === req.body.color.toLowerCase();
      if (
        effectiveEventType === "studio_event"
        && req.body.color !== undefined
        && !isOtherEventColor(req.body.color)
        && !isSavedLegacyColor
      ) {
        return res.status(400).json({ message: "Other Event color must be selected from the available calendar colors" });
      }
      const eventData = {
        ...req.body,
        ...(req.body.eventType === "workshop" ? { color: null } : {}),
        updatedByUserId: user.id,
      };
      
      const event = await storage.updateStudioEvent(id, eventData);
      res.json(event);
    } catch (error) {
      next(error);
    }
  });

  // Archive/unarchive a studio event
  app.post("/api/admin/events/:id/archive", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { id } = req.params;
      const { archived } = req.body;
      const user = req.user as UserWithBranchAccess;
      
      const existingEvent = await storage.getStudioEvent(id);
      if (!existingEvent) {
        return res.status(404).json({ message: "Event not found" });
      }
      
      const event = await storage.updateStudioEvent(id, {
        isArchived: archived !== false,
        archivedAt: archived !== false ? new Date() : null,
        updatedByUserId: user.id,
      } as any);
      res.json(event);
    } catch (error) {
      next(error);
    }
  });

  // Delete a studio event
  app.delete("/api/admin/events/:id", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { id } = req.params;
      
      const existingEvent = await storage.getStudioEvent(id);
      if (!existingEvent) {
        return res.status(404).json({ message: "Event not found" });
      }
      
      await storage.deleteStudioEvent(id);
      res.status(204).send();
    } catch (error) {
      next(error);
    }
  });

