  // Admin: update attendance days for a camp registration
  app.patch("/api/events/:eventId/camp-registrations/:registrationId/attendance-days", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { eventId, registrationId } = req.params;
      const tenantId = await getDefaultTenantId();
      const userId = (req.user as any)?.id;

      const { addDates, removeDates } = req.body as { addDates?: string[]; removeDates?: string[] };
      const toAdd: string[] = Array.isArray(addDates) ? addDates : [];
      const toRemove: string[] = Array.isArray(removeDates) ? removeDates : [];

      // Validate date format (YYYY-MM-DD)
      const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
      for (const d of [...toAdd, ...toRemove]) {
        if (!dateRegex.test(d)) return res.status(400).json({ message: `Invalid date format: ${d}` });
      }

      // Fetch the registration
      const [reg] = await db
        .select({ id: campRegistrations.id, attendanceDays: campRegistrations.attendanceDays, childFullName: campRegistrations.childFullName, eventId: campRegistrations.eventId, tenantId: campRegistrations.tenantId })
        .from(campRegistrations)
        .where(and(
          eq(campRegistrations.id, registrationId),
          eq(campRegistrations.eventId, eventId),
          eq(campRegistrations.tenantId, tenantId),
        ));
      if (!reg) return res.status(404).json({ message: "Registration not found" });

      const currentDays: string[] = Array.isArray(reg.attendanceDays) ? reg.attendanceDays : [];

      // For removed dates — check none already have a non-waiting attendance record
      if (toRemove.length > 0) {
        const attendedRows = await db
          .select({ attendanceDate: campAttendance.attendanceDate, status: campAttendance.status })
          .from(campAttendance)
          .where(and(
            eq(campAttendance.campRegistrationId, registrationId),
            inArray(campAttendance.attendanceDate, toRemove),
          ));
        const blocked = attendedRows.filter((r) => r.status !== "waiting").map((r) => r.attendanceDate);
        if (blocked.length > 0) {
          return res.status(422).json({ message: `Cannot remove dates already attended: ${blocked.join(", ")}` });
        }
      }

      // Compute new attendanceDays
      const afterRemove = currentDays.filter((d) => !toRemove.includes(d));
      const afterAdd = [...new Set([...afterRemove, ...toAdd])];
      afterAdd.sort();

      // Update registration
      await db
        .update(campRegistrations)
        .set({ attendanceDays: afterAdd, updatedAt: new Date() })
        .where(eq(campRegistrations.id, registrationId));

      // Create camp_attendance rows for added dates (status=waiting), skip if already exists
      if (toAdd.length > 0) {
        await db
          .insert(campAttendance)
          .values(
            toAdd.map((d) => ({
              campRegistrationId: registrationId,
              tenantId,
              eventId,
              attendanceDate: d,
              status: "waiting" as const,
            }))
          )
          .onConflictDoNothing();
      }

      // Delete waiting-only attendance rows for removed dates
      if (toRemove.length > 0) {
        await db
          .delete(campAttendance)
          .where(and(
            eq(campAttendance.campRegistrationId, registrationId),
            inArray(campAttendance.attendanceDate, toRemove),
            sql`${campAttendance.status} = 'waiting'`,
          ));
      }

      // Log activity
      const staffUser = req.user as any;
      const staffName = staffUser?.fullName || staffUser?.email || "Staff";
      const parts: string[] = [];
      if (toAdd.length > 0) parts.push(`added ${toAdd.join(", ")}`);
      if (toRemove.length > 0) parts.push(`removed ${toRemove.join(", ")}`);
      await storage.createActivityLog({
        activityType: "camp_attendance_days_updated",
        createdBy: userId || null,
        summaryText: `${staffName} updated attendance days for ${reg.childFullName}: ${parts.join("; ")}`,
      });

      res.json({ attendanceDays: afterAdd });
    } catch (error) {
      next(error);
    }
  });

  // Admin: update profile fields for a camp registration (with cross-registration sync)
  app.patch("/api/events/:eventId/camp-registrations/:regId", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { eventId, regId } = req.params;
      const tenantId = await getDefaultTenantId();
      const userId = (req.user as any)?.id;

      const profileSchema = z.object({
        childFullName: z.string().min(1).optional(),
        dateOfBirth: z.string().optional(),
        primaryLanguage: z.string().nullable().optional(),
        allergies: z.string().nullable().optional(),
        foodRestrictions: z.string().nullable().optional(),
        behavioralNotes: z.string().nullable().optional(),
        specialNotes: z.string().nullable().optional(),
        authorizedPickupPersons: z.string().nullable().optional(),
        parentGuardianName: z.string().min(1).optional(),
        emergencyContactNumber: z.string().min(1).optional(),
        childPhotoUrl: z.string().nullable().optional(),
      });

      const parsed = profileSchema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ message: "Invalid fields", errors: parsed.error.flatten() });

      const fields = parsed.data;

      // Fetch registration to verify it exists and get current phone/name for sync
      const [reg] = await db
        .select({
          id: campRegistrations.id,
          tenantId: campRegistrations.tenantId,
          childFullName: campRegistrations.childFullName,
          emergencyContactNumber: campRegistrations.emergencyContactNumber,
        })
        .from(campRegistrations)
        .where(and(
          eq(campRegistrations.id, regId),
          eq(campRegistrations.eventId, eventId),
          eq(campRegistrations.tenantId, tenantId),
        ));

      if (!reg) return res.status(404).json({ message: "Registration not found" });

      const now = new Date();

      // Build update payload — only include provided fields
      const updatePayload: Record<string, any> = { updatedAt: now };
      if (fields.childFullName !== undefined) updatePayload.childFullName = fields.childFullName.trim();
      if (fields.dateOfBirth !== undefined) updatePayload.dateOfBirth = fields.dateOfBirth;
      if (fields.primaryLanguage !== undefined) updatePayload.primaryLanguage = fields.primaryLanguage?.trim() || null;
      if (fields.allergies !== undefined) updatePayload.allergies = fields.allergies?.trim() || null;
      if (fields.foodRestrictions !== undefined) updatePayload.foodRestrictions = fields.foodRestrictions?.trim() || null;
      if (fields.behavioralNotes !== undefined) updatePayload.behavioralNotes = fields.behavioralNotes?.trim() || null;
      if (fields.specialNotes !== undefined) updatePayload.specialNotes = fields.specialNotes?.trim() || null;
      if (fields.authorizedPickupPersons !== undefined) updatePayload.authorizedPickupPersons = fields.authorizedPickupPersons?.trim() || null;
      if (fields.parentGuardianName !== undefined) updatePayload.parentGuardianName = fields.parentGuardianName.trim();
      if (fields.emergencyContactNumber !== undefined) updatePayload.emergencyContactNumber = fields.emergencyContactNumber.trim();
      if (fields.childPhotoUrl !== undefined) updatePayload.childPhotoUrl = fields.childPhotoUrl || null;

      // Update the primary registration
      const [updated] = await db
        .update(campRegistrations)
        .set(updatePayload)
        .where(and(
          eq(campRegistrations.id, regId),
          eq(campRegistrations.tenantId, tenantId),
        ))
        .returning();

      // Sync profile fields to other registrations for the same child + phone across all camps.
      // Always match siblings using the PRE-UPDATE name + phone so renaming or phone changes
      // still find and update the correct sibling rows.
      const profileSyncPayload: Record<string, any> = { updatedAt: now };
      const syncFields = [
        "childFullName", "dateOfBirth", "primaryLanguage", "allergies", "foodRestrictions",
        "behavioralNotes", "specialNotes", "authorizedPickupPersons", "parentGuardianName",
        "emergencyContactNumber", "childPhotoUrl",
      ] as const;
      for (const k of syncFields) {
        if (updatePayload[k] !== undefined) profileSyncPayload[k] = updatePayload[k];
      }

      if (Object.keys(profileSyncPayload).length > 1) {
        // Use the original (pre-update) name and phone as stable match keys
        const matchName = reg.childFullName.trim().toLowerCase();
        const matchPhone = reg.emergencyContactNumber.trim();

        await db
          .update(campRegistrations)
          .set(profileSyncPayload)
          .where(and(
            eq(campRegistrations.tenantId, tenantId),
            eq(campRegistrations.emergencyContactNumber, matchPhone),
            sql`lower(trim(${campRegistrations.childFullName})) = ${matchName}`,
            ne(campRegistrations.id, regId),
          ));
      }

      // Log activity
      const staffUser = req.user as any;
      const staffName = staffUser?.fullName || staffUser?.email || "Staff";
      await storage.createActivityLog({
        activityType: "camp_registration_updated",
        createdBy: userId || null,
        summaryText: `${staffName} updated profile for ${updated.childFullName}`,
      });

      res.json(updated);
    } catch (error) {
      next(error);
    }
  });

