  // Search existing children across all camps (excludes one-time profiles)
  app.get("/api/admin/camp-children/search", requireAuth, requireManager, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const { q } = req.query as { q?: string };
      if (!q || q.trim().length < 2) {
        return res.json([]);
      }
      const term = `%${q.trim().toLowerCase()}%`;

      const rows = await db
        .select({
          id: campRegistrations.id,
          childFullName: campRegistrations.childFullName,
          dateOfBirth: campRegistrations.dateOfBirth,
          primaryLanguage: campRegistrations.primaryLanguage,
          childPhotoUrl: campRegistrations.childPhotoUrl,
          parentGuardianName: campRegistrations.parentGuardianName,
          emergencyContactNumber: campRegistrations.emergencyContactNumber,
          allergies: campRegistrations.allergies,
          foodRestrictions: campRegistrations.foodRestrictions,
          behavioralNotes: campRegistrations.behavioralNotes,
          specialNotes: campRegistrations.specialNotes,
          authorizedPickupPersons: campRegistrations.authorizedPickupPersons,
          eventId: campRegistrations.eventId,
          createdAt: campRegistrations.createdAt,
        })
        .from(campRegistrations)
        .where(and(
          eq(campRegistrations.tenantId, tenantId),
          sql`${campRegistrations.isOneTime} = false`,
          or(
            sql`lower(${campRegistrations.childFullName}) like ${term}`,
            sql`lower(${campRegistrations.parentGuardianName}) like ${term}`,
            sql`lower(${campRegistrations.emergencyContactNumber}) like ${term}`,
          )
        ))
        .orderBy(desc(campRegistrations.createdAt))
        .limit(50);

      // Deduplicate: one record per (childFullName, emergencyContactNumber) keeping the most recent
      const seen = new Map<string, typeof rows[0]>();
      for (const row of rows) {
        const key = `${row.childFullName.trim().toLowerCase()}||${row.emergencyContactNumber.trim()}`;
        if (!seen.has(key)) {
          seen.set(key, row);
        }
      }

      res.json(Array.from(seen.values()));
    } catch (error) {
      next(error);
    }
  });

  // GET /api/admin/children — deduplicated list of all children across all camps
  app.get("/api/admin/children", requireAuth, requireManager, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const { search, page, limit: limitParam } = req.query as { search?: string; page?: string; limit?: string };
      const pageNum = Math.max(1, parseInt(page || "1", 10));
      const pageSize = Math.min(100, Math.max(1, parseInt(limitParam || "50", 10)));

      // Build where conditions
      const conditions: any[] = [
        eq(campRegistrations.tenantId, tenantId),
        sql`${campRegistrations.isOneTime} = false`,
      ];

      if (search && search.trim().length >= 1) {
        const term = `%${search.trim().toLowerCase()}%`;
        conditions.push(
          or(
            sql`lower(${campRegistrations.childFullName}) like ${term}`,
            sql`lower(${campRegistrations.parentGuardianName}) like ${term}`,
            sql`lower(${campRegistrations.emergencyContactNumber}) like ${term}`,
          )
        );
      }

      // Fetch all matching rows, ordered newest first
      const rows = await db
        .select({
          id: campRegistrations.id,
          childFullName: campRegistrations.childFullName,
          dateOfBirth: campRegistrations.dateOfBirth,
          primaryLanguage: campRegistrations.primaryLanguage,
          childPhotoUrl: campRegistrations.childPhotoUrl,
          parentGuardianName: campRegistrations.parentGuardianName,
          emergencyContactNumber: campRegistrations.emergencyContactNumber,
          parentContacts: campRegistrations.parentContacts,
          allergies: campRegistrations.allergies,
          foodRestrictions: campRegistrations.foodRestrictions,
          behavioralNotes: campRegistrations.behavioralNotes,
          specialNotes: campRegistrations.specialNotes,
          authorizedPickupPersons: campRegistrations.authorizedPickupPersons,
          createdAt: campRegistrations.createdAt,
          updatedAt: campRegistrations.updatedAt,
        })
        .from(campRegistrations)
        .where(and(...conditions))
        .orderBy(desc(campRegistrations.updatedAt));

      // Deduplicate: one record per (childFullName.lower, emergencyContactNumber) keeping most-recently-updated
      const seen = new Map<string, typeof rows[0]>();
      for (const row of rows) {
        const key = `${row.childFullName.trim().toLowerCase()}||${row.emergencyContactNumber.trim()}`;
        if (!seen.has(key)) {
          seen.set(key, row);
        }
      }

      const allChildren = Array.from(seen.values());
      const total = allChildren.length;
      const paginated = allChildren.slice((pageNum - 1) * pageSize, pageNum * pageSize);

      res.json({ children: paginated, total, page: pageNum, pageSize });
    } catch (error) {
      next(error);
    }
  });

  // GET /api/admin/children/duplicates — scan for likely duplicate child profiles
  app.get("/api/admin/children/duplicates", requireAuth, requireManager, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();

      // Fetch all non-one-time registrations; we'll deduplicate in JS
      const rows = await db
        .select({
          id: campRegistrations.id,
          childFullName: campRegistrations.childFullName,
          dateOfBirth: campRegistrations.dateOfBirth,
          primaryLanguage: campRegistrations.primaryLanguage,
          childPhotoUrl: campRegistrations.childPhotoUrl,
          parentGuardianName: campRegistrations.parentGuardianName,
          emergencyContactNumber: campRegistrations.emergencyContactNumber,
          allergies: campRegistrations.allergies,
          foodRestrictions: campRegistrations.foodRestrictions,
          behavioralNotes: campRegistrations.behavioralNotes,
          specialNotes: campRegistrations.specialNotes,
          authorizedPickupPersons: campRegistrations.authorizedPickupPersons,
          updatedAt: campRegistrations.updatedAt,
        })
        .from(campRegistrations)
        .where(and(
          eq(campRegistrations.tenantId, tenantId),
          sql`${campRegistrations.isOneTime} = false`,
        ))
        .orderBy(desc(campRegistrations.updatedAt));

      // Deduplicate: one record per (name, phone) keeping most-recently-updated
      // Also tally registration count per profile key
      const seen = new Map<string, typeof rows[0]>();
      const countMap = new Map<string, number>();
      for (const row of rows) {
        const key = `${row.childFullName.trim().toLowerCase()}||${row.emergencyContactNumber.trim()}`;
        countMap.set(key, (countMap.get(key) ?? 0) + 1);
        if (!seen.has(key)) seen.set(key, row);
      }
      const children = Array.from(seen.entries()).map(([key, row]) => ({
        ...row,
        registrationCount: countMap.get(key) ?? 1,
      }));

      // Dice-coefficient similarity on character bigrams (good for name fuzzy matching)
      const diceSimilarity = (s1: string, s2: string): number => {
        if (s1 === s2) return 1;
        if (s1.length < 2 || s2.length < 2) return 0;
        const bigrams = (s: string): Set<string> => {
          const b = new Set<string>();
          for (let i = 0; i < s.length - 1; i++) b.add(s.slice(i, i + 2));
          return b;
        };
        const b1 = bigrams(s1);
        const b2 = bigrams(s2);
        let intersection = 0;
        for (const b of b1) { if (b2.has(b)) intersection++; }
        return (2 * intersection) / (b1.size + b2.size);
      };

      // Find candidate duplicate pairs
      const pairs: Array<{ a: typeof rows[0]; b: typeof rows[0]; similarity: number }> = [];
      for (let i = 0; i < children.length; i++) {
        for (let j = i + 1; j < children.length; j++) {
          const a = children[i];
          const b = children[j];
          const nameA = a.childFullName.trim().toLowerCase();
          const nameB = b.childFullName.trim().toLowerCase();
          const sim = diceSimilarity(nameA, nameB);
          if (sim < 0.60) continue;

          // DOB proximity check: only exclude if both are present AND differ by > 365 days
          if (a.dateOfBirth && b.dateOfBirth) {
            const diffMs = Math.abs(new Date(a.dateOfBirth).getTime() - new Date(b.dateOfBirth).getTime());
            const diffDays = diffMs / (1000 * 60 * 60 * 24);
            if (diffDays > 365) continue;
          }

          pairs.push({ a, b, similarity: sim });
        }
      }

      // Sort by similarity descending, cap at 100 pairs
      pairs.sort((x, y) => y.similarity - x.similarity);
      const limited = pairs.slice(0, 100);

      res.json({ pairs: limited, total: pairs.length });
    } catch (error) {
      next(error);
    }
  });

  // GET /api/admin/children/:id/history — camp history for a child (by representative registration id)
  app.get("/api/admin/children/:id/history", requireAuth, requireManager, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const { id } = req.params;

      // Look up the representative registration to get dedup key
      const [rep] = await db
        .select({
          childFullName: campRegistrations.childFullName,
          emergencyContactNumber: campRegistrations.emergencyContactNumber,
        })
        .from(campRegistrations)
        .where(and(eq(campRegistrations.id, id), eq(campRegistrations.tenantId, tenantId)));

      if (!rep) return res.status(404).json({ message: "Child not found" });

      const matchName = rep.childFullName.trim().toLowerCase();
      const matchPhone = rep.emergencyContactNumber.trim();

      // Find all registrations for this child
      const allRegs = await db
        .select({
          id: campRegistrations.id,
          eventId: campRegistrations.eventId,
          attendanceDays: campRegistrations.attendanceDays,
          createdAt: campRegistrations.createdAt,
          isOneTime: campRegistrations.isOneTime,
          addedByManager: campRegistrations.addedByManager,
        })
        .from(campRegistrations)
        .where(and(
          eq(campRegistrations.tenantId, tenantId),
          eq(campRegistrations.emergencyContactNumber, matchPhone),
          sql`lower(trim(${campRegistrations.childFullName})) = ${matchName}`,
        ))
        .orderBy(desc(campRegistrations.createdAt));

      // Get event details for each registration
      const eventIds = [...new Set(allRegs.map((r) => r.eventId))];
      let events: any[] = [];
      if (eventIds.length > 0) {
        events = await db
          .select({
            id: coreEventsTable.id,
            title: coreEventsTable.title,
            eventDate: coreEventsTable.eventDate,
            campEndDate: sql<string | null>`${coreEventsTable}.camp_end_date`,
            status: coreEventsTable.status,
            branchId: coreEventsTable.branchId,
          })
          .from(coreEventsTable)
          .where(and(
            eq(coreEventsTable.tenantId, tenantId),
            inArray(coreEventsTable.id, eventIds),
          ));
      }

      const eventMap = new Map(events.map((e) => [e.id, e]));
      const history = allRegs.map((reg) => ({
        ...reg,
        event: eventMap.get(reg.eventId) || null,
      }));

      res.json({ history });
    } catch (error) {
      next(error);
    }
  });

  // POST /api/admin/children/merge — merge two child profiles into one
  app.post("/api/admin/children/merge", requireAuth, requireManager, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const userId = (req.user as any)?.id;

      const bodySchema = z.object({
        primaryId: z.string().min(1),
        secondaryId: z.string().min(1),
      });
      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ message: "primaryId and secondaryId required" });

      const { primaryId, secondaryId } = parsed.data;
      if (primaryId === secondaryId) return res.status(400).json({ message: "Cannot merge a profile with itself" });

      // Load representative registrations for both
      const [primary] = await db
        .select({
          id: campRegistrations.id,
          childFullName: campRegistrations.childFullName,
          dateOfBirth: campRegistrations.dateOfBirth,
          primaryLanguage: campRegistrations.primaryLanguage,
          childPhotoUrl: campRegistrations.childPhotoUrl,
          allergies: campRegistrations.allergies,
          foodRestrictions: campRegistrations.foodRestrictions,
          behavioralNotes: campRegistrations.behavioralNotes,
          specialNotes: campRegistrations.specialNotes,
          authorizedPickupPersons: campRegistrations.authorizedPickupPersons,
          parentGuardianName: campRegistrations.parentGuardianName,
          emergencyContactNumber: campRegistrations.emergencyContactNumber,
        })
        .from(campRegistrations)
        .where(and(eq(campRegistrations.id, primaryId), eq(campRegistrations.tenantId, tenantId)));

      const [secondary] = await db
        .select({
          id: campRegistrations.id,
          childFullName: campRegistrations.childFullName,
          emergencyContactNumber: campRegistrations.emergencyContactNumber,
          parentGuardianName: campRegistrations.parentGuardianName,
          authorizedPickupPersons: campRegistrations.authorizedPickupPersons,
        })
        .from(campRegistrations)
        .where(and(eq(campRegistrations.id, secondaryId), eq(campRegistrations.tenantId, tenantId)));

      if (!primary) return res.status(404).json({ message: "Primary child not found" });
      if (!secondary) return res.status(404).json({ message: "Secondary child not found" });

      // Build merged authorizedPickupPersons — append secondary's parent contact if not already present
      const secondaryContact = `${secondary.parentGuardianName} (${secondary.emergencyContactNumber})`;
      const existing = (primary.authorizedPickupPersons || "").toLowerCase();
      const alreadyPresent =
        existing.includes(secondary.emergencyContactNumber.trim().toLowerCase()) ||
        existing.includes(secondary.parentGuardianName.trim().toLowerCase());

      const mergedPickup = alreadyPresent
        ? primary.authorizedPickupPersons
        : [primary.authorizedPickupPersons, secondaryContact].filter(Boolean).join("\n");

      // Update ALL secondary registrations to use primary's profile + merged pickup list
      const secName = secondary.childFullName.trim().toLowerCase();
      const secPhone = secondary.emergencyContactNumber.trim();

      const now = new Date();
      const { rowCount } = await db
        .update(campRegistrations)
        .set({
          childFullName: primary.childFullName,
          dateOfBirth: primary.dateOfBirth,
          primaryLanguage: primary.primaryLanguage,
          childPhotoUrl: primary.childPhotoUrl,
          allergies: primary.allergies,
          foodRestrictions: primary.foodRestrictions,
          behavioralNotes: primary.behavioralNotes,
          specialNotes: primary.specialNotes,
          authorizedPickupPersons: mergedPickup || null,
          parentGuardianName: primary.parentGuardianName,
          emergencyContactNumber: primary.emergencyContactNumber,
          updatedAt: now,
        })
        .where(and(
          eq(campRegistrations.tenantId, tenantId),
          eq(campRegistrations.emergencyContactNumber, secPhone),
          sql`lower(trim(${campRegistrations.childFullName})) = ${secName}`,
        ));

      // Also update primary's registrations with the merged pickup list (if it changed)
      if (!alreadyPresent) {
        const primName = primary.childFullName.trim().toLowerCase();
        const primPhone = primary.emergencyContactNumber.trim();
        await db
          .update(campRegistrations)
          .set({ authorizedPickupPersons: mergedPickup || null, updatedAt: now })
          .where(and(
            eq(campRegistrations.tenantId, tenantId),
            eq(campRegistrations.emergencyContactNumber, primPhone),
            sql`lower(trim(${campRegistrations.childFullName})) = ${primName}`,
          ));
      }

      const staffUser = req.user as any;
      const staffName = staffUser?.fullName || staffUser?.email || "Staff";
      await storage.createActivityLog({
        activityType: "camp_registration_updated",
        createdBy: userId || null,
        summaryText: `${staffName} merged child profile "${secondary.childFullName}" into "${primary.childFullName}" (${rowCount ?? 0} registration(s) updated)`,
      });

      res.json({ merged: rowCount ?? 0, primaryId, secondaryId });
    } catch (error) {
      next(error);
    }
  });

  // PATCH /api/admin/children/:id — update child profile globally (syncs all registrations)
  app.patch("/api/admin/children/:id", requireAuth, requireManager, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const { id } = req.params;
      const userId = (req.user as any)?.id;

      const profileSchema = z.object({
        childFullName: z.string().min(1).optional(),
        dateOfBirth: z.string().optional().nullable(),
        primaryLanguage: z.string().nullable().optional(),
        allergies: z.string().nullable().optional(),
        foodRestrictions: z.string().nullable().optional(),
        behavioralNotes: z.string().nullable().optional(),
        specialNotes: z.string().nullable().optional(),
        authorizedPickupPersons: z.string().nullable().optional(),
        parentGuardianName: z.string().min(1).optional(),
        emergencyContactNumber: z.string().min(1).optional(),
        parentContacts: z.array(z.object({ name: z.string(), phone: z.string() })).nullable().optional(),
        childPhotoUrl: z.string().nullable().optional(),
      });

      const parsed = profileSchema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ message: "Invalid fields", errors: parsed.error.flatten() });

      const fields = parsed.data;

      // Look up the representative registration
      const [rep] = await db
        .select({
          id: campRegistrations.id,
          childFullName: campRegistrations.childFullName,
          emergencyContactNumber: campRegistrations.emergencyContactNumber,
        })
        .from(campRegistrations)
        .where(and(eq(campRegistrations.id, id), eq(campRegistrations.tenantId, tenantId)));

      if (!rep) return res.status(404).json({ message: "Child not found" });

      const now = new Date();
      const updatePayload: Record<string, any> = { updatedAt: now };
      if (fields.childFullName !== undefined) updatePayload.childFullName = fields.childFullName.trim();
      if (fields.dateOfBirth !== undefined) updatePayload.dateOfBirth = fields.dateOfBirth || "";
      if (fields.primaryLanguage !== undefined) updatePayload.primaryLanguage = fields.primaryLanguage?.trim() || null;
      if (fields.allergies !== undefined) updatePayload.allergies = fields.allergies?.trim() || null;
      if (fields.foodRestrictions !== undefined) updatePayload.foodRestrictions = fields.foodRestrictions?.trim() || null;
      if (fields.behavioralNotes !== undefined) updatePayload.behavioralNotes = fields.behavioralNotes?.trim() || null;
      if (fields.specialNotes !== undefined) updatePayload.specialNotes = fields.specialNotes?.trim() || null;
      if (fields.authorizedPickupPersons !== undefined) updatePayload.authorizedPickupPersons = fields.authorizedPickupPersons?.trim() || null;
      if (fields.parentContacts !== undefined) {
        updatePayload.parentContacts = fields.parentContacts;
        // Keep legacy columns in sync with first contact
        if (fields.parentContacts && fields.parentContacts.length > 0) {
          updatePayload.parentGuardianName = fields.parentContacts[0].name.trim();
          updatePayload.emergencyContactNumber = fields.parentContacts[0].phone.trim();
        }
      } else {
        if (fields.parentGuardianName !== undefined) updatePayload.parentGuardianName = fields.parentGuardianName.trim();
        if (fields.emergencyContactNumber !== undefined) updatePayload.emergencyContactNumber = fields.emergencyContactNumber.trim();
      }
      if (fields.childPhotoUrl !== undefined) updatePayload.childPhotoUrl = fields.childPhotoUrl || null;

      // Update ALL registrations for this child (matched by pre-update name + phone)
      const matchName = rep.childFullName.trim().toLowerCase();
      const matchPhone = rep.emergencyContactNumber.trim();

      await db
        .update(campRegistrations)
        .set(updatePayload)
        .where(and(
          eq(campRegistrations.tenantId, tenantId),
          eq(campRegistrations.emergencyContactNumber, matchPhone),
          sql`lower(trim(${campRegistrations.childFullName})) = ${matchName}`,
        ));

      // Return the updated representative record
      const [updated] = await db
        .select()
        .from(campRegistrations)
        .where(and(eq(campRegistrations.id, id), eq(campRegistrations.tenantId, tenantId)));

      const staffUser = req.user as any;
      const staffName = staffUser?.fullName || staffUser?.email || "Staff";
      await storage.createActivityLog({
        activityType: "camp_registration_updated",
        createdBy: userId || null,
        summaryText: `${staffName} updated profile for ${updated?.childFullName || rep.childFullName} (global sync)`,
      });

      res.json(updated);
    } catch (error) {
      next(error);
    }
  });

  // Manager adds a child to a camp (add existing, create new, or one-time)
  app.post("/api/admin/events/:eventId/camp-registrations/manager", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { eventId } = req.params;
      const tenantId = await getDefaultTenantId();
      const userId = (req.user as any)?.id;
      const staffUser = req.user as any;
      const staffName = staffUser?.fullName || staffUser?.email || "Staff";

      const bodySchema = z.object({
        mode: z.enum(["existing", "new", "one_time"]),
        childFullName: z.string().min(1),
        dateOfBirth: z.string().optional().nullable(),
        primaryLanguage: z.string().optional().nullable(),
        childPhotoUrl: z.string().optional().nullable(),
        allergies: z.string().optional().nullable(),
        foodRestrictions: z.string().optional().nullable(),
        behavioralNotes: z.string().optional().nullable(),
        specialNotes: z.string().optional().nullable(),
        authorizedPickupPersons: z.string().optional().nullable(),
        parentGuardianName: z.string().optional().nullable(),
        emergencyContactNumber: z.string().optional().nullable(),
        attendanceDays: z.array(z.string()).default([]),
        approximateAge: z.string().optional().nullable(),
      });

      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ message: "Invalid fields", errors: parsed.error.flatten() });

      const data = parsed.data;
      const isOneTime = data.mode === "one_time";

      // Verify event exists
      const [ev] = await db
        .select({ id: coreEventsTable.id, tenantId: coreEventsTable.tenantId, eventDate: coreEventsTable.eventDate })
        .from(coreEventsTable)
        .where(and(eq(coreEventsTable.id, eventId), eq(coreEventsTable.tenantId, tenantId)));
      if (!ev) return res.status(404).json({ message: "Event not found" });

      const normalizedName = data.childFullName.trim().toLowerCase();
      const rawPhone = data.emergencyContactNumber?.trim() || "";
      // Only attempt dedup when a real phone is supplied.
      // An absent phone cannot reliably identify the same child, so we never
      // collapse multiple "no-phone" children together — each gets its own row.
      const canDedup = rawPhone.length > 0;

      // Duplicate check: same child + phone already in this camp (only when phone is known)
      const existing = canDedup
        ? await db
            .select({ id: campRegistrations.id, attendanceDays: campRegistrations.attendanceDays })
            .from(campRegistrations)
            .where(and(
              eq(campRegistrations.tenantId, tenantId),
              eq(campRegistrations.eventId, eventId),
              sql`lower(trim(${campRegistrations.childFullName})) = ${normalizedName}`,
              eq(campRegistrations.emergencyContactNumber, rawPhone),
            ))
            .limit(1)
        : [];

      if (existing.length > 0) {
        // Merge attendance days
        const current: string[] = Array.isArray(existing[0].attendanceDays) ? existing[0].attendanceDays : [];
        const toAdd = data.attendanceDays.filter((d) => !current.includes(d));
        if (toAdd.length > 0) {
          const merged = [...current, ...toAdd];
          await db
            .update(campRegistrations)
            .set({ attendanceDays: merged, updatedAt: new Date() })
            .where(eq(campRegistrations.id, existing[0].id));

          // Ensure attendance rows exist for new days
          for (const dateStr of toAdd) {
            await db.insert(campAttendance).values({
              campRegistrationId: existing[0].id,
              tenantId,
              eventId,
              attendanceDate: dateStr,
              status: "waiting",
            }).onConflictDoNothing();
          }
        }

        const [reg] = await db.select().from(campRegistrations).where(eq(campRegistrations.id, existing[0].id));
        return res.json({ registration: reg, merged: true });
      }

      // Create new registration (bypass signature requirement for manager adds)
      const today = new Date().toISOString().split("T")[0];
      const [registration] = await db.insert(campRegistrations).values({
        tenantId,
        eventId,
        childFullName: data.childFullName.trim(),
        dateOfBirth: data.dateOfBirth || (isOneTime ? "1900-01-01" : today),
        parentGuardianName: data.parentGuardianName?.trim() || "Manager Added",
        emergencyContactNumber: rawPhone || "MANAGER_ADDED",
        allergies: data.allergies?.trim() || null,
        foodRestrictions: data.foodRestrictions?.trim() || null,
        behavioralNotes: data.behavioralNotes?.trim() || null,
        specialNotes: isOneTime ? (data.approximateAge ? `Age: ${data.approximateAge}` : null) : (data.specialNotes?.trim() || null),
        authorizedPickupPersons: data.authorizedPickupPersons?.trim() || null,
        primaryLanguage: data.primaryLanguage?.trim() || null,
        childPhotoUrl: data.childPhotoUrl || null,
        attendanceDays: data.attendanceDays,
        agreedCampRules: true,
        agreedChildHealthy: true,
        agreedCampRulesDate: new Date(),
        parentSignature: "MANAGER_ADDED",
        signatureDate: today,
        isOneTime,
        addedByManager: true,
      }).returning();

      // Create attendance rows for each day
      for (const dateStr of data.attendanceDays) {
        await db.insert(campAttendance).values({
          campRegistrationId: registration.id,
          tenantId,
          eventId,
          attendanceDate: dateStr,
          status: "waiting",
        }).onConflictDoNothing();
      }

      await storage.createActivityLog({
        activityType: "camp_registration_created",
        createdBy: userId || null,
        summaryText: `${staffName} added ${registration.childFullName} to camp (${data.mode})`,
      });

      res.status(201).json({ registration, merged: false });
    } catch (error) {
      next(error);
    }
  });

  // Manager converts a one-time child registration to a full profile
  app.post("/api/admin/events/:eventId/camp-registrations/:regId/convert", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { eventId, regId } = req.params;
      const tenantId = await getDefaultTenantId();

      const bodySchema = z.object({
        childFullName: z.string().min(1).optional(),
        dateOfBirth: z.string().optional().nullable(),
        primaryLanguage: z.string().optional().nullable(),
        childPhotoUrl: z.string().optional().nullable(),
        allergies: z.string().optional().nullable(),
        foodRestrictions: z.string().optional().nullable(),
        behavioralNotes: z.string().optional().nullable(),
        specialNotes: z.string().optional().nullable(),
        authorizedPickupPersons: z.string().optional().nullable(),
        parentGuardianName: z.string().min(1),
        emergencyContactNumber: z.string().min(1),
      });

      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ message: "Invalid fields", errors: parsed.error.flatten() });
      const data = parsed.data;

      const [reg] = await db
        .select({ id: campRegistrations.id, tenantId: campRegistrations.tenantId, isOneTime: campRegistrations.isOneTime })
        .from(campRegistrations)
        .where(and(
          eq(campRegistrations.id, regId),
          eq(campRegistrations.eventId, eventId),
          eq(campRegistrations.tenantId, tenantId),
        ));

      if (!reg) return res.status(404).json({ message: "Registration not found" });

      const updatePayload: Record<string, any> = { isOneTime: false, updatedAt: new Date() };
      if (data.childFullName) updatePayload.childFullName = data.childFullName.trim();
      if (data.dateOfBirth !== undefined) updatePayload.dateOfBirth = data.dateOfBirth || undefined;
      if (data.primaryLanguage !== undefined) updatePayload.primaryLanguage = data.primaryLanguage?.trim() || null;
      if (data.childPhotoUrl !== undefined) updatePayload.childPhotoUrl = data.childPhotoUrl || null;
      if (data.allergies !== undefined) updatePayload.allergies = data.allergies?.trim() || null;
      if (data.foodRestrictions !== undefined) updatePayload.foodRestrictions = data.foodRestrictions?.trim() || null;
      if (data.behavioralNotes !== undefined) updatePayload.behavioralNotes = data.behavioralNotes?.trim() || null;
      if (data.specialNotes !== undefined) updatePayload.specialNotes = data.specialNotes?.trim() || null;
      if (data.authorizedPickupPersons !== undefined) updatePayload.authorizedPickupPersons = data.authorizedPickupPersons?.trim() || null;
      updatePayload.parentGuardianName = data.parentGuardianName.trim();
      updatePayload.emergencyContactNumber = data.emergencyContactNumber.trim();

      const [updated] = await db
        .update(campRegistrations)
        .set(updatePayload)
        .where(eq(campRegistrations.id, regId))
        .returning();

      res.json(updated);
    } catch (error) {
      next(error);
    }
  });

  // ============================================
  // CAMP CHECK-IN / CHECK-OUT
  // ============================================

  // Get today's camp registrations (children attending today's active camp)
  app.get("/api/core/camp-checkins/today", requireAuthOrKiosk, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      let { branchId } = req.query as { branchId?: string };
      if (req.kioskSession) {
        if (branchId && branchId !== req.kioskSession.branchId) {
          return res.status(403).json({ message: "Kiosk cannot access another branch" });
        }
        branchId = req.kioskSession.branchId;
      }
      // Use Bangkok timezone for date comparison (consistent with rest of app)
      const todayStr = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Bangkok' }).format(new Date());

      // Find active camps today
      const campConditions: any[] = [
        eq(coreEventsTable.tenantId, tenantId),
        eq(coreEventsTable.eventType, "camp"),
        lte(coreEventsTable.eventDate, todayStr),
      ];
      if (branchId) campConditions.push(eq(coreEventsTable.branchId, branchId));

      const activeCamps = await db
        .select()
        .from(coreEventsTable)
        .where(and(...campConditions));

      // Filter camps where campEndDate >= today, or campEndDate is null (open-ended / no end date set)
      const todayCamps = activeCamps.filter((c: any) => {
        const end = (c as any).campEndDate;
        return end === null || end === undefined || end >= todayStr;
      });

      if (todayCamps.length === 0) {
        return res.json({ camps: [], registrations: [] });
      }

      const campIds = todayCamps.map((c: any) => c.id);

      // Filter in SQL: include registration if attendance_days is empty array []
      // OR if today's date string is present in the attendance_days JSON array.
      // Uses PostgreSQL JSONB "?" operator to check array membership efficiently.
      const regs = await db
        .select()
        .from(campRegistrations)
        .where(and(
          eq(campRegistrations.tenantId, tenantId),
          inArray(campRegistrations.eventId, campIds),
          sql`(
            ${campRegistrations.attendanceDays} IS NULL
            OR jsonb_array_length(${campRegistrations.attendanceDays}) = 0
            OR ${campRegistrations.attendanceDays} ? ${todayStr}
          )`
        ))
        .orderBy(asc(campRegistrations.childFullName));

      if (regs.length === 0) {
        return res.json({ camps: todayCamps, registrations: [] });
      }

      // Seed today's attendance rows for every registration (upsert waiting if absent)
      await db
        .insert(campAttendance)
        .values(
          regs.map((r) => ({
            campRegistrationId: r.id,
            tenantId,
            eventId: r.eventId,
            attendanceDate: todayStr,
            status: "waiting" as const,
          }))
        )
        .onConflictDoNothing();

      // Fetch the daily attendance rows for today
      const regIds = regs.map((r) => r.id);
      const attendanceRows = await db
        .select()
        .from(campAttendance)
        .where(and(
          inArray(campAttendance.campRegistrationId, regIds),
          eq(campAttendance.attendanceDate, todayStr)
        ));

      // Build a lookup map
      const attendanceByRegId = new Map(
        attendanceRows.map((a) => [a.campRegistrationId, a])
      );

      // Merge daily attendance status into each registration
      const registrations = regs.map((r) => {
        const att = attendanceByRegId.get(r.id);
        return {
          ...r,
          attendanceStatus: att?.status ?? "waiting",
          attendanceCheckedInAt: att?.checkedInAt?.toISOString() ?? null,
          attendanceCheckedOutAt: att?.checkedOutAt?.toISOString() ?? null,
        };
      });

      res.json({ camps: todayCamps, registrations });
    } catch (error) {
      next(error);
    }
  });

  // Check in a camp child (writes to daily attendance row for today)
  app.post("/api/core/camp-checkins/:id/check-in", requireAuthOrKiosk, async (req, res, next) => {
    try {
      const { id } = req.params;
      const tenantId = await getDefaultTenantId();
      const userId = (req.user as any)?.id;
      const todayStr = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Bangkok' }).format(new Date());
      const { paymentMethod, dropOffPerson } = req.body ?? {};

      // Verify registration exists and get eventId
      const [reg] = await db
        .select({ id: campRegistrations.id, eventId: campRegistrations.eventId })
        .from(campRegistrations)
        .where(and(eq(campRegistrations.id, id), eq(campRegistrations.tenantId, tenantId)));
      if (!reg) return res.status(404).json({ message: "Registration not found" });

      const [updated] = await db
        .insert(campAttendance)
        .values({
          campRegistrationId: id,
          tenantId,
          eventId: reg.eventId,
          attendanceDate: todayStr,
          status: "checked_in",
          checkedInAt: new Date(),
          checkedInBy: userId || null,
          paymentMethod: paymentMethod || null,
          dropOffPerson: dropOffPerson || null,
        })
        .onConflictDoUpdate({
          target: [campAttendance.campRegistrationId, campAttendance.attendanceDate],
          set: {
            status: "checked_in",
            checkedInAt: new Date(),
            checkedInBy: userId || null,
            paymentMethod: paymentMethod || null,
            dropOffPerson: dropOffPerson || null,
            updatedAt: new Date(),
          },
        })
        .returning();

      res.json(updated);
    } catch (error) {
      next(error);
    }
  });

  // Check out a camp child (writes to daily attendance row for today)
