  // Create a new event status
  app.post("/api/admin/event-statuses", requireAuth, requireManager, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      
      // First, ensure default statuses exist
      const existingStatuses = await db
        .select()
        .from(eventStatuses)
        .where(eq(eventStatuses.tenantId, tenantId));
      
      if (existingStatuses.length === 0) {
        // Create default statuses first
        const defaults = [
          { tenantId, name: "Upcoming", value: "upcoming", color: "blue", sortOrder: 0, isDefault: true },
          { tenantId, name: "In Progress", value: "in_progress", color: "yellow", sortOrder: 1, isDefault: true },
          { tenantId, name: "Completed", value: "completed", color: "green", sortOrder: 2, isDefault: true },
          { tenantId, name: "Cancelled", value: "cancelled", color: "gray", sortOrder: 3, isDefault: true },
        ];
        await db.insert(eventStatuses).values(defaults);
      }
      
      // Get max sort order
      const allStatuses = await db
        .select()
        .from(eventStatuses)
        .where(eq(eventStatuses.tenantId, tenantId));
      const maxOrder = Math.max(...allStatuses.map(s => s.sortOrder), -1);
      
      // Auto-generate value from name (lowercase, spaces to underscores)
      const name = req.body.name || "";
      const value = name.toLowerCase().replace(/\s+/g, "_").replace(/[^a-z0-9_]/g, "");
      
      // Check for duplicate value
      const existingWithValue = allStatuses.find(s => s.value === value);
      if (existingWithValue) {
        return res.status(400).json({ message: `A status with value "${value}" already exists. Please choose a different name.` });
      }
      
      const parsed = insertEventStatusSchema.safeParse({
        ...req.body,
        tenantId,
        value,
        sortOrder: maxOrder + 1,
        isDefault: false,
      });
      
      if (!parsed.success) {
        return res.status(400).json({ message: "Invalid status data", errors: parsed.error.errors });
      }
      
      const [newStatus] = await db.insert(eventStatuses).values(parsed.data).returning();
      res.status(201).json(newStatus);
    } catch (error: any) {
      // Handle unique constraint violation
      if (error?.code === '23505' || error?.constraint?.includes('tenant_value')) {
        return res.status(409).json({ message: "A status with this name already exists. Please choose a different name." });
      }
      next(error);
    }
  });

