  // Update a studio event task
  app.patch("/api/studio-tasks/:taskId", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { taskId } = req.params;
      
      // Validate request body with Zod
      const updateSchema = z.object({
        completed: z.boolean().optional(),
        status: z.enum(["todo", "doing", "done"]).optional(),
        title: z.string().min(1).optional(),
        description: z.string().nullable().optional(),
        dueTime: z.string().nullable().optional(),
        departmentId: z.string().nullable().optional(),
        displayOrder: z.number().int().optional(),
      });
      
      const parsed = updateSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ message: "Invalid request body", errors: parsed.error.errors });
      }
      
      const { completed, status, title, description, dueTime, departmentId, displayOrder } = parsed.data;
      const updateData: Record<string, any> = {};
      
      // Only include fields that were actually provided
      if (completed !== undefined) updateData.completed = completed;
      if (status !== undefined) updateData.status = status;
      if (title !== undefined) updateData.title = title;
      if (description !== undefined) updateData.description = description;
      if (dueTime !== undefined) updateData.dueTime = dueTime;
      if (departmentId !== undefined) updateData.departmentId = departmentId;
      if (displayOrder !== undefined) updateData.displayOrder = displayOrder;
      
      // Synchronize completed flag with status
      if (status === "done" && completed === undefined) {
        updateData.completed = true;
      }
      if (status !== undefined && status !== "done" && completed === undefined) {
        updateData.completed = false;
      }
      if (completed === true && status === undefined) {
        updateData.status = "done";
      }
      if (completed === false && status === undefined) {
        updateData.status = "todo";
      }
      
      // Determine if task is being completed (status="done" or completed=true)
      const isBeingCompleted = updateData.completed === true || updateData.status === "done";
      // Determine if task is being un-completed
      const isBeingUncompleted = updateData.completed === false || 
        (updateData.status !== undefined && updateData.status !== "done");
      
      // If marking as completed, set completion metadata (server-side only)
      if (isBeingCompleted) {
        updateData.completedAt = new Date();
        updateData.completedByUserId = req.user?.id;
      }
      // If un-completing, clear completion metadata
      if (isBeingUncompleted && !isBeingCompleted) {
        updateData.completedAt = null;
        updateData.completedByUserId = null;
      }
      
      const task = await storage.updateStudioEventTask(taskId, updateData);
      res.json(task);
    } catch (error) {
      next(error);
    }
  });

