  // ============================================
  // SCHEDULED TASKS (Recurring Task Definitions)
  // ============================================

  // Get all scheduled tasks (recurring definitions + one-off tasks, but not generated instances)
  app.get("/api/studio/scheduled-tasks", requireAuth, requireManager, async (req, res, next) => {
    try {
      const tenantId = await resolveTenantId(req.user?.tenantId);
      
      // Show recurring definitions (isRecurringDefinition=true) 
      // OR one-off tasks (recurrence="once" and no parentTaskId - meaning not generated instances)
      const scheduledTasks = await db
        .select({
          task: tasks,
          branch: branches,
        })
        .from(tasks)
        .leftJoin(branches, eq(tasks.branchId, branches.id))
        .where(and(
          eq(tasks.tenantId, tenantId),
          or(
            eq(tasks.isRecurringDefinition, true),
            and(
              eq(tasks.recurrence, "once"),
              isNull(tasks.parentTaskId)
            )
          )
        ))
        .orderBy(desc(tasks.createdAt));
      
      // Fetch questions for all tasks
      const taskIds = scheduledTasks.map(row => row.task.id);
      const allQuestions = taskIds.length > 0 
        ? await db
            .select()
            .from(taskQuestions)
            .where(inArray(taskQuestions.taskId, taskIds))
            .orderBy(taskQuestions.sortOrder)
        : [];
      
      // Group questions by taskId
      const questionsByTaskId = allQuestions.reduce((acc, q) => {
        if (!acc[q.taskId]) acc[q.taskId] = [];
        acc[q.taskId].push({
          id: q.id,
          prompt: q.prompt,
          questionType: q.questionType,
          options: q.options,
          isRequired: q.isRequired,
        });
        return acc;
      }, {} as Record<string, any[]>);
      
      // Attach task_assignments rows so that isTaskMine() on the client can
      // correctly determine per-user visibility.  Without this, tasks assigned
      // via the new `assignments` API (which leaves the legacy assignedEmployeeId
      // fields null) appear as unassigned and are shown to every user.
      const assignmentRows = taskIds.length > 0
        ? await db.select().from(taskAssignments).where(inArray(taskAssignments.taskId, taskIds))
        : [];
      const assignmentsByTaskId: Record<string, { assignmentType: string; assignmentId: string }[]> = {};
      for (const a of assignmentRows) {
        if (!assignmentsByTaskId[a.taskId]) assignmentsByTaskId[a.taskId] = [];
        assignmentsByTaskId[a.taskId].push({ assignmentType: a.assignmentType, assignmentId: a.assignmentId });
      }

      res.json(scheduledTasks.map(row => ({
        id: row.task.id,
        title: row.task.title,
        description: row.task.description,
        branchId: row.task.branchId,
        branchName: row.branch?.name || null,
        recurrence: row.task.recurrence,
        weeklyDays: row.task.weeklyDays || [],
        monthlyDay: row.task.monthlyDay || null,
        preferredDueTime: row.task.preferredDueTime,
        startAt: row.task.startAt,
        dueAt: row.task.dueAt,
        scheduledMode: row.task.scheduledMode,
        requiresPhotoEvidence: row.task.requiresPhotoEvidence,
        requiresResponses: row.task.requiresResponses,
        isRecurringDefinition: row.task.isRecurringDefinition,
        status: row.task.status,
        createdAt: row.task.createdAt,
        assignedTo: row.task.assignedTo,
        assignedEmployeeId: row.task.assignedEmployeeId,
        assignedRoleId: row.task.assignedRoleId,
        assignedDepartmentId: row.task.assignedDepartmentId,
        questions: questionsByTaskId[row.task.id] || [],
        assignments: assignmentsByTaskId[row.task.id] || [],
      })));
    } catch (error) {
      next(error);
    }
  });

  // Create a new scheduled task
  app.post("/api/studio/scheduled-tasks", requireAuth, requireManager, async (req, res, next) => {
    try {
      const tenantId = await resolveTenantId(req.user?.tenantId);
      const userId = req.user?.id;
      
      const { 
        title, description, branchId, branchIds, recurrence, weeklyDays, monthlyDay, preferredDueTime, 
        requiresPhotoEvidence, requiresResponses, startDate, dueDate, questions,
        assignmentType, assignedTo, assignedAdvisorId, assignedRoleId, assignedDepartmentId, scheduledMode,
        assignments: assignmentsBody
      } = req.body;
      
      if (!title?.trim()) {
        return res.status(400).json({ message: "Title is required" });
      }

      // Handle branchIds array (new multi-select) or legacy branchId
      const selectedBranchIds: string[] = branchIds && branchIds.length > 0 ? branchIds : (branchId ? [branchId] : []);
      const effectiveBranchId = selectedBranchIds.length > 0 ? selectedBranchIds[0] : null;

      // For one-off tasks, create a task instance with dueAt and startAt
      const isOneOff = recurrence === "once";
      const isScheduledMode = Boolean(scheduledMode);
      let startAt: Date | null = null;
      let dueAt: Date | null = null;
      
      if (isOneOff && dueDate && preferredDueTime) {
        dueAt = new Date(`${dueDate}T${preferredDueTime}:00+07:00`);
      } else if (isOneOff && dueDate) {
        dueAt = new Date(`${dueDate}T18:00:00+07:00`);
      }
      
      if (isOneOff) {
        if (isScheduledMode && startDate) {
          startAt = new Date(`${startDate}T00:00:00+07:00`);
        } else if (dueAt) {
          startAt = new Date(dueAt);
          startAt.setHours(startAt.getHours() - 7);
          const startCopy = new Date(`${dueDate}T00:00:00+07:00`);
          startAt = startCopy;
        }
      }
      
      // Handle employee and advisor assignments
      // For employees, we store the employee ID directly in assignedEmployeeId
      // For advisors, we store the user ID in assignedTo
      let resolvedAssignedTo: string | null = null;
      let resolvedAssignedEmployeeId: string | null = null;
      
      if (assignmentType === "specific_employee" && assignedTo) {
        // Store employee ID directly - no need to resolve to user ID
        resolvedAssignedEmployeeId = assignedTo;
      } else if (assignmentType === "advisor" && assignedAdvisorId) {
        // assignedAdvisorId could be a person ID (new selection) or user ID
        // First check if it's already a valid user ID
        const [existingUser] = await db.select().from(users).where(eq(users.id, assignedAdvisorId)).limit(1);
        if (existingUser) {
          resolvedAssignedTo = assignedAdvisorId;
        } else {
          // Try to resolve as person ID via access policy
          const accessPolicy = await storage.getAccessPolicy(assignedAdvisorId);
          if (accessPolicy && accessPolicy.userId) {
            resolvedAssignedTo = accessPolicy.userId;
          }
        }
      }
      
      const [newTask] = await db
        .insert(tasks)
        .values({
          tenantId,
          branchId: effectiveBranchId,
          title: title.trim(),
          description: description?.trim() || null,
          recurrence: recurrence || "daily",
          weeklyDays: weeklyDays || [],
          monthlyDay: monthlyDay || null,
          preferredDueTime: preferredDueTime || null,
          startAt: startAt,
          dueAt: dueAt,
          scheduledMode: isScheduledMode,
          requiresPhotoEvidence: requiresPhotoEvidence || false,
          requiresResponses: requiresResponses || false,
          isRecurringDefinition: !isOneOff, // One-off tasks are NOT recurring definitions
          status: "pending",
          priority: "medium",
          createdBy: userId,
          assignedTo: resolvedAssignedTo,
          assignedEmployeeId: resolvedAssignedEmployeeId,
          assignedRoleId: assignmentType === "by_role" ? assignedRoleId : null,
          assignedDepartmentId: assignmentType === "by_department" ? assignedDepartmentId : null,
        })
        .returning();
      
      // Handle questions if provided
      if (questions && questions.length > 0) {
        const questionValues = questions.map((q: any, index: number) => ({
          tenantId,
          taskId: newTask.id,
          prompt: q.prompt,
          questionType: q.questionType || 'text',
          options: q.options || null,
          isRequired: q.isRequired ?? true,
          sortOrder: index,
        }));
        await db.insert(taskQuestions).values(questionValues);
      }

      // Handle multi-employee assignments
      if (assignmentType === "specific_employee" && Array.isArray(assignmentsBody) && assignmentsBody.length > 0) {
        for (const a of assignmentsBody) {
          await db.insert(taskAssignments).values({
            tenantId,
            taskId: newTask.id,
            assignmentType: a.assignmentType as any,
            assignmentId: a.assignmentId,
          });
        }
      }

      if (newTask.isRecurringDefinition) {
        const THAILAND_OFFSET_MS = 7 * 60 * 60 * 1000;
        await generateInstanceForDefinition(tenantId, newTask.id, new Date(Date.now() + THAILAND_OFFSET_MS));
      }
      
      res.status(201).json({
        id: newTask.id,
        title: newTask.title,
        description: newTask.description,
        branchId: newTask.branchId,
        branchIds: selectedBranchIds, // Return for display
        recurrence: newTask.recurrence,
        weeklyDays: newTask.weeklyDays,
        preferredDueTime: newTask.preferredDueTime,
        requiresPhotoEvidence: newTask.requiresPhotoEvidence,
        requiresResponses: newTask.requiresResponses,
        isRecurringDefinition: newTask.isRecurringDefinition,
        status: newTask.status,
        createdAt: newTask.createdAt,
      });
    } catch (error) {
      next(error);
    }
  });

  // Update a scheduled task
  app.patch("/api/studio/scheduled-tasks/:id", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { id } = req.params;
      const tenantId = await resolveTenantId(req.user?.tenantId);
      
      const { title, description, branchId, recurrence, weeklyDays, monthlyDay, preferredDueTime, requiresPhotoEvidence, requiresResponses } = req.body;
      
      const updates: any = { updatedAt: new Date() };
      if (title !== undefined) updates.title = title.trim();
      if (description !== undefined) updates.description = description?.trim() || null;
      if (branchId !== undefined) updates.branchId = branchId || null;
      if (recurrence !== undefined) updates.recurrence = recurrence;
      if (weeklyDays !== undefined) updates.weeklyDays = weeklyDays;
      if (monthlyDay !== undefined) updates.monthlyDay = monthlyDay || null;
      if (preferredDueTime !== undefined) updates.preferredDueTime = preferredDueTime || null;
      if (requiresPhotoEvidence !== undefined) updates.requiresPhotoEvidence = requiresPhotoEvidence;
      if (requiresResponses !== undefined) updates.requiresResponses = requiresResponses;
      
      // Handle startDate, dueDate, scheduledMode for one-off tasks and branchIds array
      const { startDate, dueDate, scheduledMode, branchIds, assignedTo, assignedAdvisorId, assignedRoleId, assignedDepartmentId, assignmentType } = req.body;
      
      // Handle scheduledMode
      if (scheduledMode !== undefined) {
        updates.scheduledMode = Boolean(scheduledMode);
      }
      
      // Handle dates for one-off tasks
      if (recurrence === "once") {
        const isScheduledMode = scheduledMode !== undefined ? Boolean(scheduledMode) : false;
        
        if (dueDate) {
          const dueTime = preferredDueTime || "18:00";
          updates.dueAt = new Date(`${dueDate}T${dueTime}:00+07:00`);
        }
        
        if (isScheduledMode && startDate) {
          updates.startAt = new Date(`${startDate}T00:00:00+07:00`);
        } else if (!isScheduledMode && dueDate) {
          updates.startAt = new Date(`${dueDate}T00:00:00+07:00`);
        }
      } else if (dueDate) {
        updates.dueAt = new Date(dueDate);
      }
      // Handle branchIds array - use first selected branch
      if (branchIds !== undefined && Array.isArray(branchIds)) {
        updates.branchId = branchIds.length > 0 ? branchIds[0] : null;
      }
      // Sync task_assignments from the assignments array sent by the client.
      // Clear legacy single-assignment fields — all assignment data lives in task_assignments.
      const { assignments: assignmentsBody } = req.body;
      if (assignmentsBody !== undefined) {
        updates.assignedTo = null;
        updates.assignedEmployeeId = null;
        updates.assignedRoleId = null;
        updates.assignedDepartmentId = null;
      }
      // Update isRecurringDefinition based on recurrence type
      if (recurrence !== undefined) {
        updates.isRecurringDefinition = recurrence !== "once";
      }
      
      const [updated] = await db
        .update(tasks)
        .set(updates)
        .where(and(
          eq(tasks.id, id),
          eq(tasks.tenantId, tenantId)
        ))
        .returning();
      
      if (!updated) {
        return res.status(404).json({ message: "Scheduled task not found" });
      }
      
      // Sync task_assignments
      if (assignmentsBody !== undefined) {
        await db.delete(taskAssignments).where(eq(taskAssignments.taskId, id));
        if (Array.isArray(assignmentsBody)) {
          for (const a of assignmentsBody) {
            await db.insert(taskAssignments).values({
              tenantId,
              taskId: id,
              assignmentType: a.assignmentType as any,
              assignmentId: a.assignmentId,
            });
          }
        }
      }

      // Sync future non-completed instances to match the updated definition.
      // "Future" = due_at is in the future or null, and status is not completed/cancelled.
      if (updated.isRecurringDefinition) {
        const now = new Date();
        const futureInstances = await db
          .select({ id: tasks.id, dueAt: tasks.dueAt })
          .from(tasks)
          .where(and(
            eq(tasks.tenantId, tenantId),
            eq(tasks.parentTaskId, id),
            or(isNull(tasks.dueAt), gte(tasks.dueAt, now)),
            sql`${tasks.status} NOT IN ('completed', 'cancelled')`,
          ));

        if (futureInstances.length > 0) {
          const instanceUpdates: any = {};
          if (title !== undefined) instanceUpdates.title = updated.title;
          if (description !== undefined) instanceUpdates.description = updated.description;
          if (branchIds !== undefined || branchId !== undefined) instanceUpdates.branchId = updated.branchId;
          if (requiresPhotoEvidence !== undefined) instanceUpdates.requiresPhotoEvidence = updated.requiresPhotoEvidence;
          if (requiresResponses !== undefined) instanceUpdates.requiresResponses = updated.requiresResponses;
          if (assignmentsBody !== undefined) {
            instanceUpdates.assignedTo = null;
            instanceUpdates.assignedEmployeeId = null;
            instanceUpdates.assignedRoleId = null;
            instanceUpdates.assignedDepartmentId = null;
          }

          for (const instance of futureInstances) {
            const instanceFieldUpdates = { ...instanceUpdates };
            // If preferredDueTime changed and the instance has a dueAt, update the time component.
            if (preferredDueTime !== undefined && instance.dueAt) {
              const dateStr = instance.dueAt.toISOString().split('T')[0];
              instanceFieldUpdates.dueAt = new Date(`${dateStr}T${preferredDueTime}:00+07:00`);
            }
            if (Object.keys(instanceFieldUpdates).length > 0) {
              await db.update(tasks).set(instanceFieldUpdates).where(eq(tasks.id, instance.id));
            }
            // Sync task_assignments
            if (assignmentsBody !== undefined) {
              await db.delete(taskAssignments).where(eq(taskAssignments.taskId, instance.id));
              if (Array.isArray(assignmentsBody)) {
                for (const a of assignmentsBody) {
                  await db.insert(taskAssignments).values({
                    tenantId,
                    taskId: instance.id,
                    assignmentType: a.assignmentType as any,
                    assignmentId: a.assignmentId,
                  });
                }
              }
            }
          }
        }
      }

      // Handle questions update - delete old ones and insert new ones
      const { questions } = req.body;
      if (questions !== undefined) {
        // Delete existing questions for this task
        await db.delete(taskQuestions).where(eq(taskQuestions.taskId, id));
        
        // Insert new questions if any
        if (questions && questions.length > 0) {
          const questionValues = questions.map((q: any, index: number) => ({
            tenantId,
            taskId: id,
            prompt: q.prompt,
            questionType: q.questionType || 'text',
            options: q.options || null,
            isRequired: q.isRequired ?? true,
            sortOrder: index,
          }));
          await db.insert(taskQuestions).values(questionValues);
        }
      }
      
      // Fetch updated questions
      const updatedQuestions = await db
        .select()
        .from(taskQuestions)
        .where(eq(taskQuestions.taskId, id))
        .orderBy(taskQuestions.sortOrder);
      
      res.json({
        id: updated.id,
        title: updated.title,
        description: updated.description,
        branchId: updated.branchId,
        recurrence: updated.recurrence,
        weeklyDays: updated.weeklyDays,
        preferredDueTime: updated.preferredDueTime,
        dueAt: updated.dueAt,
        requiresPhotoEvidence: updated.requiresPhotoEvidence,
        requiresResponses: updated.requiresResponses,
        isRecurringDefinition: updated.isRecurringDefinition,
        status: updated.status,
        createdAt: updated.createdAt,
        assignedTo: updated.assignedTo,
        assignedRoleId: updated.assignedRoleId,
        assignedDepartmentId: updated.assignedDepartmentId,
        questions: updatedQuestions.map(q => ({
          id: q.id,
          prompt: q.prompt,
          questionType: q.questionType,
          options: q.options,
          isRequired: q.isRequired,
        })),
      });
    } catch (error) {
      next(error);
    }
  });

  // Delete a scheduled task
  app.delete("/api/studio/scheduled-tasks/:id", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { id } = req.params;
      const tenantId = await resolveTenantId(req.user?.tenantId);
      
      // Delete questions first
      await db.delete(taskQuestions).where(eq(taskQuestions.taskId, id));
      
      const [deleted] = await db
        .delete(tasks)
        .where(and(
          eq(tasks.id, id),
          eq(tasks.tenantId, tenantId)
        ))
        .returning();
      
      if (!deleted) {
        return res.status(404).json({ message: "Scheduled task not found" });
      }
      
      res.status(204).send();
    } catch (error) {
      next(error);
    }
  });

