  // ============================================
  // CHECKLIST TEMPLATES
  // ============================================

  // Get all checklist templates
  app.get("/api/checklists/templates", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const requestedBranchId = req.query.branchId as string | undefined;
      
      // Enforce effective branch access, including policy-derived advisor access.
      let effectiveBranchId: string | null = null;
      
      if (user.hasAllBranchesAccess) {
        if (requestedBranchId === 'all' || !requestedBranchId) {
          effectiveBranchId = null;
        } else {
          effectiveBranchId = requestedBranchId;
        }
      } else {
        if (user.allowedBranchIds.length === 0) {
          return res.status(403).json({ message: "No branch access configured" });
        }
        
        if (requestedBranchId && requestedBranchId !== 'all') {
          if (!canUserAccessBranch(user, requestedBranchId)) {
            return res.status(403).json({ message: "Access denied to this branch" });
          }
          effectiveBranchId = requestedBranchId;
        } else {
          effectiveBranchId = user.allowedBranchIds[0];
        }
      }
      
      const templates = await storage.getChecklistTemplates(tenantId, effectiveBranchId);
      
      const tplEmployeeIds = [...new Set(templates.map((t: any) => t.assignedEmployeeId).filter(Boolean))] as string[];
      let tplEmployeeRoleMap = new Map<string, string>();
      let tplEmployeeDeptMap = new Map<string, string | null>();
      let tplEmployeeHrRoleIdsMap = new Map<string, string>();
      if (tplEmployeeIds.length > 0) {
        const empUserRows = await db.select({ employeeId: employees.id, role: users.role, primaryDepartmentId: employees.primaryDepartmentId })
          .from(employees)
          .leftJoin(users, eq(employees.userId, users.id))
          .where(inArray(employees.id, tplEmployeeIds as string[]));
        tplEmployeeRoleMap = new Map(empUserRows.filter(e => e.role).map(e => [e.employeeId, e.role!]));
        tplEmployeeDeptMap = new Map(empUserRows.map(e => [e.employeeId, e.primaryDepartmentId]));
        
        const hrRoleRows = await db.select({ employeeId: employeeRoles.employeeId, roleId: employeeRoles.roleId })
          .from(employeeRoles)
          .where(inArray(employeeRoles.employeeId, tplEmployeeIds as string[]));
        const grouped = new Map<string, string[]>();
        for (const row of hrRoleRows) {
          if (!grouped.has(row.employeeId)) grouped.set(row.employeeId, []);
          grouped.get(row.employeeId)!.push(row.roleId);
        }
        tplEmployeeHrRoleIdsMap = new Map([...grouped.entries()].map(([k, v]) => [k, v.join(',')]));
      }
      
      const enrichedTemplates = templates.map((t: any) => ({
        ...t,
        assignedUserRole: t.assignedEmployeeId ? tplEmployeeRoleMap.get(t.assignedEmployeeId) || null : null,
        assignedEmployeeDepartmentId: t.assignedEmployeeId ? tplEmployeeDeptMap.get(t.assignedEmployeeId) || null : null,
        assignedEmployeeRoleIds: t.assignedEmployeeId ? tplEmployeeHrRoleIdsMap.get(t.assignedEmployeeId) || null : null,
      }));
      
      res.json(enrichedTemplates);
    } catch (error) {
      next(error);
    }
  });

  // Get today's checklists for operational use
  app.get("/api/checklists/today", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const requestedBranchId = req.query.branchId as string | undefined;
      const myOnly = req.query.myOnly === 'true';
      
      // Enforce effective branch access, including policy-derived advisor access.
      let effectiveBranchId: string | null = null;
      
      if (user.hasAllBranchesAccess) {
        if (requestedBranchId === 'all' || !requestedBranchId) {
          effectiveBranchId = null;
        } else {
          effectiveBranchId = requestedBranchId;
        }
      } else {
        if (user.allowedBranchIds.length === 0) {
          return res.status(403).json({ message: "No branch access configured" });
        }
        
        if (requestedBranchId && requestedBranchId !== 'all') {
          if (!canUserAccessBranch(user, requestedBranchId)) {
            return res.status(403).json({ message: "Access denied to this branch" });
          }
          effectiveBranchId = requestedBranchId;
        } else {
          effectiveBranchId = user.allowedBranchIds[0];
        }
      }
      
      const templates = await storage.getChecklistTemplates(tenantId, effectiveBranchId);
      
      // Fetch assignment names for display
      const assignmentIds = {
        employeeIds: [...new Set(templates.map((t: any) => t.assignedEmployeeId).filter(Boolean))],
        roleIds: [...new Set(templates.map((t: any) => t.assignedRoleId).filter(Boolean))],
        deptIds: [...new Set(templates.map((t: any) => t.assignedDepartmentId).filter(Boolean))],
      };
      
      // Fetch names in parallel
      const [employeeNames, roleNames, deptNames] = await Promise.all([
        assignmentIds.employeeIds.length > 0 
          ? db.select({ id: employees.id, nickname: employees.nickname, fullName: employees.fullName, primaryDepartmentId: employees.primaryDepartmentId }).from(employees).where(inArray(employees.id, assignmentIds.employeeIds as string[]))
          : Promise.resolve([]),
        assignmentIds.roleIds.length > 0
          ? db.select({ id: roles.id, name: roles.name }).from(roles).where(inArray(roles.id, assignmentIds.roleIds as string[]))
          : Promise.resolve([]),
        assignmentIds.deptIds.length > 0
          ? db.select({ id: departments.id, name: departments.name }).from(departments).where(inArray(departments.id, assignmentIds.deptIds as string[]))
          : Promise.resolve([]),
      ]);
      
      const employeeNameMap = new Map(employeeNames.map((e: any) => [e.id, e.nickname || e.fullName]));
      const employeeDeptMap = new Map(employeeNames.map((e: any) => [e.id, e.primaryDepartmentId]));
      const roleNameMap = new Map(roleNames.map((r: any) => [r.id, r.name]));
      const deptNameMap = new Map(deptNames.map((d: any) => [d.id, d.name]));
      
      let employeeHrRoleIdsMap = new Map<string, string>();
      if (assignmentIds.employeeIds.length > 0) {
        const hrRoleRows = await db.select({ employeeId: employeeRoles.employeeId, roleId: employeeRoles.roleId })
          .from(employeeRoles)
          .where(inArray(employeeRoles.employeeId, assignmentIds.employeeIds as string[]));
        const grouped = new Map<string, string[]>();
        for (const row of hrRoleRows) {
          if (!grouped.has(row.employeeId)) grouped.set(row.employeeId, []);
          grouped.get(row.employeeId)!.push(row.roleId);
        }
        employeeHrRoleIdsMap = new Map([...grouped.entries()].map(([k, v]) => [k, v.join(',')]));
      }
      
      // Get today's date range for run lookups
      const todayStart = new Date();
      todayStart.setHours(0, 0, 0, 0);
      const todayEnd = new Date();
      todayEnd.setHours(23, 59, 59, 999);
      
      // Enrich templates with assignment names and today's run status
      const enrichedTemplates = await Promise.all(templates.map(async (template: any) => {
        // Check for today's runs
        const runs = await db.select()
          .from(checklistRuns)
          .where(and(
            eq(checklistRuns.templateId, template.id),
            gte(checklistRuns.createdAt, todayStart),
            lte(checklistRuns.createdAt, todayEnd)
          ))
          .orderBy(desc(checklistRuns.createdAt))
          .limit(1);
        
        let computedStatus: string = 'not_started';
        let todayRun = null;
        if (runs.length > 0) {
          todayRun = runs[0];
          if (todayRun.status === 'completed') {
            computedStatus = 'completed';
          } else {
            computedStatus = 'in_progress';
          }
        }
        
        return {
          ...template,
          assignedEmployeeName: template.assignedEmployeeId ? employeeNameMap.get(template.assignedEmployeeId) || null : null,
          assignedRoleName: template.assignedRoleId ? roleNameMap.get(template.assignedRoleId) || null : null,
          assignedDepartmentName: template.assignedDepartmentId ? deptNameMap.get(template.assignedDepartmentId) || null : null,
          assignedEmployeeDepartmentId: template.assignedEmployeeId ? employeeDeptMap.get(template.assignedEmployeeId) || null : null,
          assignedEmployeeRoleIds: template.assignedEmployeeId ? employeeHrRoleIdsMap.get(template.assignedEmployeeId) || null : null,
          computedStatus,
          todayRun,
        };
      }));
      
      // Filter checklists by assignment
      const isAdminOrManager = ['admin', 'global_admin', 'operator_admin', 'manager'].includes(user.role);
      
      // For staff users, filter out CHECKER type checklists (manager-only visibility)
      const finalTemplates = isAdminOrManager 
        ? enrichedTemplates 
        : enrichedTemplates.filter((t: any) => t.checklistType !== 'checker');
      
      // Always enforce personal-workspace filter for all users in Today view
      const linkedEmployee = await storage.getEmployeeByUserId(user.id);
      const employeeId = linkedEmployee?.id || null;
      const employeeDepartmentId = linkedEmployee?.primaryDepartmentId || (linkedEmployee as any)?.departmentId || null;
      
      let employeeRoleIds: string[] = [];
      if (employeeId) {
        const roleResult = await db.select({ roleId: employeeRoles.roleId })
          .from(employeeRoles)
          .where(eq(employeeRoles.employeeId, employeeId));
        employeeRoleIds = roleResult.map(r => r.roleId);
      }
      
      const filteredTemplates = finalTemplates.filter((template: any) => {
        const hasDirectEmployee = !!template.assignedEmployeeId;
        const hasRole = !!template.assignedRoleId;
        const hasDept = !!template.assignedDepartmentId;

        // (a) Directly assigned to this employee
        if (hasDirectEmployee && template.assignedEmployeeId === employeeId) return true;

        // (b) No assignment fields set at all — visible only when template.departmentId
        //     matches the actor's primary department (completely unassigned = hidden)
        if (!hasDirectEmployee && !hasRole && !hasDept) {
          return !!(employeeDepartmentId && template.departmentId === employeeDepartmentId);
        }

        // (c) Department assignment matches actor's dept and no direct employee assignment
        if (hasDept && !hasDirectEmployee && template.assignedDepartmentId === employeeDepartmentId) return true;

        // Role assignment matches actor's roles, only when no direct employee assignment exists
        if (hasRole && !hasDirectEmployee && employeeRoleIds.includes(template.assignedRoleId)) return true;

        return false;
      });
      
      res.json(filteredTemplates);
    } catch (error) {
      next(error);
    }
  });

  // Get checklists by date range
  app.get("/api/checklists/by-date", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const requestedBranchId = req.query.branchId as string | undefined;
      const fromDate = req.query.from as string | undefined;
      const toDate = req.query.to as string | undefined;
      
      // Validate date parameters
      if (!fromDate || !toDate) {
        return res.status(400).json({ message: "Missing 'from' and 'to' date parameters" });
      }
      
      // Enforce effective branch access, including policy-derived advisor access.
      let effectiveBranchId: string | null = null;
      
      if (user.hasAllBranchesAccess) {
        if (requestedBranchId === 'all' || !requestedBranchId) {
          effectiveBranchId = null;
        } else {
          effectiveBranchId = requestedBranchId;
        }
      } else {
        if (user.allowedBranchIds.length === 0) {
          return res.status(403).json({ message: "No branch access configured" });
        }
        
        if (requestedBranchId && requestedBranchId !== 'all') {
          if (!canUserAccessBranch(user, requestedBranchId)) {
            return res.status(403).json({ message: "Access denied to this branch" });
          }
          effectiveBranchId = requestedBranchId;
        } else {
          effectiveBranchId = user.allowedBranchIds[0];
        }
      }
      
      const templates = await storage.getChecklistTemplates(tenantId, effectiveBranchId);
      
      // Parse dates
      const queryFromDate = new Date(fromDate);
      const queryToDate = new Date(toDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      
      // Filter templates by recurrence matching the date range and creation date
      const filteredByDate = templates.filter((template: any) => {
        // Convert createdAt to Bangkok date string (YYYY-MM-DD)
        const templateCreatedAt = new Date(template.createdAt);
        const templateCreatedDateBangkok = new Intl.DateTimeFormat('sv-SE', { 
          timeZone: 'Asia/Bangkok' 
        }).format(templateCreatedAt);
        
        // Query dates are already in YYYY-MM-DD format from frontend
        // Don't show checklists for dates before they were created (compare as strings)
        if (templateCreatedDateBangkok > toDate) {
          return false;
        }
        
        // Check if template is scheduled for any day in the range
        const recurrence = template.recurrence || 'daily';
        const weeklyDays = template.weeklyDays || [];
        
        // For daily templates, include if created on or before the query date
        if (recurrence === 'daily') {
          return true;
        }
        
        // For weekly templates, check if any day in the range matches
        if (recurrence === 'weekly' && weeklyDays.length > 0) {
          const dayNames = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
          let currentDate = new Date(queryFromDate);
          while (currentDate <= queryToDate) {
            const dayOfWeek = dayNames[currentDate.getDay()];
            if (weeklyDays.includes(dayOfWeek)) {
              return true;
            }
            currentDate.setDate(currentDate.getDate() + 1);
          }
          return false;
        }
        
        // For monthly templates, check if the monthlyDay falls within the range
        if (recurrence === 'monthly') {
          const monthlyDay = template.monthlyDay;
          if (monthlyDay) {
            let currentDate = new Date(queryFromDate);
            while (currentDate <= queryToDate) {
              const dayOfMonth = currentDate.getDate();
              const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
              if (dayOfMonth === monthlyDay || (monthlyDay > daysInMonth && dayOfMonth === daysInMonth)) {
                return true;
              }
              currentDate.setDate(currentDate.getDate() + 1);
            }
            return false;
          }
          return true;
        }
        
        return true;
      });
      
      // Fetch assignment names for display
      const assignmentIds = {
        employeeIds: [...new Set(filteredByDate.map((t: any) => t.assignedEmployeeId).filter(Boolean))],
        roleIds: [...new Set(filteredByDate.map((t: any) => t.assignedRoleId).filter(Boolean))],
        deptIds: [...new Set(filteredByDate.map((t: any) => t.assignedDepartmentId).filter(Boolean))],
        locationIds: [...new Set(filteredByDate.map((t: any) => t.locationId).filter(Boolean))],
      };
      
      // Fetch names in parallel
      const [employeeNames, roleNames, deptNames, locationNames] = await Promise.all([
        assignmentIds.employeeIds.length > 0 
          ? db.select({ id: employees.id, nickname: employees.nickname, fullName: employees.fullName }).from(employees).where(inArray(employees.id, assignmentIds.employeeIds as string[]))
          : Promise.resolve([]),
        assignmentIds.roleIds.length > 0
          ? db.select({ id: roles.id, name: roles.name }).from(roles).where(inArray(roles.id, assignmentIds.roleIds as string[]))
          : Promise.resolve([]),
        assignmentIds.deptIds.length > 0
          ? db.select({ id: departments.id, name: departments.name }).from(departments).where(inArray(departments.id, assignmentIds.deptIds as string[]))
          : Promise.resolve([]),
        assignmentIds.locationIds.length > 0
          ? db.select({ id: locations.id, name: locations.name }).from(locations).where(inArray(locations.id, assignmentIds.locationIds as string[]))
          : Promise.resolve([]),
      ]);
      
      const employeeNameMap = new Map(employeeNames.map((e: any) => [e.id, e.nickname || e.fullName]));
      const roleNameMap = new Map(roleNames.map((r: any) => [r.id, r.name]));
      const deptNameMap = new Map(deptNames.map((d: any) => [d.id, d.name]));
      const locationNameMap = new Map(locationNames.map((l: any) => [l.id, l.name]));
      
      // Enrich templates with assignment names and computed status
      const enrichedTemplates = await Promise.all(filteredByDate.map(async (template: any) => {
        // Check for existing runs to determine status
        const runs = await db.select()
          .from(checklistRuns)
          .where(and(
            eq(checklistRuns.templateId, template.id),
            gte(checklistRuns.createdAt, queryFromDate),
            lte(checklistRuns.createdAt, new Date(queryToDate.getTime() + 24 * 60 * 60 * 1000))
          ))
          .orderBy(desc(checklistRuns.createdAt))
          .limit(1);
        
        let computedStatus = 'not_started';
        let latestRunId: string | null = null;
        if (runs.length > 0) {
          const latestRun = runs[0];
          latestRunId = latestRun.id;
          if (latestRun.status === 'completed') {
            computedStatus = 'completed';
          } else {
            computedStatus = 'in_progress';
          }
        }
        
        return {
          ...template,
          assignedEmployeeName: template.assignedEmployeeId ? employeeNameMap.get(template.assignedEmployeeId) || null : null,
          assignedRoleName: template.assignedRoleId ? roleNameMap.get(template.assignedRoleId) || null : null,
          assignedDepartmentName: template.assignedDepartmentId ? deptNameMap.get(template.assignedDepartmentId) || null : null,
          locationName: template.locationId ? locationNameMap.get(template.locationId) || null : null,
          computedStatus,
          latestRunId,
        };
      }));
      
      res.json(enrichedTemplates);
    } catch (error) {
      next(error);
    }
  });

  // Create checklist template (admin/manager only)
  app.post("/api/checklists/templates", requireAuth, requireManager, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const { 
        name, description, branchId, branchIds, departmentId, recurrence, scheduledTime, 
        items, assignedEmployeeId, assignedRoleId, assignedDepartmentId,
        locationId, requiresPhotoEvidence, referenceMediaUrls, weeklyDays, monthlyDay,
        // Checker-specific fields
        checklistType, checkerRounds, scheduleTime1, scheduleTime2, scheduleTime3, scheduleTime4, scheduleTime5, allowedCheckerRoles
      } = req.body;
      
      if (!name) {
        return res.status(400).json({ message: "Name is required" });
      }
      
      // Handle branchIds array (new multi-select) or legacy branchId
      const selectedBranchIds: string[] = branchIds && branchIds.length > 0 ? branchIds : (branchId ? [branchId] : []);
      
      // Validate branch access for non-admins
      let effectiveBranchId: string | null = selectedBranchIds.length > 0 ? selectedBranchIds[0] : null;
      if (!user.hasAllBranchesAccess) {
        // Non-admins cannot create global (null branchId) templates
        if (!effectiveBranchId) {
          // Default to user's first accessible branch
          if (user.allowedBranchIds.length === 0) {
            return res.status(403).json({ message: "No branch access configured" });
          }
          effectiveBranchId = user.allowedBranchIds[0];
        } else {
          // Verify access to all specified branches
          for (const bid of selectedBranchIds) {
            if (!canUserAccessBranch(user, bid)) {
              return res.status(403).json({ message: "Access denied to create templates for one or more branches" });
            }
          }
        }
      }
      
      const isChecker = checklistType === 'checker';
      const itemWithInvalidEvidenceFlags = Array.isArray(items)
        ? items.find((item: any) =>
            (item.requiresPhoto !== undefined && typeof item.requiresPhoto !== "boolean")
            || (item.cameraEnabled !== undefined && typeof item.cameraEnabled !== "boolean")
            || (item.galleryEnabled !== undefined && typeof item.galleryEnabled !== "boolean")
          )
        : null;
      if (itemWithInvalidEvidenceFlags) {
        return res.status(400).json({ message: "Checklist item photo settings must be true or false" });
      }
      const sanitizedItems = Array.isArray(items)
        ? items.map((item: any) => {
            const galleryEnabled = item.galleryEnabled ?? false;
            const configuredCameraEnabled = item.cameraEnabled ?? true;
            return {
              ...item,
              requiresPhoto: item.requiresPhoto === true || requiresPhotoEvidence === true,
              cameraEnabled: requiresPhotoEvidence === true
                && configuredCameraEnabled === false
                && galleryEnabled === false
                ? true
                : configuredCameraEnabled,
              galleryEnabled,
              linkedToFix: isChecker ? false : item.linkedToFix === true,
            };
          })
        : [];

      const invalidPhotoItem = sanitizedItems.find((item: any) =>
        item.requiresPhoto === true && item.cameraEnabled === false
        && item.galleryEnabled === false
      );
      if (invalidPhotoItem) {
        return res.status(400).json({ message: `"${invalidPhotoItem.title || "Checklist item"}" requires a photo, so enable Camera or Gallery` });
      }
      
      // Multi-branch support: Create a template for each selected branch
      // For non-admins, ensure at least one branch is used (no global templates)
      const branchesToCreate = selectedBranchIds.length > 0 
        ? selectedBranchIds 
        : (effectiveBranchId ? [effectiveBranchId] : [null]);
      const createdTemplates: any[] = [];
      
      for (const branchIdToUse of branchesToCreate) {
        const template = await storage.createChecklistTemplate({
          tenantId,
          name,
          description: description || null,
          branchId: branchIdToUse,
          departmentId: departmentId || null,
          checklistType: checklistType || 'operational',
          recurrence: recurrence || 'once',
          scheduledTime: scheduledTime || null,
          checkerRounds: checkerRounds || null,
          scheduleTime1: scheduleTime1 || null,
          scheduleTime2: scheduleTime2 || null,
          scheduleTime3: scheduleTime3 || null,
          scheduleTime4: scheduleTime4 || null,
          scheduleTime5: scheduleTime5 || null,
          assignedEmployeeId: assignedEmployeeId || null,
          assignedRoleId: assignedRoleId || null,
          assignedDepartmentId: assignedDepartmentId || null,
          allowedCheckerRoles: allowedCheckerRoles || [],
          locationId: locationId || null,
          referenceMediaUrls: referenceMediaUrls || [],
          weeklyDays: weeklyDays || [],
          monthlyDay: monthlyDay || null,
          createdBy: req.user!.id,
        }, sanitizedItems);
        createdTemplates.push(template);
      }
      
      // Return first template with all branchIds for display (backwards compatible)
      const firstTemplate = createdTemplates[0];
      res.status(201).json({ 
        ...firstTemplate, 
        branchIds: selectedBranchIds,
        createdCount: createdTemplates.length,
        message: createdTemplates.length > 1 
          ? `Created ${createdTemplates.length} templates (one per branch)` 
          : undefined
      });
    } catch (error) {
      next(error);
    }
  });

  // Get single checklist template with items
  app.get("/api/checklists/templates/:id", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const { id } = req.params;
      const template = await storage.getChecklistTemplateWithItems(id, tenantId);
      if (!template) {
        return res.status(404).json({ message: "Checklist template not found" });
      }
      
      // Verify branch access
      if (template.branchId && !canUserAccessBranch(user, template.branchId)) {
        return res.status(403).json({ message: "Access denied to this checklist" });
      }
      
      res.json(template);
    } catch (error) {
      next(error);
    }
  });

  // Update a checklist template
  app.patch("/api/checklists/templates/:id", requireAuth, requireManager, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const { id } = req.params;
      
      // Check if template exists and user has access
      const existingTemplate = await storage.getChecklistTemplateWithItems(id, tenantId);
      if (!existingTemplate) {
        return res.status(404).json({ message: "Checklist template not found" });
      }
      
      // Verify branch access
      if (existingTemplate.branchId && !canUserAccessBranch(user, existingTemplate.branchId)) {
        return res.status(403).json({ message: "Access denied to this checklist" });
      }
      
      const { name, description, branchId, branchIds, recurrence, scheduledTime, items, 
              assignedEmployeeId, assignedRoleId, assignedDepartmentId, locationId,
              requiresPhotoEvidence, referenceMediaUrls, isActive, weeklyDays, monthlyDay,
              // Checker-specific fields
              checklistType, checkerRounds, scheduleTime1, scheduleTime2, scheduleTime3, scheduleTime4, scheduleTime5, allowedCheckerRoles } = req.body;

      const itemWithInvalidEvidenceFlags = Array.isArray(items)
        ? items.find((item: any) =>
            (item.requiresPhoto !== undefined && typeof item.requiresPhoto !== "boolean")
            || (item.cameraEnabled !== undefined && typeof item.cameraEnabled !== "boolean")
            || (item.galleryEnabled !== undefined && typeof item.galleryEnabled !== "boolean")
          )
        : null;
      if (itemWithInvalidEvidenceFlags) {
        return res.status(400).json({ message: "Checklist item photo settings must be true or false" });
      }
      const itemsToNormalize = Array.isArray(items)
        ? items
        : requiresPhotoEvidence === true || existingTemplate.requiresPhotoEvidence
          ? existingTemplate.items
          : null;
      const shouldApplyLegacyPhotoRequirement = requiresPhotoEvidence === true
        || (!Array.isArray(items) && existingTemplate.requiresPhotoEvidence);
      const normalizedItems = itemsToNormalize
        ? itemsToNormalize.map((item: any) => {
            const galleryEnabled = item.galleryEnabled ?? false;
            const configuredCameraEnabled = item.cameraEnabled ?? true;
            return {
              ...item,
              requiresPhoto: item.requiresPhoto === true || shouldApplyLegacyPhotoRequirement,
              cameraEnabled: shouldApplyLegacyPhotoRequirement
                && configuredCameraEnabled === false
                && galleryEnabled === false
                ? true
                : configuredCameraEnabled,
              galleryEnabled,
            };
          })
        : null;
      const effectiveItems = normalizedItems ?? [];
      const invalidPhotoItem = effectiveItems.find((item: any) =>
        item.requiresPhoto === true && (item.cameraEnabled ?? true) === false
        && (item.galleryEnabled ?? false) === false
      );
      if (invalidPhotoItem) {
        return res.status(400).json({ message: `"${invalidPhotoItem.title || "Checklist item"}" requires a photo, so enable Camera or Gallery` });
      }
      
      // Update the template
      const updateData: any = { updatedAt: new Date() };
      if (name !== undefined) updateData.name = name;
      if (description !== undefined) updateData.description = description;
      if (branchId !== undefined) updateData.branchId = branchId;
      if (branchIds !== undefined) updateData.branchIds = branchIds;
      if (recurrence !== undefined) updateData.recurrence = recurrence;
      if (scheduledTime !== undefined) updateData.scheduledTime = scheduledTime;
      if (assignedEmployeeId !== undefined) updateData.assignedEmployeeId = assignedEmployeeId;
      if (assignedRoleId !== undefined) updateData.assignedRoleId = assignedRoleId;
      if (assignedDepartmentId !== undefined) updateData.assignedDepartmentId = assignedDepartmentId;
      if (locationId !== undefined) updateData.locationId = locationId;
      updateData.requiresPhotoEvidence = false;
      if (referenceMediaUrls !== undefined) updateData.referenceMediaUrls = referenceMediaUrls;
      if (isActive !== undefined) updateData.isActive = isActive;
      if (weeklyDays !== undefined) updateData.weeklyDays = weeklyDays;
      if (monthlyDay !== undefined) updateData.monthlyDay = monthlyDay;
      // Checker-specific fields
      if (checklistType !== undefined) updateData.checklistType = checklistType;
      if (checkerRounds !== undefined) updateData.checkerRounds = checkerRounds;
      if (scheduleTime1 !== undefined) updateData.scheduleTime1 = scheduleTime1;
      if (scheduleTime2 !== undefined) updateData.scheduleTime2 = scheduleTime2;
      if (scheduleTime3 !== undefined) updateData.scheduleTime3 = scheduleTime3;
      if (scheduleTime4 !== undefined) updateData.scheduleTime4 = scheduleTime4;
      if (scheduleTime5 !== undefined) updateData.scheduleTime5 = scheduleTime5;
      if (allowedCheckerRoles !== undefined) updateData.allowedCheckerRoles = allowedCheckerRoles;
      
      const newVersion = (existingTemplate.templateVersion || 1) + 1;
      updateData.templateVersion = newVersion;
      
      await db.update(checklistTemplates)
        .set(updateData)
        .where(eq(checklistTemplates.id, id));
      
      const newTemplateItemIds: string[] = [];
      
      if (normalizedItems) {
        const effectiveChecklistType = checklistType || existingTemplate.checklistType || "operational";
        const isCheckerTemplate = effectiveChecklistType === "checker";
        const now = new Date();
        const existingItemIds: string[] = existingTemplate.items?.map((i: any) => i.id) || [];
        const incomingItemIds = normalizedItems.filter((item: any) => item.id).map((item: any) => item.id);
        
        const itemsToDelete = existingItemIds.filter((eid: string) => !incomingItemIds.includes(eid));
        for (const itemId of itemsToDelete) {
          const referencedRuns = await db
            .select({ count: sql`count(*)` })
            .from(checklistRunItems)
            .where(eq(checklistRunItems.templateItemId, itemId));
          
          const refCount = Number(referencedRuns[0]?.count || 0);
          if (refCount === 0) {
            await db.delete(checklistTemplateItems).where(eq(checklistTemplateItems.id, itemId));
          }
        }
        
        for (let index = 0; index < normalizedItems.length; index++) {
          const item = normalizedItems[index];
          if (item.id && existingItemIds.includes(item.id)) {
            await db.update(checklistTemplateItems)
              .set({
                title: item.title,
                description: item.description || null,
                referenceMediaUrls: item.referenceMediaUrls || [],
                requiresNote: item.requiresNote === true,
                requiresPhoto: item.requiresPhoto === true,
                cameraEnabled: item.cameraEnabled,
                galleryEnabled: item.galleryEnabled,
                isCritical: item.isCritical === true,
                linkedToFix: isCheckerTemplate ? false : item.linkedToFix === true,
                departmentId: item.departmentId || null,
                zoneLabel: item.zoneLabel || null,
                sortOrder: index,
              })
              .where(eq(checklistTemplateItems.id, item.id));
            newTemplateItemIds.push(item.id);
          } else {
            const newItemId = crypto.randomUUID();
            await db.insert(checklistTemplateItems).values({
              id: newItemId,
              tenantId,
              templateId: id,
              title: item.title,
              description: item.description || null,
              referenceMediaUrls: item.referenceMediaUrls || [],
              requiresNote: item.requiresNote === true,
              requiresPhoto: item.requiresPhoto === true,
              cameraEnabled: item.cameraEnabled,
              galleryEnabled: item.galleryEnabled,
              isCritical: item.isCritical === true,
              linkedToFix: isCheckerTemplate ? false : item.linkedToFix === true,
              departmentId: item.departmentId || null,
              zoneLabel: item.zoneLabel || null,
              sortOrder: index,
              createdAt: now,
            });
            newTemplateItemIds.push(newItemId);
          }
        }
      }
      
      // Propagate changes to all non-completed runs
      // Rules:
      // - Completed runs are never touched (they're historical records)
      // - Pending/in_progress runs get fully synced to match the new template
      // - Run items that are already completed (checked off) within an incomplete run are preserved
      // - Run items for deleted template items that are NOT completed get removed
      // - New template items get added as uncompleted run items
      const incompleteRuns = await db.select()
        .from(checklistRuns)
        .where(and(
          eq(checklistRuns.templateId, id),
          inArray(checklistRuns.status, ['pending', 'in_progress'])
        ));
      
      let propagatedCount = 0;
      
      // If items were not sent in the update, fetch current template items for propagation
      let finalTemplateItemIds = newTemplateItemIds;
      if (finalTemplateItemIds.length === 0 && (!items || !Array.isArray(items))) {
        const currentItems = await db.select({ id: checklistTemplateItems.id })
          .from(checklistTemplateItems)
          .where(eq(checklistTemplateItems.templateId, id));
        finalTemplateItemIds = currentItems.map(i => i.id);
      }
      
      // The set of template item IDs that should exist in runs now
      const currentTemplateItemIdSet = new Set(finalTemplateItemIds);
      
      for (const run of incompleteRuns) {
        const runItems = await db.select()
          .from(checklistRunItems)
          .where(eq(checklistRunItems.runId, run.id));
        
        const existingTemplateItemIds = new Set(runItems.map(ri => ri.templateItemId));
        
        // 1. Remove run items whose template items no longer exist (only if not completed)
        for (const runItem of runItems) {
          if (!currentTemplateItemIdSet.has(runItem.templateItemId)) {
            if (!runItem.isCompleted) {
              await db.delete(checklistRunItems)
                .where(eq(checklistRunItems.id, runItem.id));
            }
          }
        }
        
        // 2. Add new template items that don't exist in the run yet
        for (const templateItemId of newTemplateItemIds) {
          if (!existingTemplateItemIds.has(templateItemId)) {
            await db.insert(checklistRunItems).values({
              id: crypto.randomUUID(),
              tenantId,
              runId: run.id,
              templateItemId: templateItemId,
              isCompleted: false,
              createdAt: new Date(),
            });
          }
        }
        
        // 3. Update the run's version marker
        await db.update(checklistRuns)
          .set({ 
            templateVersionApplied: newVersion,
            updatedAt: new Date(),
          })
          .where(eq(checklistRuns.id, run.id));
        
        propagatedCount++;
      }
      
      const updatedTemplate = await storage.getChecklistTemplateWithItems(id, tenantId);
      res.json({ ...updatedTemplate, propagatedRunCount: propagatedCount });
    } catch (error) {
      next(error);
    }
  });

  // Delete a checklist template
  app.delete("/api/checklists/templates/:id", requireAuth, requireManager, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const { id } = req.params;
      
      // Check if template exists and user has access
      const existingTemplate = await storage.getChecklistTemplateWithItems(id, tenantId);
      if (!existingTemplate) {
        return res.status(404).json({ message: "Checklist template not found" });
      }
      
      // Verify branch access
      if (existingTemplate.branchId && !canUserAccessBranch(user, existingTemplate.branchId)) {
        return res.status(403).json({ message: "Access denied to this checklist" });
      }
      
      // Delete related runs and their items first (foreign key constraints)
      const relatedRuns = await db.select({ id: checklistRuns.id })
        .from(checklistRuns)
        .where(eq(checklistRuns.templateId, id));
      
      if (relatedRuns.length > 0) {
        const runIds = relatedRuns.map(r => r.id);
        // Run items cascade from runs, but delete explicitly to be safe
        await db.delete(checklistRunItems).where(inArray(checklistRunItems.runId, runIds));
        await db.delete(checklistRuns).where(inArray(checklistRuns.id, runIds));
      }
      
      // Delete template items
      await db.delete(checklistTemplateItems).where(eq(checklistTemplateItems.templateId, id));
      
      // Delete the template
      await db.delete(checklistTemplates).where(eq(checklistTemplates.id, id));
      
      res.json({ success: true });
    } catch (error) {
      next(error);
    }
  });

  // List checklist runs for Ops Kanban board
  app.get("/api/checklist-runs/ops", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const requestedBranchId = req.query.branchId as string | undefined;
      const showArchived = req.query.showArchived === 'true';
      
      let effectiveBranchId: string | null = null;
      
      if (user.hasAllBranchesAccess) {
        if (requestedBranchId === 'all' || !requestedBranchId) {
          effectiveBranchId = null;
        } else {
          effectiveBranchId = requestedBranchId;
        }
      } else {
        if (user.allowedBranchIds.length === 0) {
          return res.status(403).json({ message: "No branch access configured" });
        }
        if (requestedBranchId && requestedBranchId !== 'all') {
          if (!canUserAccessBranch(user, requestedBranchId)) {
            return res.status(403).json({ message: "Access denied to this branch" });
          }
          effectiveBranchId = requestedBranchId;
        } else {
          effectiveBranchId = user.allowedBranchIds[0];
        }
      }

      // Materialize the current recurring period as a pending run. This keeps
      // Pending meaningful without requiring a separate scheduler, while the
      // period lookup makes repeated dashboard requests idempotent.
      const accessibleBranches = await db.select({ id: branches.id, timezone: branches.timezone })
        .from(branches)
        .where(and(
          eq(branches.tenantId, tenantId),
          effectiveBranchId
            ? eq(branches.id, effectiveBranchId)
            : user.hasAllBranchesAccess
              ? sql`true`
              : inArray(branches.id, user.allowedBranchIds),
        ));
      const accessibleBranchMap = new Map(accessibleBranches.map((branch) => [branch.id, branch]));
      const recurringTemplates = await db.select()
        .from(checklistTemplates)
        .where(and(
          eq(checklistTemplates.tenantId, tenantId),
          eq(checklistTemplates.isActive, true),
          inArray(checklistTemplates.recurrence, ["daily", "weekly", "monthly"]),
        ));
      const now = new Date();

      for (const template of recurringTemplates) {
        const targetBranchIds = template.branchIds?.length
          ? template.branchIds
          : template.branchId
            ? [template.branchId]
            : [...accessibleBranchMap.keys()];
        for (const targetBranchId of targetBranchIds.filter((id) => accessibleBranchMap.has(id))) {
          const timezone = accessibleBranchMap.get(targetBranchId)?.timezone || "Asia/Bangkok";
          const localDate = getLocalDateString(now, timezone);
          const [latestRun] = await db.select({ periodStart: checklistRuns.periodStart })
            .from(checklistRuns)
            .where(and(
              eq(checklistRuns.templateId, template.id),
              eq(checklistRuns.branchId, targetBranchId),
            ))
            .orderBy(desc(checklistRuns.periodStart))
            .limit(1);
          const templateItems = await db.select({ id: checklistTemplateItems.id })
            .from(checklistTemplateItems)
            .where(eq(checklistTemplateItems.templateId, template.id));

          let candidateDate = latestRun?.periodStart
            ? getLocalDateString(latestRun.periodStart, timezone)
            : getLocalDateString(template.createdAt || now, timezone);
          // Catch up elapsed occurrences after downtime or long periods without
          // dashboard visits. The cap prevents a legacy template from causing
          // unbounded work on its first lifecycle-aware request.
          const earliestCatchup = addLocalDays(localDate, -370);
          if (candidateDate < earliestCatchup) candidateDate = earliestCatchup;
          for (let iteration = 0; candidateDate <= localDate && iteration < 371; iteration++, candidateDate = addLocalDays(candidateDate, 1)) {
            const candidateNoon = new Date(`${candidateDate}T12:00:00Z`);
            const weekday = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"][candidateNoon.getUTCDay()];
            if (template.recurrence === "weekly" && template.weeklyDays?.length && !template.weeklyDays.includes(weekday)) continue;
            if (template.recurrence === "monthly") {
              const localDay = Number(candidateDate.slice(-2));
              const daysInMonth = new Date(Date.UTC(Number(candidateDate.slice(0, 4)), Number(candidateDate.slice(5, 7)), 0)).getUTCDate();
              if (localDay !== Math.min(template.monthlyDay || 1, daysInMonth)) continue;
            }
            const referenceDate = createDateTimeInTimezone(candidateDate, "12:00", timezone);
            const period = getChecklistPeriod(template, referenceDate, timezone);
            const responsibleStaff = await getChecklistResponsibleStaff(
              tenantId,
              targetBranchId,
              template,
              period.dueAt,
              timezone,
              template.scheduledTime,
            );
            const runId = crypto.randomUUID();
            const isExpired = period.end <= now;
            const insertedRuns = await db.insert(checklistRuns).values({
              id: runId,
              tenantId,
              templateId: template.id,
              branchId: targetBranchId,
              status: isExpired ? "missed" : "pending",
              dueAt: period.dueAt,
              periodStart: period.start,
              periodEnd: period.end,
              missedAt: isExpired ? period.end : null,
              responsibleStaff,
              templateVersionApplied: template.templateVersion || 1,
              createdAt: now,
              updatedAt: now,
            }).onConflictDoNothing().returning({ id: checklistRuns.id });
            if (insertedRuns.length === 0 || templateItems.length === 0) continue;
            await db.insert(checklistRunItems).values(templateItems.map((item) => ({
                id: crypto.randomUUID(),
                tenantId,
                runId,
                templateItemId: item.id,
                isCompleted: false,
                createdAt: now,
              })));
          }
        }
      }
      
      const conditions = [
        eq(checklistRuns.tenantId, tenantId),
      ];
      
      if (effectiveBranchId) {
        conditions.push(eq(checklistRuns.branchId, effectiveBranchId));
      }
      
      const runs = await db.select()
        .from(checklistRuns)
        .where(and(...conditions))
        .orderBy(desc(checklistRuns.createdAt))
        .limit(200);
      
      if (runs.length === 0) {
        return res.json([]);
      }
      
      const templateIds = [...new Set(runs.map(r => r.templateId).filter(Boolean))] as string[];
      const templateRows = templateIds.length > 0 
        ? await db.select({ 
            id: checklistTemplates.id, 
            name: checklistTemplates.name, 
            departmentId: checklistTemplates.departmentId,
            assignedDepartmentId: checklistTemplates.assignedDepartmentId,
            assignedEmployeeId: checklistTemplates.assignedEmployeeId,
            assignedRoleId: checklistTemplates.assignedRoleId,
            checklistType: checklistTemplates.checklistType,
            recurrence: checklistTemplates.recurrence,
            weeklyDays: checklistTemplates.weeklyDays,
            monthlyDay: checklistTemplates.monthlyDay,
            scheduledTime: checklistTemplates.scheduledTime,
          }).from(checklistTemplates).where(inArray(checklistTemplates.id, templateIds))
        : [];
      const templateMap = new Map(templateRows.map(t => [t.id, t]));

      const branchIdsForTimezone = [...new Set(runs.map((run) => run.branchId).filter(Boolean))] as string[];
      const branchTimezoneRows = branchIdsForTimezone.length > 0
        ? await db.select({ id: branches.id, timezone: branches.timezone })
          .from(branches)
          .where(inArray(branches.id, branchIdsForTimezone))
        : [];
      const branchTimezoneMap = new Map(branchTimezoneRows.map((branch) => [branch.id, branch.timezone || "Asia/Bangkok"]));

      // Backfill periods for older runs and close incomplete periods exactly once.
      // The persisted period makes this idempotent and keeps history stable after
      // a template schedule or branch timezone is changed.
      for (const run of runs) {
        const template = templateMap.get(run.templateId);
        if (!template) continue;
        const timezone = branchTimezoneMap.get(run.branchId) || "Asia/Bangkok";
        const period = run.periodStart && run.periodEnd
          ? { start: run.periodStart, end: run.periodEnd, dueAt: run.dueAt || run.periodStart }
          : getChecklistPeriod(template, run.dueAt || run.createdAt, timezone);
        const needsBackfill = !run.periodStart || !run.periodEnd;
        const shouldMiss = (run.status === "pending" || run.status === "in_progress") && new Date() >= period.end;
        if (needsBackfill || shouldMiss) {
          await db.update(checklistRuns)
            .set({
              periodStart: period.start,
              periodEnd: period.end,
              dueAt: run.dueAt || period.dueAt,
              ...(shouldMiss ? { status: "missed", missedAt: run.missedAt || new Date() } : {}),
              updatedAt: new Date(),
            })
            .where(eq(checklistRuns.id, run.id));
          Object.assign(run, {
            periodStart: period.start,
            periodEnd: period.end,
            dueAt: run.dueAt || period.dueAt,
            ...(shouldMiss ? { status: "missed", missedAt: run.missedAt || new Date() } : {}),
          });
        }
      }

      const filterNow = new Date();
      const sevenDaysAgo = new Date(filterNow);
      sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
      const visibleRuns = showArchived
        ? runs
        : runs.filter((run) => {
          if (run.status === "missed") {
            const timezone = branchTimezoneMap.get(run.branchId) || "Asia/Bangkok";
            const localToday = getLocalDateString(filterNow, timezone);
            const localDueDate = run.dueAt ? getLocalDateString(run.dueAt, timezone) : null;
            const oldestVisibleDate = addLocalDays(localToday, -2);
            return !!localDueDate && localDueDate >= oldestVisibleDate && localDueDate <= localToday;
          }
          return run.status !== "completed" || !run.completedAt || run.completedAt >= sevenDaysAgo;
        });
      
      const assignedUserIds = [...new Set(visibleRuns.map(r => r.assignedTo).filter(Boolean))] as string[];
      const userRows = assignedUserIds.length > 0
        ? await db.select({ id: users.id, username: users.username, role: users.role }).from(users).where(inArray(users.id, assignedUserIds))
        : [];
      const userMap = new Map(userRows.map(u => [u.id, u.username]));
      const userRoleMap = new Map(userRows.map(u => [u.id, u.role]));
      
      const assignedEmployeeIds = [...new Set(templateRows.map(t => t.assignedEmployeeId).filter(Boolean))] as string[];
      const employeeUserRows = assignedEmployeeIds.length > 0
        ? await db.select({ employeeId: employees.id, role: users.role, primaryDepartmentId: employees.primaryDepartmentId })
            .from(employees)
            .leftJoin(users, eq(employees.userId, users.id))
            .where(inArray(employees.id, assignedEmployeeIds))
        : [];
      const employeeRoleMap = new Map(employeeUserRows.filter(e => e.role).map(e => [e.employeeId, e.role!]));
      const runEmployeeDeptMap = new Map(employeeUserRows.map(e => [e.employeeId, e.primaryDepartmentId]));
      
      let runEmployeeHrRoleIdsMap = new Map<string, string>();
      if (assignedEmployeeIds.length > 0) {
        const hrRoleRows = await db.select({ employeeId: employeeRoles.employeeId, roleId: employeeRoles.roleId })
          .from(employeeRoles)
          .where(inArray(employeeRoles.employeeId, assignedEmployeeIds));
        const grouped = new Map<string, string[]>();
        for (const row of hrRoleRows) {
          if (!grouped.has(row.employeeId)) grouped.set(row.employeeId, []);
          grouped.get(row.employeeId)!.push(row.roleId);
        }
        runEmployeeHrRoleIdsMap = new Map([...grouped.entries()].map(([k, v]) => [k, v.join(',')]));
      }
      
      const branchIds = [...new Set(visibleRuns.map(r => r.branchId).filter(Boolean))] as string[];
      const branchRows = branchIds.length > 0
        ? await db.select({ id: branches.id, name: branches.name }).from(branches).where(inArray(branches.id, branchIds))
        : [];
      const branchMap = new Map(branchRows.map(b => [b.id, b.name]));
      
      const deptIds = [...new Set([
        ...templateRows.map(t => t.departmentId).filter(Boolean),
        ...templateRows.map(t => t.assignedDepartmentId).filter(Boolean),
      ])] as string[];
      const deptRows = deptIds.length > 0
        ? await db.select({ id: departments.id, name: departments.name }).from(departments).where(inArray(departments.id, deptIds))
        : [];
      const deptMap = new Map(deptRows.map(d => [d.id, d.name]));
      
      const runIds = visibleRuns.map(r => r.id);
      const allItems = await db.select({
        runId: checklistRunItems.runId,
        isCompleted: checklistRunItems.isCompleted,
        resultStatus: checklistRunItems.resultStatus,
      }).from(checklistRunItems).where(inArray(checklistRunItems.runId, runIds));
      
      const itemStats = new Map<string, { total: number; completed: number; failed: number }>();
      for (const item of allItems) {
        const stats = itemStats.get(item.runId) || { total: 0, completed: 0, failed: 0 };
        stats.total++;
        if (item.isCompleted) stats.completed++;
        if (item.resultStatus === 'fail') stats.failed++;
        itemStats.set(item.runId, stats);
      }
      
      const enrichedRuns = visibleRuns.map(run => {
        const template = run.templateId ? templateMap.get(run.templateId) : null;
        const stats = itemStats.get(run.id) || { total: 0, completed: 0, failed: 0 };
        const effectiveDeptId = template?.assignedDepartmentId || template?.departmentId || null;
        const resolvedUserRole = run.assignedTo 
          ? userRoleMap.get(run.assignedTo) || null
          : template?.assignedEmployeeId 
            ? employeeRoleMap.get(template.assignedEmployeeId) || null
            : null;
        return {
          id: run.id,
          templateId: run.templateId,
          templateName: template?.name || "Unknown",
          checklistType: template?.checklistType || "operational",
          branchId: run.branchId,
          branchName: branchMap.get(run.branchId) || null,
          departmentId: effectiveDeptId,
          departmentName: effectiveDeptId ? deptMap.get(effectiveDeptId) || null : null,
          assignedTo: run.assignedTo,
          assignedUserName: run.assignedTo ? userMap.get(run.assignedTo) || null : null,
          assignedEmployeeId: template?.assignedEmployeeId || null,
          assignedRoleId: template?.assignedRoleId || null,
          assignedDepartmentId: template?.assignedDepartmentId || null,
          assignedUserRole: resolvedUserRole,
          assignedEmployeeDepartmentId: template?.assignedEmployeeId ? runEmployeeDeptMap.get(template.assignedEmployeeId) || null : null,
          assignedEmployeeRoleIds: template?.assignedEmployeeId ? runEmployeeHrRoleIdsMap.get(template.assignedEmployeeId) || null : null,
          status: run.status,
          dueAt: run.dueAt,
          startedAt: run.startedAt,
          completedAt: run.completedAt,
          createdAt: run.createdAt,
          updatedAt: run.updatedAt,
          notes: run.notes,
          periodStart: run.periodStart,
          periodEnd: run.periodEnd,
          missedAt: run.missedAt,
          responsibleStaff: run.responsibleStaff || [],
          itemsTotal: stats.total,
          itemsCompleted: stats.completed,
          itemsFailed: stats.failed,
        };
      });
      
      res.json(enrichedRuns);
    } catch (error) {
      next(error);
    }
  });

  // Checklist history is deliberately separate from the current dashboard so
  // repeated misses remain useful without becoming stale dashboard cards.
  app.get("/api/checklist-runs/history", requireAuth, requireManager, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const requestedBranchId = req.query.branchId as string | undefined;
      let effectiveBranchId: string | null = null;

      if (user.hasAllBranchesAccess) {
        effectiveBranchId = requestedBranchId && requestedBranchId !== "all" ? requestedBranchId : null;
      } else {
        if (user.allowedBranchIds.length === 0) {
          return res.status(403).json({ message: "No branch access configured" });
        }
        if (requestedBranchId && requestedBranchId !== "all") {
          if (!canUserAccessBranch(user, requestedBranchId)) {
            return res.status(403).json({ message: "Access denied to this branch" });
          }
          effectiveBranchId = requestedBranchId;
        }
      }

      const conditions = [
        eq(checklistRuns.tenantId, tenantId),
        inArray(checklistRuns.status, ["missed", "completed"]),
      ];
      if (effectiveBranchId) {
        conditions.push(eq(checklistRuns.branchId, effectiveBranchId));
      } else if (!user.hasAllBranchesAccess) {
        conditions.push(inArray(checklistRuns.branchId, user.allowedBranchIds));
      }

      const rows = await db.select({
        id: checklistRuns.id,
        templateId: checklistRuns.templateId,
        templateName: checklistTemplates.name,
        recurrence: checklistTemplates.recurrence,
        scheduledTime: checklistTemplates.scheduledTime,
        assignedEmployeeId: checklistTemplates.assignedEmployeeId,
        assignedRoleId: checklistTemplates.assignedRoleId,
        assignedDepartmentId: checklistTemplates.assignedDepartmentId,
        departmentId: checklistTemplates.departmentId,
        departmentName: departments.name,
        branchId: checklistRuns.branchId,
        branchName: branches.name,
        branchTimezone: branches.timezone,
        status: checklistRuns.status,
        dueAt: checklistRuns.dueAt,
        periodStart: checklistRuns.periodStart,
        periodEnd: checklistRuns.periodEnd,
        completedAt: checklistRuns.completedAt,
        missedAt: checklistRuns.missedAt,
        responsibleStaff: checklistRuns.responsibleStaff,
      })
        .from(checklistRuns)
        .innerJoin(checklistTemplates, eq(checklistRuns.templateId, checklistTemplates.id))
        .innerJoin(branches, eq(checklistRuns.branchId, branches.id))
        .leftJoin(departments, or(
          eq(checklistTemplates.assignedDepartmentId, departments.id),
          and(isNull(checklistTemplates.assignedDepartmentId), eq(checklistTemplates.departmentId, departments.id)),
        ))
        .where(and(...conditions))
        .orderBy(desc(sql`COALESCE(${checklistRuns.missedAt}, ${checklistRuns.completedAt}, ${checklistRuns.updatedAt})`))
        .limit(1000);

      // Older runs may have stored an empty snapshot when the schedule row did
      // not carry a department even though the employee profile did. Repair only
      // empty missed snapshots; preserve staff already recorded on the run.
      for (const row of rows) {
        if (row.status !== "missed" || row.responsibleStaff?.length || !row.dueAt) continue;
        const responsibleStaff = await getChecklistResponsibleStaff(
          tenantId,
          row.branchId,
          row,
          row.dueAt,
          row.branchTimezone || "Asia/Bangkok",
          row.scheduledTime,
        );
        if (responsibleStaff.length === 0) continue;
        row.responsibleStaff = responsibleStaff;
        await db.update(checklistRuns)
          .set({ responsibleStaff, updatedAt: new Date() })
          .where(eq(checklistRuns.id, row.id));
      }

      const completed = rows.filter((row) => row.status === "completed");
      const missedGroups = new Map<string, {
        key: string;
        templateId: string;
        templateName: string;
        recurrence: string | null;
        periodStart: Date | null;
        periodEnd: Date | null;
        count: number;
        runs: typeof rows;
      }>();

      for (const row of rows.filter((record) => record.status === "missed")) {
        const source = row.periodStart || row.dueAt || row.missedAt || new Date();
        let groupPeriodStart = getLocalDateString(source, row.branchTimezone || "Asia/Bangkok");
        if (row.recurrence === "daily") {
          const localNoon = new Date(`${groupPeriodStart}T12:00:00Z`);
          const day = localNoon.getUTCDay();
          groupPeriodStart = addLocalDays(groupPeriodStart, -(day === 0 ? 6 : day - 1));
        }
        const key = `${row.branchId}:${row.templateId}:${groupPeriodStart}`;
        const group = missedGroups.get(key) || {
          key,
          templateId: row.templateId,
          templateName: row.templateName,
          recurrence: row.recurrence,
          periodStart: row.periodStart,
          periodEnd: row.periodEnd,
          count: 0,
          runs: [],
        };
        group.count += 1;
        group.runs.push(row);
        missedGroups.set(key, group);
      }

      res.json({ missedGroups: [...missedGroups.values()], completed });
    } catch (error) {
      next(error);
    }
  });

  // Start a checklist run
  app.post("/api/checklist-runs/start", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const { templateId, branchId: requestBranchId } = req.body;
      
      if (!templateId) {
        return res.status(400).json({ message: "templateId is required" });
      }
      
      // Get template to verify access and get branch info
      const template = await storage.getChecklistTemplateWithItems(templateId, tenantId);
      if (!template) {
        return res.status(404).json({ message: "Checklist template not found" });
      }
      
      // Verify branch access
      if (template.branchId && !canUserAccessBranch(user, template.branchId)) {
        return res.status(403).json({ message: "Access denied to this checklist" });
      }
      
      const effectiveBranchId = template.branchId || requestBranchId || user.allowedBranchIds[0];
      if (!effectiveBranchId) {
        return res.status(400).json({ message: "Could not determine branch for this checklist run" });
      }
      if (!canUserAccessBranch(user, effectiveBranchId)) {
        return res.status(403).json({ message: "Access denied to this branch" });
      }
      
      // Create the checklist run
      const runId = crypto.randomUUID();
      const now = new Date();
      const [runBranch] = await db.select({ timezone: branches.timezone })
        .from(branches)
        .where(and(eq(branches.id, effectiveBranchId), eq(branches.tenantId, tenantId)))
        .limit(1);
      const period = getChecklistPeriod(template, now, runBranch?.timezone || "Asia/Bangkok");
      const responsibleStaff = await getChecklistResponsibleStaff(
        tenantId,
        effectiveBranchId,
        template,
        period.dueAt,
        runBranch?.timezone || "Asia/Bangkok",
        template.scheduledTime,
      );
      const [existingPeriodRun] = await db.select()
        .from(checklistRuns)
        .where(and(
          eq(checklistRuns.templateId, templateId),
          eq(checklistRuns.branchId, effectiveBranchId),
          eq(checklistRuns.periodStart, period.start),
          inArray(checklistRuns.status, ["pending", "in_progress"]),
        ))
        .orderBy(desc(checklistRuns.createdAt))
        .limit(1);
      if (existingPeriodRun) {
        await db.update(checklistRuns)
          .set({
            status: "in_progress",
            assignedTo: user.id,
            startedAt: existingPeriodRun.startedAt || now,
            responsibleStaff: existingPeriodRun.responsibleStaff?.length ? existingPeriodRun.responsibleStaff : responsibleStaff,
            updatedAt: now,
          })
          .where(eq(checklistRuns.id, existingPeriodRun.id));
        return res.json({
          id: existingPeriodRun.id,
          templateId,
          status: "in_progress",
          dueAt: existingPeriodRun.dueAt || period.dueAt,
          periodStart: existingPeriodRun.periodStart || period.start,
          periodEnd: existingPeriodRun.periodEnd || period.end,
          responsibleStaff: existingPeriodRun.responsibleStaff?.length ? existingPeriodRun.responsibleStaff : responsibleStaff,
        });
      }
      
      const inserted = await db.insert(checklistRuns).values({
        id: runId,
        tenantId: tenantId,
        templateId: templateId,
        branchId: effectiveBranchId,
        assignedTo: user.id,
        status: 'in_progress',
        templateVersionApplied: template.templateVersion || 1,
        startedAt: now,
        dueAt: period.dueAt,
        periodStart: period.start,
        periodEnd: period.end,
        responsibleStaff,
        createdAt: now,
        updatedAt: now,
      }).onConflictDoNothing().returning({ id: checklistRuns.id });
      if (inserted.length === 0) {
        const [winner] = await db.select()
          .from(checklistRuns)
          .where(and(
            eq(checklistRuns.tenantId, tenantId),
            eq(checklistRuns.templateId, templateId),
            eq(checklistRuns.branchId, effectiveBranchId),
            eq(checklistRuns.periodStart, period.start),
          ))
          .limit(1);
        if (!winner) return res.status(409).json({ message: "Checklist run already exists" });
        return res.json({ ...winner, status: winner.status });
      }
      
      // Create run items from template items
      const templateItems = template.items || [];
      if (templateItems.length > 0) {
        const runItemsToInsert = templateItems.map((item: any) => ({
          id: crypto.randomUUID(),
          tenantId: tenantId,
          runId: runId,
          templateItemId: item.id,
          isCompleted: false,
          createdAt: now,
        }));
        
        await db.insert(checklistRunItems).values(runItemsToInsert);
      }
      
      res.json({
        id: runId,
        templateId,
        status: 'in_progress',
        dueAt: period.dueAt,
        periodStart: period.start,
        periodEnd: period.end,
        responsibleStaff,
      });
    } catch (error) {
      next(error);
    }
  });

  // Get a specific checklist run with items
  app.get("/api/checklist-runs/:id", requireAuth, async (req, res, next) => {
    try {
      const { id } = req.params;
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      
      // Get the run
      const runs = await db.select()
        .from(checklistRuns)
        .where(and(eq(checklistRuns.id, id), eq(checklistRuns.tenantId, tenantId)))
        .limit(1);
      
      if (runs.length === 0) {
        return res.status(404).json({ message: "Checklist run not found" });
      }
      
      const run = runs[0];
      if (!canUserAccessBranch(user, run.branchId)) {
        return res.status(403).json({ message: "Access denied to this checklist run" });
      }
      
      // Get template with items
      const template = await storage.getChecklistTemplateWithItems(run.templateId!, tenantId);
      
      // Get run items with template item details
      const runItems = await db.select()
        .from(checklistRunItems)
        .where(eq(checklistRunItems.runId, id));

      const completionUserIds = Array.from(new Set([
        run.completedBy,
        ...runItems.map((item) => item.completedBy),
      ].filter((userId): userId is string => Boolean(userId))));
      const completionUsers = completionUserIds.length > 0
        ? await db.select({
            id: users.id,
            preferredName: users.preferredName,
            fullName: users.fullName,
          })
          .from(users)
          .where(inArray(users.id, completionUserIds))
        : [];
      const completionNamesByUserId = new Map(
        completionUsers.map((completionUser) => [
          completionUser.id,
          completionUser.preferredName || completionUser.fullName,
        ]),
      );

      const runItemIds = runItems.map((item) => item.id);
      const linkedReports = runItemIds.length > 0
        ? await db.select({
            id: fixReports.id,
            sourceChecklistRunItemId: fixReports.sourceChecklistRunItemId,
            title: fixReports.title,
            status: fixReports.status,
            createdAt: fixReports.createdAt,
          })
          .from(fixReports)
          .where(and(
            eq(fixReports.tenantId, tenantId),
            inArray(fixReports.sourceChecklistRunItemId, runItemIds),
          ))
          .orderBy(desc(fixReports.createdAt))
        : [];
      const linkedReportsByItem = new Map<string, typeof linkedReports>();
      for (const report of linkedReports) {
        if (!report.sourceChecklistRunItemId) continue;
        const current = linkedReportsByItem.get(report.sourceChecklistRunItemId) || [];
        current.push(report);
        linkedReportsByItem.set(report.sourceChecklistRunItemId, current);
      }
      
      // Create a map of template items by id
      const templateItemsMap = new Map((template.items || []).map((item: any) => [item.id, item]));
      
      // Combine run items with template item details
      const items = runItems.map(runItem => ({
        ...runItem,
        completed: runItem.isCompleted,
        completedByName: runItem.completedBy
          ? completionNamesByUserId.get(runItem.completedBy) || null
          : null,
        templateItem: templateItemsMap.get(runItem.templateItemId) || null,
        linkedFixReports: linkedReportsByItem.get(runItem.id) || [],
      }));
      
      // Sort by templateItem.sortOrder to maintain consistent order
      items.sort((a, b) => {
        const sortA = a.templateItem?.sortOrder ?? 999;
        const sortB = b.templateItem?.sortOrder ?? 999;
        return sortA - sortB;
      });
      
      res.json({
        ...run,
        completedByName: run.completedBy
          ? completionNamesByUserId.get(run.completedBy) || null
          : null,
        template,
        items,
      });
    } catch (error) {
      next(error);
    }
  });

  // Update a checklist run item
  app.patch("/api/checklist-run-items/:itemId", requireAuth, async (req, res, next) => {
    try {
      const { itemId } = req.params;
      const { completed, note, completedAt, photoEvidenceUrls, resultStatus, failNote, failPhotoUrl } = req.body;
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const [authorizedItem] = await db.select({
        id: checklistRunItems.id,
        runId: checklistRunItems.runId,
        branchId: checklistRuns.branchId,
        status: checklistRuns.status,
      })
        .from(checklistRunItems)
        .innerJoin(checklistRuns, eq(checklistRunItems.runId, checklistRuns.id))
        .where(and(eq(checklistRunItems.id, itemId), eq(checklistRunItems.tenantId, tenantId), eq(checklistRuns.tenantId, tenantId)))
        .limit(1);
      if (!authorizedItem) {
        return res.status(404).json({ message: "Checklist item not found" });
      }
      if (!canUserAccessBranch(user, authorizedItem.branchId)) {
        return res.status(403).json({ message: "Access denied to this checklist item" });
      }
      if (authorizedItem.status === "completed" || authorizedItem.status === "missed") {
        return res.status(409).json({ message: "This checklist run is read-only" });
      }
      
      const updates: any = {};
      
      if (typeof completed === 'boolean') {
        updates.isCompleted = completed;
        if (completed) {
          updates.completedBy = user.id;
          updates.completedAt = completedAt ? new Date(completedAt) : new Date();
        } else {
          updates.completedBy = null;
          updates.completedAt = null;
        }
      }
      
      if (note !== undefined) {
        updates.note = note;
      }
      
      if (photoEvidenceUrls !== undefined) {
        updates.photoEvidenceUrls = photoEvidenceUrls;
      }
      
      // Checker-specific fields
      if (resultStatus !== undefined) {
        updates.resultStatus = resultStatus;
        // If switching to PASS, clear fail fields
        if (resultStatus === 'pass') {
          updates.failNote = null;
          updates.failPhotoUrl = null;
        }
      }
      
      if (failNote !== undefined) {
        updates.failNote = failNote;
      }
      
      if (failPhotoUrl !== undefined) {
        updates.failPhotoUrl = failPhotoUrl;
      }
      
      await db.update(checklistRunItems)
        .set(updates)
        .where(and(eq(checklistRunItems.id, itemId), eq(checklistRunItems.tenantId, tenantId)));
      
      // Auto-transition run status based on item changes
      const [updatedItem] = await db.select().from(checklistRunItems).where(eq(checklistRunItems.id, itemId)).limit(1);
      if (updatedItem) {
        const [currentRun] = await db.select().from(checklistRuns).where(eq(checklistRuns.id, updatedItem.runId)).limit(1);
        if (currentRun && currentRun.status === 'pending') {
          await db.update(checklistRuns)
            .set({ status: 'in_progress', startedAt: new Date(), updatedAt: new Date() })
            .where(eq(checklistRuns.id, updatedItem.runId));
        }

        // Auto-create attention item when checker item is marked FAIL
        if (resultStatus === 'fail' && currentRun) {
          const templateItem = await db.select()
            .from(checklistTemplateItems)
            .where(eq(checklistTemplateItems.id, updatedItem.templateItemId))
            .limit(1);
          const itemTitle = templateItem[0]?.title || 'Unknown item';
          const template = await db.select()
            .from(checklistTemplates)
            .where(eq(checklistTemplates.id, currentRun.templateId!))
            .limit(1);
          const checklistName = template[0]?.name || 'Unknown checklist';

          await storage.createAttentionItem({
            type: 'CHECKLIST_AUDIT_FAIL',
            severity: 'high',
            branchId: currentRun.branchId || undefined,
            title: `Audit fail: ${itemTitle}`,
            description: `Checklist "${checklistName}" item "${itemTitle}" was marked as FAIL.${failNote ? ` Note: ${failNote}` : ''}${failPhotoUrl ? ` Photo evidence attached.` : ''}`,
          });
        }
      }

      // Flag notes with problem keywords
      if (note && typeof note === 'string') {
        const problemKeywords = ['broken', 'missing', 'issue', 'damaged', 'leak', 'unsafe', 'hazard', 'fault', 'defect'];
        const lowerNote = note.toLowerCase();
        const foundKeywords = problemKeywords.filter(kw => lowerNote.includes(kw));
        if (foundKeywords.length > 0 && updatedItem) {
          const [currentRun2] = await db.select().from(checklistRuns).where(eq(checklistRuns.id, updatedItem.runId)).limit(1);
          if (currentRun2) {
            const templateItem2 = await db.select()
              .from(checklistTemplateItems)
              .where(eq(checklistTemplateItems.id, updatedItem.templateItemId))
              .limit(1);
            const itemTitle2 = templateItem2[0]?.title || 'Unknown item';

            await storage.createAttentionItem({
              type: 'CHECKLIST_NOTE_FLAGGED',
              severity: 'medium',
              branchId: currentRun2.branchId || undefined,
              title: `Flagged note: ${itemTitle2}`,
              description: `A checklist note contains problem keywords (${foundKeywords.join(', ')}): "${note}"`,
            });
          }
        }
      }
      
      res.json({ success: true });
    } catch (error) {
      next(error);
    }
  });

  // Update a checklist run (complete, etc.)
  app.patch("/api/checklist-runs/:id", requireAuth, async (req, res, next) => {
    try {
      const { id } = req.params;
      const { status } = req.body;
      const now = new Date();
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const [authorizedRun] = await db.select()
        .from(checklistRuns)
        .where(and(eq(checklistRuns.id, id), eq(checklistRuns.tenantId, tenantId)))
        .limit(1);
      if (!authorizedRun) {
        return res.status(404).json({ message: "Checklist run not found" });
      }
      if (!canUserAccessBranch(user, authorizedRun.branchId)) {
        return res.status(403).json({ message: "Access denied to this checklist run" });
      }
      
      const updates: any = {
        updatedAt: now,
      };
      
      if (status) {
        if (!["pending", "in_progress", "issues", "completed"].includes(status)) {
          return res.status(400).json({ message: "Invalid checklist status" });
        }
        if (status === 'completed') {
          const runToComplete = authorizedRun;
          if (runToComplete) {
            const templateToCheck = await storage.getChecklistTemplateWithItems(runToComplete.templateId!, tenantId);
            const allRunItems = await db.select()
              .from(checklistRunItems)
              .where(eq(checklistRunItems.runId, id));
            const templateItemsById = new Map(
              (templateToCheck?.items ?? []).map((item: any) => [item.id, item])
            );
            const itemsMissingRequiredPhotos = allRunItems.filter((item) => {
              const templateItem: any = templateItemsById.get(item.templateItemId);
              const requiresPhoto = templateItem?.linkedToFix !== true
                && templateItem?.requiresPhoto === true;
              return requiresPhoto && (!Array.isArray(item.photoEvidenceUrls) || item.photoEvidenceUrls.length === 0);
            });
            if (itemsMissingRequiredPhotos.length > 0) {
              return res.status(400).json({
                message: `Cannot complete checklist: ${itemsMissingRequiredPhotos.length} item(s) need photo evidence`,
              });
            }
            
            if (templateToCheck && templateToCheck.checklistType === 'checker') {
              const itemsWithoutResult = allRunItems.filter(item => !item.resultStatus);
              if (itemsWithoutResult.length > 0) {
                return res.status(400).json({ 
                  message: `Cannot complete checker run: ${itemsWithoutResult.length} item(s) need Pass/Fail status` 
                });
              }
              
              const failedItems = allRunItems.filter(item => item.resultStatus === 'fail');
              if (failedItems.length > 0) {
                updates.status = 'issues';
              } else {
                updates.status = 'completed';
                updates.completedAt = now;
                updates.completedBy = user.id;
              }
            } else {
              const incompleteItems = allRunItems.filter(item => !item.isCompleted);
              if (incompleteItems.length > 0) {
                updates.status = 'issues';
              } else {
                updates.status = 'completed';
                updates.completedAt = now;
                updates.completedBy = user.id;
              }
            }
          }
        } else {
          updates.status = status;
          if (status === 'completed') {
            updates.completedAt = now;
          }
        }
      }
      
      await db.update(checklistRuns)
        .set(updates)
        .where(and(eq(checklistRuns.id, id), eq(checklistRuns.tenantId, tenantId)));
      
      // If completing a CHECKER checklist, auto-create tasks for FAIL items
      if (updates.status === 'completed' || updates.status === 'issues') {
        // Get the run and template
        const [run] = await db.select().from(checklistRuns).where(and(eq(checklistRuns.id, id), eq(checklistRuns.tenantId, tenantId))).limit(1);
        if (run) {
          const template = await storage.getChecklistTemplateWithItems(run.templateId!, tenantId);
          
          if (template && template.checklistType === 'checker') {
            // Get all run items with FAIL status that don't have a task yet
            const runItems = await db.select()
              .from(checklistRunItems)
              .where(and(
                eq(checklistRunItems.runId, id),
                eq(checklistRunItems.resultStatus, 'fail'),
                isNull(checklistRunItems.createdTaskId)
              ));
            
            // Create tasks for each FAIL item
            for (const runItem of runItems) {
              // Get the template item to find departmentId and other details
              const templateItem = template.items?.find((ti: any) => ti.id === runItem.templateItemId);
              if (!templateItem) continue;
              
              const taskDepartmentId = templateItem.departmentId || template.departmentId;
              
              const taskId = crypto.randomUUID();
              const taskTitle = `Checker fail – ${templateItem.title}`;
              const taskDescription = [
                `**Checklist:** ${template.name}`,
                `**Checked at:** ${now.toLocaleString()}`,
                templateItem.zoneLabel ? `**Zone:** ${templateItem.zoneLabel}` : null,
                runItem.failNote ? `**Issue:** ${runItem.failNote}` : null,
              ].filter(Boolean).join('\n');
              
              // Create the task - include fail photo as reference
              await db.insert(tasks).values({
                id: taskId,
                tenantId,
                branchId: run.branchId,
                departmentId: taskDepartmentId || null,
                assignedDepartmentId: taskDepartmentId || null,
                title: taskTitle,
                description: taskDescription,
                status: 'pending',
                priority: 'medium',
                referencePhotoUrl: runItem.failPhotoUrl || null, // Include fail photo in task
                createdAt: now,
                updatedAt: now,
              });
              
              // Update the run item with the created task ID
              await db.update(checklistRunItems)
                .set({ createdTaskId: taskId })
                .where(eq(checklistRunItems.id, runItem.id));
            }
          }
        }
      }
      
      res.json({ success: true, status });
    } catch (error) {
      next(error);
    }
  });

  // Manager/Admin override checklist run status
  app.post("/api/checklist-runs/:id/override-status", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { id } = req.params;
      const { newStatus } = req.body;
      const user = req.user as UserWithBranchAccess;
      const now = new Date();
      const tenantId = await resolveTenantId(user.tenantId);
      
      const validStatuses = ['pending', 'in_progress', 'issues', 'completed'];
      if (!validStatuses.includes(newStatus)) {
        return res.status(400).json({ message: "Invalid status" });
      }
      
      const [run] = await db.select().from(checklistRuns).where(and(eq(checklistRuns.id, id), eq(checklistRuns.tenantId, tenantId))).limit(1);
      if (!run) {
        return res.status(404).json({ message: "Checklist run not found" });
      }
      if (run.tenantId !== tenantId) {
        return res.status(404).json({ message: "Checklist run not found" });
      }
      if (!canUserAccessBranch(user, run.branchId)) {
        return res.status(403).json({ message: "Access denied to this checklist run" });
      }
      
      const oldStatus = run.status;
      
      const updates: any = {
        status: newStatus,
        updatedAt: now,
      };
      
      if (newStatus === 'completed') {
        updates.completedAt = now;
        updates.completedBy = user.id;
      }
      
      await db.update(checklistRuns)
        .set(updates)
        .where(and(eq(checklistRuns.id, id), eq(checklistRuns.tenantId, tenantId)));
      
      console.log(`[AUDIT] Checklist run ${id} status override: ${oldStatus} -> ${newStatus} by user ${user.id} at ${now.toISOString()}`);
      
      res.json({ success: true, oldStatus, newStatus });
    } catch (error) {
      next(error);
    }
  });

  app.get("/api/checklist-runs/activities/recent", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const branchId = req.query.branchId as string | undefined;
      const limitNum = Math.min(parseInt(req.query.limit as string) || 30, 100);

      const conditions: any[] = [eq(checklistRuns.tenantId, tenantId)];

      if (branchId && branchId !== "all") {
        if (!canUserAccessBranch(user, branchId)) {
          return res.status(403).json({ message: "Access denied to this branch" });
        }
        conditions.push(eq(checklistRuns.branchId, branchId));
      } else if (!user.hasAllBranchesAccess && user.allowedBranchIds?.length) {
        conditions.push(inArray(checklistRuns.branchId, user.allowedBranchIds));
      }

      const result = await db
        .select({
          id: checklistRuns.id,
          templateId: checklistRuns.templateId,
          branchId: checklistRuns.branchId,
          status: checklistRuns.status,
          startedAt: checklistRuns.startedAt,
          completedAt: checklistRuns.completedAt,
          updatedAt: checklistRuns.updatedAt,
          templateName: checklistTemplates.name,
          userName: users.fullName,
          employeeNickname: employees.nickname,
        })
        .from(checklistRuns)
        .leftJoin(checklistTemplates, eq(checklistRuns.templateId, checklistTemplates.id))
        .leftJoin(users, eq(checklistRuns.assignedTo, users.id))
        .leftJoin(employees, eq(users.id, employees.userId))
        .where(and(...conditions))
        .orderBy(desc(checklistRuns.updatedAt))
        .limit(limitNum);

      const activities = result.map((run) => {
        const displayName = run.employeeNickname || run.userName || "Someone";
        let description = "";
        if (run.status === "completed") {
          description = `${displayName} completed checklist`;
        } else if (run.status === "issues") {
          description = `${displayName} completed checklist with issues`;
        } else if (run.status === "in_progress") {
          description = `${displayName} started checklist`;
        } else {
          description = `Checklist status changed to ${run.status}`;
        }
        return {
          id: run.id,
          templateName: run.templateName,
          branchId: run.branchId,
          status: run.status,
          description,
          userName: run.userName,
          employeeNickname: run.employeeNickname,
          updatedAt: run.updatedAt,
        };
      });

      res.json(activities);
    } catch (error) {
      next(error);
    }
  });

  // Get checker/inspection run history for a template (admin/manager only)
  app.get("/api/checklists/checker-history/:templateId", requireAuth, requireManager, async (req, res, next) => {
    try {
      const { templateId } = req.params;
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const limit = parseInt(req.query.limit as string) || 20;
      
      // Get the template to verify it's a checker type
      const template = await storage.getChecklistTemplateWithItems(templateId, tenantId);
      if (!template) {
        return res.status(404).json({ message: "Template not found" });
      }
      
      // Get recent runs for this template
      const runs = await db.select()
        .from(checklistRuns)
        .where(and(
          eq(checklistRuns.templateId, templateId),
          eq(checklistRuns.status, 'completed')
        ))
        .orderBy(desc(checklistRuns.completedAt))
        .limit(limit);
      
      // Get run items with result counts
      const runsWithStats = await Promise.all(runs.map(async (run) => {
        const items = await db.select()
          .from(checklistRunItems)
          .where(eq(checklistRunItems.runId, run.id));
        
        const passCount = items.filter((i: any) => i.resultStatus === 'pass').length;
        const failCount = items.filter((i: any) => i.resultStatus === 'fail').length;
        const totalItems = items.length;
        
        return {
          id: run.id,
          branchId: run.branchId,
          completedAt: run.completedAt,
          passCount,
          failCount,
          totalItems,
          hasFailures: failCount > 0,
        };
      }));
      
      res.json({
        templateId,
        templateName: template.name,
        runs: runsWithStats,
      });
    } catch (error) {
      next(error);
    }
  });

  // ============================================
  // SOP ARTICLES (franchise-ready scoping)
  // ============================================

  // List SOP articles with branch filtering
  app.get("/api/sops", requireAuth, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const user = req.user as UserWithBranchAccess;
      const requestedBranchId = req.query.branchId as string | undefined;
      
      // Determine effective branch filter:
      // - 'all' is only allowed for users with all_branches access (admins)
      // - Non-admins MUST have a valid branch ID to view content
      let effectiveBranchId: string | null = null;
      
      if (user.hasAllBranchesAccess) {
        // Admin can view all branches or specific branch
        if (requestedBranchId === 'all' || !requestedBranchId) {
          effectiveBranchId = null; // Admin viewing all
        } else {
          effectiveBranchId = requestedBranchId;
        }
      } else {
        // Non-admin: Must have branch access and use a valid branch
        if (!user.branchAccess || user.branchAccess.length === 0) {
          return res.status(403).json({ message: "No branch access configured" });
        }
        
        if (requestedBranchId && requestedBranchId !== 'all') {
          // Validate user has access to requested branch
          const hasAccess = user.branchAccess.some(ba => ba.branchId === requestedBranchId);
          if (!hasAccess) {
            return res.status(403).json({ message: "Access denied to this branch" });
          }
          effectiveBranchId = requestedBranchId;
        } else {
          // Default to first accessible branch for non-admins
          effectiveBranchId = user.branchAccess[0].branchId;
        }
      }
      
      const articles = await storage.getSopArticles(tenantId, effectiveBranchId);
      res.json(articles);
    } catch (error) {
      next(error);
    }
  });

