  // Upload knowledge file (PDF/image/video)
  app.post("/api/knowledge-files/upload", requireAuth, requireManager, knowledgeFileUpload.single("file"), fixMulterFilenames, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const user = req.user as UserWithBranchAccess;
      const file = req.file;
      
      if (!file) {
        return res.status(400).json({ message: "No file uploaded" });
      }

      // Determine file type
      let fileType: "pdf" | "image" | "video" = "pdf";
      if (file.mimetype.startsWith("image/")) {
        fileType = "image";
      } else if (file.mimetype.startsWith("video/")) {
        fileType = "video";
      } else if (file.mimetype !== "application/pdf") {
        return res.status(400).json({ message: "Unsupported file type. Only PDF, images, and videos are allowed." });
      }

      const timestamp = Date.now();
      const safeFilename = file.originalname.replace(/[\/\\:*?"<>|]/g, '_');
      const knowledgeFilename = `${timestamp}_${safeFilename}`;

      const storageUrl = await uploadToObjectStorage(
        file.buffer,
        "knowledge-files",
        knowledgeFilename,
        file.mimetype,
      );

      // Parse metadata from request body
      const { title, description, branchId, departmentId, language, tags, version } = req.body;

      console.log(`[KnowledgeFiles] Creating database record for: ${file.originalname}, storageUrl: ${storageUrl}`);

      // Create knowledge file record
      let knowledgeFile;
      try {
        knowledgeFile = await storage.createKnowledgeFile({
          tenantId,
          filename: file.originalname,
          fileType,
          storageUrl,
          mimeType: file.mimetype,
          sizeBytes: file.size,
          branchId: branchId || null,
          departmentId: departmentId || null,
          language: language || "en",
          tags: tags ? (typeof tags === "string" ? JSON.parse(tags) : tags) : [],
          version: version || null,
          title: title || file.originalname,
          description: description || null,
          createdByUserId: user.id,
          isActive: true,
          indexStatus: "pending",
        });
        console.log(`[KnowledgeFiles] Database record created: ${knowledgeFile.id}`);
      } catch (dbError: any) {
        console.error(`[KnowledgeFiles] Database error:`, dbError.message || dbError);
        return res.status(500).json({ message: "Failed to save file record to database" });
      }

      // If PDF, trigger async text extraction and chunking
      if (fileType === "pdf") {
        extractAndChunkPDF(knowledgeFile.id, file.buffer, tenantId).catch((err) => {
          console.error(`[KnowledgeFiles] Failed to extract PDF ${knowledgeFile.id}:`, err);
        });
      }

      res.status(201).json(knowledgeFile);
    } catch (error: any) {
      console.error(`[KnowledgeFiles] Unexpected error:`, error.message || error);
      next(error);
    }
  });

  // Helper function to extract text from PDF and create chunks
  async function extractAndChunkPDF(fileId: string, pdfBuffer: Buffer, tenantId: string) {
    try {
      await storage.updateKnowledgeFile(fileId, { indexStatus: "processing" });
      
      const { PDFParse } = await import("pdf-parse");
      const parser = new PDFParse({ data: pdfBuffer });
      const textResult = await parser.getText();
      const infoResult = await parser.getInfo();
      await parser.destroy();
      
      // Update page count
      await storage.updateKnowledgeFile(fileId, { pageCount: infoResult.total || 0 });
      
      // Split text into chunks (approximately 1000 characters each with overlap)
      const text = textResult.text;
      const chunkSize = 1000;
      const overlap = 100;
      const chunks: string[] = [];
      
      for (let i = 0; i < text.length; i += chunkSize - overlap) {
        const chunk = text.slice(i, i + chunkSize).trim();
        if (chunk.length > 50) { // Only keep meaningful chunks
          chunks.push(chunk);
        }
      }
      
      // Delete existing chunks for this file
      await storage.deleteKnowledgeChunksForFile(fileId);
      
      // Create new chunks
      for (let i = 0; i < chunks.length; i++) {
        await storage.createKnowledgeChunk({
          tenantId,
          fileId,
          chunkIndex: i,
          text: chunks[i],
          pageStart: null,
          pageEnd: null,
          embedding: null, // Embeddings will be added in a future phase
        });
      }
      
      await storage.updateKnowledgeFile(fileId, { indexStatus: "indexed" });
      console.log(`[KnowledgeFiles] Successfully indexed ${chunks.length} chunks from PDF ${fileId}`);
    } catch (error) {
      console.error(`[KnowledgeFiles] Error extracting PDF:`, error);
      await storage.updateKnowledgeFile(fileId, { 
        indexStatus: "failed",
        indexError: error instanceof Error ? error.message : "Unknown error",
      });
    }
  }

  // Generate SOP from knowledge file using AI
  app.post("/api/knowledge-files/:id/generate-sop", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const { id } = req.params;
      const tenantId = await resolveTenantId(req.user?.tenantId);
      const user = req.user!;
      
      const knowledgeFile = await storage.getKnowledgeFile(id);
      if (!knowledgeFile || knowledgeFile.tenantId !== tenantId) {
        return res.status(404).json({ message: "File not found" });
      }
      
      // Get the text chunks from this file
      const chunks = await storage.getKnowledgeChunks(id);
      if (chunks.length === 0) {
        return res.status(400).json({ message: "No text content found. Please wait for indexing to complete." });
      }
      
      // Combine all chunks into full text
      const fullText = chunks.map(c => c.text).join("\n\n");
      
      // Check for OpenAI API key
      if (!process.env.OPENAI_API_KEY) {
        return res.status(500).json({ message: "AI service not configured" });
      }
      
      // Use OpenAI to extract structured steps
      const completion = await getAskOtoOpenAI().chat.completions.create({
        model: "gpt-4o",
        messages: [
          {
            role: "system",
            content: `You are an expert at analyzing documents and extracting step-by-step procedures.
Your task is to analyze the provided document text and extract structured SOP (Standard Operating Procedure) steps.

Return a JSON object with:
- title: A clear, concise title for this SOP
- steps: An array of step objects, each with:
  - stepNumber: The step number (1, 2, 3, etc.)
  - title: A brief title for the step (max 50 characters)
  - description: A detailed description of what to do (max 200 characters)

Focus on actionable steps that staff can follow. If the document contains multiple procedures, focus on the main one.
Return ONLY valid JSON, no markdown or explanation.`
          },
          {
            role: "user",
            content: `Please extract structured steps from this document:\n\n${fullText.substring(0, 8000)}`
          }
        ],
        temperature: 0.3,
        max_tokens: 2000,
      });
      
      const aiResponse = completion.choices[0]?.message?.content || "";
      
      // Parse the JSON response
      let parsedSteps;
      try {
        // Remove markdown code blocks if present
        const cleanJson = aiResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
        parsedSteps = JSON.parse(cleanJson);
      } catch (parseError) {
        console.error("[GenerateSOP] Failed to parse AI response:", aiResponse);
        return res.status(500).json({ message: "Failed to parse AI response" });
      }
      
      // Create the SOP
      const structuredSteps = (parsedSteps.steps || []).map((s: any, i: number) => ({
        stepNumber: s.stepNumber || i + 1,
        title: s.title || `Step ${i + 1}`,
        description: s.description || "",
      }));
      
      // Validate we have at least one step
      if (structuredSteps.length === 0) {
        return res.status(400).json({ message: "Could not extract any steps from the document. Please try a different file." });
      }
      
      const sopData = {
        tenantId,
        title: parsedSteps.title || knowledgeFile.title || "Generated SOP",
        body: `Generated from: ${knowledgeFile.filename}`,
        departments: ["general"],
        structuredSteps,
        steps: structuredSteps.map((s: any) => s.title),
      };
      
      const newSop = await storage.createSopArticle(sopData);
      
      res.status(201).json({
        message: "SOP created successfully",
        sop: newSop,
        stepsCount: structuredSteps.length,
      });
    } catch (error) {
      console.error("[GenerateSOP] Error:", error);
      next(error);
    }
  });

