  // ============================================
  // OBJECT STORAGE DIAGNOSTIC TEST ENDPOINT
  // ============================================
  app.get("/api/test-object-storage", requireAuth, async (req, res) => {
    const diagnostics: any = {
      envCheck: {
        objectStorage: process.env.OBJECT_STORAGE || null,
        s3Bucket: process.env.S3_BUCKET || null,
        awsRegion: process.env.AWS_REGION || null,
        hasExplicitCredentials: !!(process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY),
      },
      storageMode: process.env.OBJECT_STORAGE || "not configured",
    };

    try {
      
      const testContent = Buffer.from(`Test file content - ${new Date().toISOString()}`);
      const testFilename = `test-${Date.now()}.txt`;
      
      // Test upload
      const url = await uploadToObjectStorage(testContent, "test-uploads", testFilename, "text/plain");
      diagnostics.uploadSuccess = true;
      diagnostics.uploadUrl = url;
      
      // Test retrieval
      const file = await getFileFromObjectStorage("test-uploads", testFilename);
      let retrieveSuccess = false;
      let contentMatches = false;
      
      if (file) {
        const chunks: Buffer[] = [];
        for await (const chunk of file.stream) {
          chunks.push(chunk as Buffer);
        }
        const retrievedContent = Buffer.concat(chunks).toString();
        retrieveSuccess = true;
        contentMatches = retrievedContent === testContent.toString();
      }
      diagnostics.retrieveSuccess = retrieveSuccess;
      diagnostics.contentMatches = contentMatches;
      
      // Cleanup
      await deleteFromObjectStorage("test-uploads", testFilename);
      
      res.json({
        success: true,
        diagnostics,
        message: "Object storage is working correctly! Files will persist across deployments."
      });
    } catch (error: any) {
      console.error("[Object Storage Test] Error:", error);
      res.status(500).json({
        success: false,
        diagnostics,
        error: error.message || 'Unknown error',
        errorCode: error.code || 'unknown',
        message: "Object storage test failed. Check diagnostics for configuration status."
      });
    }
  });

  // ============================================
  // GENERAL FILE SERVING FROM OBJECT STORAGE
  // ============================================
  // Public folders that don't require authentication
  const publicFileFolders = ["branch-logos", "dropoff-photos", "dropoff-signatures", "profile-photos", "invitations"];
  
  // Serve any file type from object storage with legacy fallback
  // Some folders are public, others require authentication
  app.get("/api/files/:folder/:filename", async (req, res, next) => {
    try {
      const { folder, filename } = req.params;
      const sanitizedFilename = path.basename(filename);
      // Private documents have their own record-scoped routes; this generic
      // file route cannot decide who may read a contract or employee record.
      if (["contracts", "letters", "beo-pdfs", "employee-documents", "payroll-exports", "payroll-payslips"].includes(folder)) {
        return res.status(404).json({ message: "File not found" });
      }
      
      // Check if folder requires authentication
      if (!publicFileFolders.includes(folder)) {
        // Require authentication for non-public folders
        if (!req.isAuthenticated || !req.isAuthenticated()) {
          return res.status(401).json({ message: "Authentication required" });
        }
      }
      
      // Try object storage first
      const file = await getFileFromObjectStorage(folder, sanitizedFilename);
      if (file) {
        res.setHeader("Content-Type", file.contentType);
        res.setHeader("Cache-Control", "public, max-age=86400, stale-while-revalidate=604800");
        file.stream.pipe(res);
        return;
      }
      
      // Fallback to local storage for legacy files
      const possiblePaths = [
        path.join(process.cwd(), folder, sanitizedFilename),
        path.join(process.cwd(), "uploads", folder, sanitizedFilename),
      ];
      
      for (const localPath of possiblePaths) {
        if (fs.existsSync(localPath)) {
          res.sendFile(localPath);
          return;
        }
      }
      
      res.status(404).json({ message: "File not found" });
    } catch (error) {
      next(error);
    }
  });

  // ============================================
  // FIX BOARD ENHANCED ENDPOINTS
  // ============================================

  // Get fix report with full details (location, comments, department members)
  app.get("/api/fix-reports/:id/details", requireAuth, async (req, res, next) => {
    try {
      const result = await storage.getFixReportWithDetails(req.params.id);
      if (!result) {
        return res.status(404).json({ message: "Fix report not found" });
      }

      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      if (result.report.tenantId !== tenantId) {
        return res.status(404).json({ message: "Fix report not found" });
      }
      if (!canUserAccessBranch(user, result.report.branchId)) {
        return res.status(403).json({ message: "Access denied to this Fix report branch" });
      }
      const isReporter = result.report.reportedBy === user.id;
      const isManagerOrAdmin = user.hasAllBranchesAccess || ['manager', 'admin', 'operator_admin', 'global_admin'].includes(user.role || '');

      // Allow access if: user is reporter OR manager/admin OR Fix Dept member
      if (!isReporter && !isManagerOrAdmin) {
        const deptMember = await isUserFixDeptMember(user.id);
        if (!deptMember) {
          return res.status(403).json({ message: "Access denied: reporter, manager/admin, or Fix Department membership required" });
        }
      }

      // Enrich comments with author names
      const enrichedComments = await Promise.all(
        result.comments.map(async (comment) => {
          let author: { id: string; fullName?: string | null; email: string } | null = null;
          if (comment.authorUserId) {
            const [u] = await db.select({ id: users.id, fullName: users.fullName, email: users.email })
              .from(users).where(eq(users.id, comment.authorUserId)).limit(1);
            if (u) author = u;
          }
          return { ...comment, author };
        })
      );

      // Attach department info + members if assigned
      let assignedDepartment: { id: string; name: string } | null = null;
      let departmentMembers: { id: string; name: string; initials: string }[] = [];
      const reportRow = result.report as any;
      if (reportRow.assignedDepartmentId) {
        const [dept] = await db.select({ id: departments.id, name: departments.name })
          .from(departments).where(eq(departments.id, reportRow.assignedDepartmentId)).limit(1);
        if (dept) assignedDepartment = dept;

        // Get members via employees
        const empMembers = await db
          .select({ id: users.id, fullName: users.fullName, email: users.email })
          .from(employees)
          .innerJoin(users, eq(users.id, employees.userId))
          .where(eq(employees.primaryDepartmentId as any, reportRow.assignedDepartmentId));

        // Get members via advisors (people with departmentId)
        const advisorMembers = await db
          .select({ id: users.id, fullName: users.fullName, email: users.email })
          .from(people)
          .innerJoin(accessPolicies, eq(accessPolicies.personId, people.id))
          .innerJoin(users, eq(users.id, accessPolicies.coreUserId as any))
          .where(eq(people.departmentId as any, reportRow.assignedDepartmentId));

        const allMembers = [...empMembers, ...advisorMembers];
        const seen = new Set<string>();
        departmentMembers = allMembers
          .filter(m => { if (seen.has(m.id)) return false; seen.add(m.id); return true; })
          .map(m => ({
            id: m.id,
            name: m.fullName || m.email,
            initials: (m.fullName || m.email).slice(0, 2).toUpperCase(),
          }));
      }

      res.json({
        ...result,
        comments: enrichedComments,
        assignedDepartment,
        departmentMembers,
      });
    } catch (error) {
      next(error);
    }
  });

  // Get comments for a fix report
  app.get("/api/fix-reports/:id/comments", requireAuth, async (req, res, next) => {
    try {
      const report = await storage.getFixReport(req.params.id);
      if (!report) {
        return res.status(404).json({ message: "Fix report not found" });
      }

      const comments = await storage.getFixComments(req.params.id);
      res.json(comments);
    } catch (error) {
      next(error);
    }
  });

  // Add a comment to a fix report (open to original reporter + branch members)
  app.post("/api/fix-reports/:id/comments", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const report = await storage.getFixReport(req.params.id);
      if (!report) {
        return res.status(404).json({ message: "Fix report not found" });
      }

      // Allow access if: user is reporter OR manager/admin OR Fix Dept member
      const isReporter = report.reportedBy === user.id;
      const isManagerOrAdmin = user.hasAllBranchesAccess || ['manager', 'admin', 'operator_admin', 'global_admin'].includes(user.role || '');
      if (!isReporter && !isManagerOrAdmin) {
        const deptMember = await isUserFixDeptMember(user.id);
        if (!deptMember) {
          return res.status(403).json({ message: "Access denied: reporter, manager/admin, or Fix Department membership required" });
        }
      }

      const { message } = req.body;
      if (!message || typeof message !== 'string' || message.trim().length === 0) {
        return res.status(400).json({ message: "Comment message is required" });
      }

      const comment = await storage.createFixComment({
        fixId: req.params.id,
        authorType: 'staff_user',
        authorUserId: user.id,
        message: message.trim(),
      } as any);

      res.status(201).json(comment);
    } catch (error) {
      next(error);
    }
  });

  // Close a fix report (manager/admin only)
  app.patch("/api/fix-reports/:id/close", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const report = await storage.getFixReport(req.params.id);
      if (!report) {
        return res.status(404).json({ message: "Fix report not found" });
      }

      // Check if user has manager/admin access
      if (!user.hasAllBranchesAccess && user.role !== 'manager' && user.role !== 'admin') {
        return res.status(403).json({ message: "Only managers and admins can close fix reports" });
      }

      // Check branch access for managers
      if (!user.hasAllBranchesAccess) {
        const hasAccess = user.branchAccess?.some(ba => ba.branchId === report.branchId);
        if (!hasAccess) {
          return res.status(403).json({ message: "Access denied to this branch" });
        }
      }

      const { doneNote } = req.body;
      const closedReport = await storage.closeFixReport(
        req.params.id,
        user.id,
        null, // No supplier token
        doneNote || undefined
      );

      res.json(closedReport);
    } catch (error) {
      next(error);
    }
  });

  // Update fix report (manager/admin - for scheduling, priority, etc.)
  app.patch("/api/fix-reports/:id/update", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const report = await storage.getFixReport(req.params.id);
      if (!report) {
        return res.status(404).json({ message: "Fix report not found" });
      }

      const isManagerOrAdmin = user.hasAllBranchesAccess || ['manager', 'admin', 'operator_admin', 'global_admin'].includes(user.role || '');

      // Status/priority updates allowed for: manager/admin OR Fix Dept member
      // (dept members are the responders — they need to move reports through the workflow)
      const { status, priority, scheduledAt, note, appendMedia } = req.body;
      if (!isManagerOrAdmin) {
        const deptMember = await isUserFixDeptMember(user.id);
        if (!deptMember) {
          return res.status(403).json({ message: "Access denied: manager/admin or Fix Department membership required" });
        }
      }
      
      const updates: Partial<FixReport> = {};
      
      if (status) updates.status = status;
      if (priority) updates.priority = priority;
      if (scheduledAt !== undefined) updates.scheduledAt = scheduledAt ? new Date(scheduledAt) : null;
      if (note !== undefined) updates.note = note;

      // Append completion photos to existing media array (capped at 10 total)
      if (Array.isArray(appendMedia) && appendMedia.length > 0) {
        const existingMedia: string[] = Array.isArray(report.media) ? (report.media as string[]) : [];
        const combined = [...existingMedia, ...appendMedia];
        updates.media = combined.slice(0, 10) as any;
      }

      const oldStatus = report.status;
      const updatedReport = await storage.updateFixReport(req.params.id, updates);

      // Log status change as an activity comment so it appears in the activity feed
      if (status && status !== oldStatus) {
        await db.insert(fixComments).values({
          fixId: req.params.id as any,
          authorType: 'staff_user',
          authorUserId: user.id,
          message: `[status_change]from:${oldStatus}|to:${status}`,
        } as any);
      }

      res.json(updatedReport);
    } catch (error) {
      next(error);
    }
  });

  // ============================================
  // FIX DEPARTMENT SETTING (Admin only)
  // ============================================

  // Get the current fix department setting
  app.get("/api/settings/fix-department", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      if (!user.hasAllBranchesAccess && user.role !== 'admin') {
        return res.status(403).json({ message: "Admin access required" });
      }
      const setting = await storage.getSetting("fix_department_id");
      let department: { id: string; name: string } | null = null;
      if (setting?.value) {
        const [dept] = await db.select({ id: departments.id, name: departments.name })
          .from(departments).where(eq(departments.id, setting.value)).limit(1);
        if (dept) department = dept;
      }
      res.json({ departmentId: setting?.value || null, department });
    } catch (error) {
      next(error);
    }
  });

  // Set the fix department
  app.post("/api/settings/fix-department", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      if (!user.hasAllBranchesAccess && user.role !== 'admin') {
        return res.status(403).json({ message: "Admin access required" });
      }
      const { departmentId } = req.body;
      if (departmentId === null || departmentId === undefined || departmentId === '') {
        await storage.upsertSetting({ key: "fix_department_id", value: "" });
        return res.json({ departmentId: null, department: null });
      }
      // Verify department exists
      const [dept] = await db.select({ id: departments.id, name: departments.name })
        .from(departments).where(eq(departments.id, departmentId)).limit(1);
      if (!dept) {
        return res.status(404).json({ message: "Department not found" });
      }
      await storage.upsertSetting({ key: "fix_department_id", value: departmentId });
      res.json({ departmentId, department: dept });
    } catch (error) {
      next(error);
    }
  });

  // ============================================
  // SUPPLIER TOKEN MANAGEMENT (Admin only)
  // ============================================

  // List all supplier tokens
  app.get("/api/settings/supplier-tokens", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const tokens = await storage.getFixSupplierTokens(tenantId);
      
      // Don't expose token hashes
      const safeTokens = tokens.map(t => ({
        id: t.id,
        tenantId: t.tenantId,
        name: t.name,
        allowedBranchIds: t.allowedBranchIds,
        expiresAt: t.expiresAt,
        createdAt: t.createdAt,
        lastAccessedAt: t.lastUsedAt,
        createdByUserId: t.createdByUserId,
        isActive: t.isEnabled && (!t.expiresAt || new Date(t.expiresAt) > new Date()),
      }));
      
      res.json(safeTokens);
    } catch (error) {
      next(error);
    }
  });

  // Create a new supplier token
  app.post("/api/settings/supplier-tokens", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const { name, allowedBranchIds, expiresAt } = req.body;
      if (typeof name !== 'string' || !name.trim()) {
        return res.status(400).json({ message: "Supplier name is required" });
      }
      if (!Array.isArray(allowedBranchIds) || allowedBranchIds.length === 0 || !allowedBranchIds.every(id => typeof id === 'string')) {
        return res.status(400).json({ message: "At least one branch must be selected" });
      }

      const tenantId = await resolveTenantId(user.tenantId);
      const branchesInTenant = (await storage.getBranches()).filter(branch => branch.tenantId === tenantId);
      const validBranchIds = new Set(branchesInTenant.map(branch => branch.id));
      if (allowedBranchIds.some(id => !validBranchIds.has(id))) {
        return res.status(400).json({ message: "Selected branch is not available" });
      }
      const expiry = expiresAt == null ? null : new Date(expiresAt);
      if (expiry && (!Number.isFinite(expiry.getTime()) || expiry <= new Date())) {
        return res.status(400).json({ message: "Expiry must be a future date" });
      }
      
      // Generate a secure random token
      const rawToken = crypto.randomBytes(32).toString('hex');
      const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');

      const supplierToken = await storage.createFixSupplierToken({
        tenantId,
        name: name.trim(),
        tokenHash,
        allowedBranchIds: [...new Set(allowedBranchIds)],
        expiresAt: expiry,
        createdByUserId: user.id,
      });

      // Return the raw token ONCE (it cannot be retrieved again)
      res.status(201).json({
        id: supplierToken.id,
        name: supplierToken.name,
        token: rawToken, // Only returned once!
        allowedBranchIds: supplierToken.allowedBranchIds,
        expiresAt: supplierToken.expiresAt,
        createdAt: supplierToken.createdAt,
        magicLink: `${req.protocol}://${req.get('host')}/supplier/${rawToken}`,
      });
    } catch (error) {
      next(error);
    }
  });

  // Revoke (delete) a supplier token
  app.delete("/api/settings/supplier-tokens/:id", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const user = req.user as UserWithBranchAccess;
      const tenantId = await resolveTenantId(user.tenantId);
      const token = await storage.getFixSupplierToken(req.params.id);
      if (!token || token.tenantId !== tenantId) {
        return res.status(404).json({ message: "Supplier token not found" });
      }
      await storage.updateFixSupplierToken(token.id, { isEnabled: false });
      res.status(204).send();
    } catch (error) {
      next(error);
    }
  });

  // ============================================
  // SUPPLIER PORTAL (Public with token auth)
  // ============================================

  const resolveSupplierPortalToken = async (rawToken: unknown) => {
    if (typeof rawToken !== 'string' || !/^[a-f0-9]{64}$/.test(rawToken)) return null;
    const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');
    const token = await storage.getFixSupplierTokenByHash(tokenHash);
    if (!token?.isEnabled || (token.expiresAt && new Date(token.expiresAt) <= new Date())) return null;
    return token;
  };

  const supplierCanAccessReport = (token: { tenantId: string; allowedBranchIds: string[] }, report: FixReport) =>
    report.tenantId === token.tenantId && token.allowedBranchIds.includes(report.branchId);

  const supplierMediaUrls = (report: FixReport, rawToken: string) =>
    report.media.flatMap(url => {
      const filename = /^\/api\/files\/fix-media\/([a-zA-Z0-9._-]+)$/.exec(url)?.[1];
      return filename
        ? [`/api/supplier-portal/fix-reports/${report.id}/media/${filename}?token=${rawToken}`]
        : [];
    });

  // Validate supplier token and get supplier info
  app.get("/api/supplier-portal/validate", async (req, res, next) => {
    try {
      const supplierToken = await resolveSupplierPortalToken(req.query.token);
      if (!supplierToken) {
        return res.status(401).json({ message: "Invalid or expired token" });
      }

      // Update last used time
      await storage.updateFixSupplierTokenLastUsed(supplierToken.id);

      // Get branches for display
      const branches = await storage.getBranches();
      const allowedBranches = branches.filter(b =>
        b.tenantId === supplierToken.tenantId && supplierToken.allowedBranchIds.includes(b.id)
      );

      res.json({
        id: supplierToken.id,
        name: supplierToken.name,
        allowedBranches: allowedBranches.map(b => ({ id: b.id, name: b.name })),
      });
    } catch (error) {
      next(error);
    }
  });

  // Get fix reports for supplier
  app.get("/api/supplier-portal/fix-reports", async (req, res, next) => {
    try {
      const supplierToken = await resolveSupplierPortalToken(req.query.token);
      if (!supplierToken) {
        return res.status(401).json({ message: "Invalid or expired token" });
      }

      // Get fix reports for allowed branches only
      const reports = await storage.getFixReportsForBranches(
        supplierToken.tenantId,
        supplierToken.allowedBranchIds
      );

      res.json(reports.map(report => ({
        ...report,
        mediaUrls: supplierMediaUrls(report, req.query.token as string),
      })));
    } catch (error) {
      next(error);
    }
  });

  // Get fix report details for supplier
  app.get("/api/supplier-portal/fix-reports/:id", async (req, res, next) => {
    try {
      const supplierToken = await resolveSupplierPortalToken(req.query.token);
      if (!supplierToken) {
        return res.status(401).json({ message: "Invalid or expired token" });
      }

      const details = await storage.getFixReportWithDetails(req.params.id);
      if (!details) {
        return res.status(404).json({ message: "Fix report not found" });
      }

      if (!supplierCanAccessReport(supplierToken, details.report)) {
        return res.status(403).json({ message: "Access denied to this report" });
      }

      res.json({
        ...details.report,
        mediaUrls: supplierMediaUrls(details.report, req.query.token as string),
        locationDetails: details.location ?? null,
        comments: details.comments.map(comment => ({
          ...comment,
          supplierToken: comment.supplierTokenId === supplierToken.id
            ? { id: supplierToken.id, name: supplierToken.name }
            : null,
        })),
      });
    } catch (error) {
      next(error);
    }
  });

  // Supplier media stays private to the report and token's tenant and branches.
  app.get("/api/supplier-portal/fix-reports/:id/media/:filename", async (req, res, next) => {
    try {
      const supplierToken = await resolveSupplierPortalToken(req.query.token);
      if (!supplierToken) return res.status(401).json({ message: "Invalid or expired token" });
      const report = await storage.getFixReport(req.params.id);
      if (!report) return res.status(404).json({ message: "Fix report not found" });
      if (!supplierCanAccessReport(supplierToken, report)) {
        return res.status(403).json({ message: "Access denied to this report" });
      }
      const filename = req.params.filename;
      if (!/^[a-zA-Z0-9._-]+$/.test(filename) || !report.media.includes(`/api/files/fix-media/${filename}`)) {
        return res.status(404).json({ message: "Media not found" });
      }
      const file = await getFileRangeFromObjectStorage("fix-media", filename, req.headers.range);
      if (!file) return res.status(404).json({ message: "Media not found" });
      res.setHeader("Content-Type", file.contentType);
      res.setHeader("Accept-Ranges", "bytes");
      res.setHeader("Cache-Control", "private, no-store");
      res.setHeader("X-Content-Type-Options", "nosniff");
      if (file.isPartial) {
        res.status(206);
        res.setHeader("Content-Range", `bytes ${file.start}-${file.end}/${file.totalSize}`);
        res.setHeader("Content-Length", String(file.end - file.start + 1));
      } else {
        res.setHeader("Content-Length", String(file.totalSize));
      }
      file.stream.pipe(res);
    } catch (error) {
      next(error);
    }
  });

  // Add comment as supplier
  app.post("/api/supplier-portal/fix-reports/:id/comments", async (req, res, next) => {
    try {
      const supplierToken = await resolveSupplierPortalToken(req.query.token);
      if (!supplierToken) {
        return res.status(401).json({ message: "Invalid or expired token" });
      }

      const report = await storage.getFixReport(req.params.id);
      if (!report) {
        return res.status(404).json({ message: "Fix report not found" });
      }

      if (!supplierCanAccessReport(supplierToken, report)) {
        return res.status(403).json({ message: "Access denied to this report" });
      }

      const { message } = req.body;
      if (typeof message !== 'string' || !message.trim() || message.length > 5000) {
        return res.status(400).json({ message: "Comment must be 1 to 5000 characters" });
      }

      const comment = await storage.createFixComment({
        fixId: req.params.id,
        authorType: 'supplier_token',
        supplierTokenId: supplierToken.id,
        message: message.trim(),
      });

      res.status(201).json(comment);
    } catch (error) {
      next(error);
    }
  });

  // Close fix report as supplier
  app.patch("/api/supplier-portal/fix-reports/:id/close", async (req, res, next) => {
    try {
      const supplierToken = await resolveSupplierPortalToken(req.query.token);
      if (!supplierToken) {
        return res.status(401).json({ message: "Invalid or expired token" });
      }

      const report = await storage.getFixReport(req.params.id);
      if (!report) {
        return res.status(404).json({ message: "Fix report not found" });
      }

      if (!supplierCanAccessReport(supplierToken, report)) {
        return res.status(403).json({ message: "Access denied to this report" });
      }

      if (report.status === 'done') {
        return res.status(409).json({ message: "Fix report is already done" });
      }

      const { doneNote } = req.body;
      if (doneNote != null && (typeof doneNote !== 'string' || doneNote.length > 5000)) {
        return res.status(400).json({ message: "Resolution note is too long" });
      }
      const closedReport = await storage.closeFixReport(
        req.params.id,
        null, // No user ID
        supplierToken.id,
        doneNote?.trim() || undefined
      );

      res.json(closedReport);
    } catch (error) {
      next(error);
    }
  });

  // ============================================
  // TRAINING MODULES (franchise-ready scoping)
  // ============================================

  // List training modules with branch filtering
  app.get("/api/training/modules", requireAuth, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const user = req.user as UserWithBranchAccess;
      const requestedBranchId = req.query.branchId as string | undefined;
      
      // Determine effective branch filter:
      // - 'all' is only allowed for users with all_branches access (admins)
      // - Non-admins MUST have a valid branch ID to view content
      let effectiveBranchId: string | null = null;
      
      if (user.hasAllBranchesAccess) {
        // Admin can view all branches or specific branch
        if (requestedBranchId === 'all' || !requestedBranchId) {
          effectiveBranchId = null; // Admin viewing all
        } else {
          effectiveBranchId = requestedBranchId;
        }
      } else {
        // Non-admin: Must have branch access and use a valid branch
        if (!user.branchAccess || user.branchAccess.length === 0) {
          return res.status(403).json({ message: "No branch access configured" });
        }
        
        if (requestedBranchId && requestedBranchId !== 'all') {
          // Validate user has access to requested branch
          const hasAccess = user.branchAccess.some(ba => ba.branchId === requestedBranchId);
          if (!hasAccess) {
            return res.status(403).json({ message: "Access denied to this branch" });
          }
          effectiveBranchId = requestedBranchId;
        } else {
          // Default to first accessible branch for non-admins
          effectiveBranchId = user.branchAccess[0].branchId;
        }
      }
      
      const modules = await storage.getTrainingModules(tenantId, effectiveBranchId);
      
      // Attach completion status and question count for current user
      const modulesWithProgress = await Promise.all(modules.map(async (module) => {
        // Get question count
        const questions = await db.select().from(quizQuestions)
          .where(eq(quizQuestions.moduleId, module.id));
        
        // Get user's completion
        const [completion] = await db.select().from(moduleCompletions)
          .where(and(
            eq(moduleCompletions.moduleId, module.id),
            eq(moduleCompletions.userId, user.id)
          ));
        
        // Get user's best quiz attempt
        const [bestAttempt] = await db.select().from(quizAttempts)
          .where(and(
            eq(quizAttempts.moduleId, module.id),
            eq(quizAttempts.userId, user.id),
            eq(quizAttempts.passed, true)
          ))
          .orderBy(desc(quizAttempts.score))
          .limit(1);
        
        return {
          ...module,
          questionCount: questions.length,
          completion: completion || null,
          bestAttempt: bestAttempt || null,
        };
      }));
      
      res.json(modulesWithProgress);
    } catch (error) {
      next(error);
    }
  });

  // Get single training module
  app.get("/api/training/modules/:id", requireAuth, async (req, res, next) => {
    try {
      const { id } = req.params;
      const module = await storage.getTrainingModule(id);
      if (!module) {
        return res.status(404).json({ message: "Training module not found" });
      }
      res.json(module);
    } catch (error) {
      next(error);
    }
  });

  // Create training module (admin only)
  app.post("/api/training/modules", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const user = req.user as UserWithBranchAccess;
      const moduleData = {
        ...req.body,
        tenantId,
        createdBy: user.id,
        scope: req.body.scope || 'GLOBAL',
        branchIds: req.body.branchIds || [],
      };
      const module = await storage.createTrainingModule(moduleData);
      res.status(201).json(module);
    } catch (error) {
      next(error);
    }
  });

  // Update training module (admin only)
  app.patch("/api/training/modules/:id", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const { id } = req.params;
      const existing = await storage.getTrainingModule(id);
      if (!existing) {
        return res.status(404).json({ message: "Training module not found" });
      }
      const module = await storage.updateTrainingModule(id, req.body);
      res.json(module);
    } catch (error) {
      next(error);
    }
  });

  // Delete training module (admin only)
  app.delete("/api/training/modules/:id", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const { id } = req.params;
      const existing = await storage.getTrainingModule(id);
      if (!existing) {
        return res.status(404).json({ message: "Training module not found" });
      }
      await storage.deleteTrainingModule(id);
      res.status(204).send();
    } catch (error) {
      next(error);
    }
  });

  // ============================================
  // PAYROLL MODULE API ENDPOINTS
  // ============================================

  // Helper: Check if user has payroll admin access (global_admin or operator_admin)
  const isPayrollAdmin = (user: any) =>
    user?.role === 'global_admin' || user?.role === 'admin' || user?.role === 'operator_admin';
  const payrollUuidPattern = "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}";

  // Helper: Verify payroll period belongs to user's operator
  const verifyPeriodAccess = async (periodId: string, user: any): Promise<boolean> => {
    const period = await storage.getPayrollPeriod(periodId);
    if (!period) return false;
    if (user.role === 'global_admin' || user.role === 'admin') return true;
    return period.operatorId === user.operatorId;
  };

  // Helper: Verify payroll run belongs to user's operator
  const verifyRunAccess = async (runId: string, user: any): Promise<boolean> => {
    const run = await storage.getPayrollRun(runId);
    if (!run) return false;
    return verifyPeriodAccess(run.payrollPeriodId, user);
  };

  // GET /api/payroll/periods - List payroll periods for user's operator
  app.get("/api/payroll/periods", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as any;
      if (!isPayrollAdmin(user)) {
        return res.status(403).json({ message: "Payroll admin access required" });
      }
      if (!user.operatorId && user.role !== 'global_admin' && user.role !== 'admin') {
        return res.status(400).json({ message: "No operator context" });
      }
      const operatorId = user.operatorId || (req.query.operatorId as string);
      if (!operatorId) {
        return res.status(400).json({ message: "Operator ID required" });
      }
      const periods = await storage.getPayrollPeriods(operatorId);
      res.json(periods);
    } catch (error) {
      next(error);
    }
  });

  // GET /api/payroll/periods/:id - Get period with runs (admin only)
  app.get("/api/payroll/periods/:id", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as any;
      if (!isPayrollAdmin(user)) {
        return res.status(403).json({ message: "Payroll admin access required" });
      }
      const period = await storage.getPayrollPeriodWithRuns(req.params.id);
      if (!period) {
        return res.status(404).json({ message: "Period not found" });
      }
      if (!(await verifyPeriodAccess(req.params.id, user))) {
        return res.status(403).json({ message: "Access denied to this period" });
      }
      res.json(period);
    } catch (error) {
      next(error);
    }
  });

  // POST /api/payroll/periods - Create new period (admin only)
  app.post("/api/payroll/periods", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as any;
      if (!isPayrollAdmin(user)) {
        return res.status(403).json({ message: "Payroll admin access required" });
      }
      if (!user.operatorId && user.role !== 'global_admin' && user.role !== 'admin') {
        return res.status(400).json({ message: "No operator context" });
      }
      const { name, startDate, endDate, status } = req.body;
      if (!name || !startDate || !endDate) {
        return res.status(400).json({ message: "Name, startDate, and endDate are required" });
      }
      const operatorId = user.operatorId || req.body.operatorId;
      if (!operatorId) {
        return res.status(400).json({ message: "Operator ID required" });
      }
      const period = await storage.createPayrollPeriod({
        operatorId,
        name,
        startDate,
        endDate,
        status: status || 'OPEN',
      });
      res.status(201).json(period);
    } catch (error) {
      next(error);
    }
  });

  // PATCH /api/payroll/periods/:id - Update period (admin only)
  app.patch("/api/payroll/periods/:id", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as any;
      if (!isPayrollAdmin(user)) {
        return res.status(403).json({ message: "Payroll admin access required" });
      }
      const existing = await storage.getPayrollPeriod(req.params.id);
      if (!existing) {
        return res.status(404).json({ message: "Period not found" });
      }
      if (!(await verifyPeriodAccess(req.params.id, user))) {
        return res.status(403).json({ message: "Access denied to this period" });
      }
      if (existing.status === 'CLOSED') {
        return res.status(400).json({ message: "Cannot modify closed period" });
      }
      const { name, startDate, endDate, status } = req.body;
      const period = await storage.updatePayrollPeriod(req.params.id, { name, startDate, endDate, status });
      res.json(period);
    } catch (error) {
      next(error);
    }
  });

