  // POST /api/payroll/runs - Create new payroll run (admin only)
  app.post("/api/payroll/runs", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as any;
      if (!isPayrollAdmin(user)) {
        return res.status(403).json({ message: "Payroll admin access required" });
      }
      const { payrollPeriodId, branchIds } = req.body;
      if (!payrollPeriodId) {
        return res.status(400).json({ message: "payrollPeriodId is required" });
      }
      if (!(await verifyPeriodAccess(payrollPeriodId, user))) {
        return res.status(403).json({ message: "Access denied to this period" });
      }
      const existingRuns = await storage.getPayrollRuns(payrollPeriodId);
      const nextRunNumber = existingRuns.length + 1;
      const run = await storage.createPayrollRun({
        payrollPeriodId,
        branchIds: branchIds || [],
        runNumber: nextRunNumber,
        status: 'DRAFT',
        createdBy: user.id,
      });
      res.status(201).json(run);
    } catch (error) {
      next(error);
    }
  });

  // PATCH /api/payroll/runs/:id - Update run status (admin only)
  app.patch("/api/payroll/runs/:id", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as any;
      if (!isPayrollAdmin(user)) {
        return res.status(403).json({ message: "Payroll admin access required" });
      }
      const existing = await storage.getPayrollRun(req.params.id);
      if (!existing) {
        return res.status(404).json({ message: "Run not found" });
      }
      if (!(await verifyRunAccess(req.params.id, user))) {
        return res.status(403).json({ message: "Access denied to this run" });
      }
      if (existing.status === 'FINALIZED') {
        return res.status(400).json({ message: "Cannot modify finalized run" });
      }
      const updates: any = {};
      if (req.body.status) updates.status = req.body.status;
      if (req.body.status === 'FINALIZED') {
        updates.finalizedAt = new Date();
        updates.finalizedBy = user.id;
      }
      const run = await storage.updatePayrollRun(req.params.id, updates);
      res.json(run);
    } catch (error) {
      next(error);
    }
  });

