  // GET /api/payroll/payslips/:id - Get single payslip (self or admin)
  app.get("/api/payroll/payslips/:id", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as any;
      if (!new RegExp(`^${payrollUuidPattern}$`).test(req.params.id)) {
        return res.status(400).json({ message: "Invalid payslip ID" });
      }
      const payslip = await storage.getPayslip(req.params.id);
      if (!payslip) {
        return res.status(404).json({ message: "Payslip not found" });
      }
      if (!isPayrollAdmin(user)) {
        const employee = await db.select()
          .from(employees)
          .where(and(
            eq(employees.userId, user.id),
            eq(employees.tenantId, user.tenantId)
          ))
          .limit(1);
        if (!employee.length || employee[0].id !== payslip.employeeId) {
          return res.status(403).json({ message: "Access denied" });
        }
      }
      res.json(payslip);
    } catch (error) {
      next(error);
    }
  });

