  // ============================================
  // DEV-ONLY LEGACY IMPORT ENDPOINTS
  // ============================================

  // Import legacy core uploads to object storage (DEV ONLY)
  // Auth: admin session OR x-dev-import-key header matching DEV_IMPORT_KEY
  app.post("/api/dev/import-core-legacy-uploads", async (req, res) => {
    try {
      // 1. DEV-only enforcement
      const { APP_ENV } = await import("./config/env");
      if (APP_ENV !== "dev") {
        res.status(403).json({
          success: false,
          error: "This endpoint is only available in dev environment",
        });
        return;
      }

      // 2. Auth check: admin session OR x-dev-import-key header
      const devImportKey = process.env.DEV_IMPORT_KEY;
      const headerKey = req.headers["x-dev-import-key"];
      const isKeyAuth = devImportKey && headerKey === devImportKey;
      const isAdminAuth = req.isAuthenticated?.() && (req.user as any)?.role === "admin";

      if (!isKeyAuth && !isAdminAuth) {
        res.status(401).json({
          success: false,
          error: "Unauthorized. Provide admin session or valid x-dev-import-key header.",
        });
        return;
      }

      // 3. Run import
      const { importCoreLegacyUploads } = await import("./routes/legacyImport");
      const result = await importCoreLegacyUploads();
      res.json({
        success: result.failed.length === 0,
        ...result,
      });
    } catch (error: any) {
      console.error("Legacy import error:", error);
      res.status(500).json({
        success: false,
        error: error.message || "Internal server error",
      });
    }
  });

  // ============================================
  // LOCATIONS API (for tagging checklists/tasks)
  // ============================================

  // Get all locations with branch access info
  app.get("/api/locations", requireAuth, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const user = req.user as UserWithBranchAccess;
      const { branchId, tag } = req.query;

      // Get all locations for the tenant
      let allLocations = await db
        .select()
        .from(locations)
        .where(eq(locations.tenantId, tenantId))
        .orderBy(locations.sortOrder, locations.name);

      // Filter by tag if specified
      if (tag) {
        allLocations = allLocations.filter(loc => 
          loc.tags && loc.tags.includes(tag as string)
        );
      }

      // Get branch access for all locations
      const allBranchAccess = await db
        .select()
        .from(locationBranchAccess);

      // Filter locations based on user's branch access if not admin
      let filteredLocations = allLocations;
      if (!user.hasAllBranchesAccess && branchId) {
        // Filter to locations that are either global (no branch access) or have access to the specified branch
        const locationIdsWithBranchAccess = new Set(
          allBranchAccess
            .filter(ba => ba.branchId === branchId)
            .map(ba => ba.locationId)
        );
        
        // Get locations that have no branch restrictions OR have access to the current branch
        const locationIdsWithAnyAccess = new Set(allBranchAccess.map(ba => ba.locationId));
        
        filteredLocations = allLocations.filter(loc => 
          !locationIdsWithAnyAccess.has(loc.id) || // No branch restrictions
          locationIdsWithBranchAccess.has(loc.id)  // Has access to specified branch
        );
      }

      // Add branch access info to each location
      const locationsWithBranches = filteredLocations.map(loc => ({
        ...loc,
        branchAccess: allBranchAccess.filter(ba => ba.locationId === loc.id),
      }));

      res.json(locationsWithBranches);
    } catch (error) {
      next(error);
    }
  });

  // Create a new location
  app.post("/api/locations", requireAuth, requireRole("admin", "global_admin", "operator_admin", "manager"), async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const { name, description, parentId, branchIds, tags } = req.body;

      if (!name) {
        return res.status(400).json({ message: "Name is required" });
      }

      const id = crypto.randomUUID();
      const now = new Date();

      await db.insert(locations).values({
        id,
        tenantId,
        name,
        description: description || null,
        parentId: parentId || null,
        isActive: true,
        sortOrder: 0,
        tags: tags || [],
        createdAt: now,
        updatedAt: now,
      });

      // Add branch access if specified
      if (branchIds && branchIds.length > 0) {
        const branchAccessValues = branchIds.map((branchId: string) => ({
          id: crypto.randomUUID(),
          locationId: id,
          branchId,
          createdAt: now,
        }));
        await db.insert(locationBranchAccess).values(branchAccessValues);
      }

      res.json({ id, name, description });
    } catch (error) {
      next(error);
    }
  });

  // Update a location
  app.patch("/api/locations/:id", requireAuth, requireRole("admin", "global_admin", "operator_admin", "manager"), async (req, res, next) => {
    try {
      const { id } = req.params;
      const { name, description, parentId, isActive, sortOrder, branchIds, tags } = req.body;

      const updates: Record<string, any> = { updatedAt: new Date() };
      if (name !== undefined) updates.name = name;
      if (description !== undefined) updates.description = description;
      if (parentId !== undefined) updates.parentId = parentId;
      if (isActive !== undefined) updates.isActive = isActive;
      if (sortOrder !== undefined) updates.sortOrder = sortOrder;
      if (tags !== undefined) updates.tags = tags;

      await db.update(locations).set(updates).where(eq(locations.id, id));

      // Update branch access if specified
      if (branchIds !== undefined) {
        // Remove existing branch access
        await db.delete(locationBranchAccess).where(eq(locationBranchAccess.locationId, id));
        
        // Add new branch access
        if (branchIds.length > 0) {
          const now = new Date();
          const branchAccessValues = branchIds.map((branchId: string) => ({
            id: crypto.randomUUID(),
            locationId: id,
            branchId,
            createdAt: now,
          }));
          await db.insert(locationBranchAccess).values(branchAccessValues);
        }
      }

      res.json({ success: true });
    } catch (error) {
      next(error);
    }
  });

  // Delete a location
  app.delete("/api/locations/:id", requireAuth, requireRole("admin", "global_admin", "operator_admin", "manager"), async (req, res, next) => {
    try {
      const { id } = req.params;
      
      // Check for sublocations
      const [sublocation] = await db
        .select()
        .from(locations)
        .where(eq(locations.parentId, id))
        .limit(1);
      
      if (sublocation) {
        return res.status(400).json({ message: "Cannot delete location with sublocations. Delete sublocations first." });
      }

      await db.delete(locations).where(eq(locations.id, id));
      res.json({ success: true });
    } catch (error) {
      next(error);
    }
  });

  // ============================================
  // ACCESS VAULT ROUTES
  // ============================================

  // Get access items (filtered by user's visibility level and branch access)
  // Admin mode: ?adminMode=true bypasses visibility/branch filtering (admin only)
  app.get("/api/access", requireAuth, async (req, res, next) => {
    try {
      const tenantId = await getDefaultTenantId();
      const user = req.userWithAccess;
      const userRole = user?.role || 'staff';
      const branchId = req.query.branchId as string | undefined;
      const category = req.query.category as string | undefined;
      const status = (req.query.status as string) || 'active';
      const adminMode = req.query.adminMode === 'true';

      // Admin mode bypasses visibility/branch filtering for config page
      const isAdmin = userRole === 'global_admin' || userRole === 'operator_admin' || userRole === 'admin';
      const useAdminMode = adminMode && isAdmin;

      // Get all access items for the tenant
      const allItems = await storage.getAccessItems(tenantId);
      
      // Filter by status
      let items = allItems.filter(item => item.status === status);

      // Filter by visibility level based on user role (skip in admin mode)
      if (!useAdminMode) {
        items = items.filter(item => {
          if (isAdmin) {
            return true; // Admin can see all
          }
          if (userRole === 'manager') {
            return item.visibilityLevel === 'admin_manager' || item.visibilityLevel === 'all_staff';
          }
          // staff
          return item.visibilityLevel === 'all_staff';
        });

        // Filter by branch access (skip in admin mode)
        if (user && !user.hasAllBranchesAccess) {
          items = items.filter(item => {
            if (!item.branchIds || item.branchIds.length === 0) return true; // No branch restriction
            return item.branchIds.some(bid => user.allowedBranchIds.includes(bid));
          });
        }
      }

      // Filter by specific branch if provided
      if (branchId) {
        items = items.filter(item => {
          if (!item.branchIds || item.branchIds.length === 0) return true;
          return item.branchIds.includes(branchId);
        });
      }

      // Filter by category if provided
      if (category) {
        items = items.filter(item => item.category === category);
      }

      // Remove encrypted passwords from list view
      const safeItems = items.map(item => ({
        id: item.id,
        title: item.title,
        category: item.category,
        username: item.username,
        branchIds: item.branchIds,
        visibilityLevel: item.visibilityLevel,
        status: item.status,
        notes: item.notes,
        updatedAt: item.updatedAt,
        updatedBy: item.updatedBy,
      }));

      res.json(safeItems);
    } catch (error) {
      next(error);
    }
  });

  // Get single access item (includes password)
  app.get("/api/access/:id", requireAuth, async (req, res, next) => {
    try {
      const { id } = req.params;
      const user = req.userWithAccess;
      const userRole = user?.role || 'staff';

      const item = await storage.getAccessItem(id);
      if (!item) {
        return res.status(404).json({ message: "Access item not found" });
      }

      // Check visibility
      let canView = false;
      if (userRole === 'global_admin' || userRole === 'operator_admin' || userRole === 'admin') {
        canView = true;
      } else if (userRole === 'manager') {
        canView = item.visibilityLevel === 'admin_manager' || item.visibilityLevel === 'all_staff';
      } else {
        canView = item.visibilityLevel === 'all_staff';
      }

      // Check branch access
      if (canView && user && !user.hasAllBranchesAccess) {
        if (item.branchIds && item.branchIds.length > 0) {
          canView = item.branchIds.some(bid => user.allowedBranchIds.includes(bid));
        }
      }

      if (!canView) {
        return res.status(403).json({ message: "Access denied" });
      }

      res.json(item);
    } catch (error) {
      next(error);
    }
  });

  // Log password view (only if user has visibility)
  app.post("/api/access/:id/view-log", requireAuth, async (req, res, next) => {
    try {
      const { id } = req.params;
      const tenantId = await getDefaultTenantId();
      const user = req.user;
      const userWithAccess = req.userWithAccess;
      const userRole = userWithAccess?.role || 'staff';

      if (!user) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      // Verify user has access to this item before logging
      const item = await storage.getAccessItem(id);
      if (!item) {
        return res.status(404).json({ message: "Access item not found" });
      }

      // Check visibility
      let canView = false;
      if (userRole === 'global_admin' || userRole === 'operator_admin' || userRole === 'admin') {
        canView = true;
      } else if (userRole === 'manager') {
        canView = item.visibilityLevel === 'admin_manager' || item.visibilityLevel === 'all_staff';
      } else {
        canView = item.visibilityLevel === 'all_staff';
      }

      // Check branch access
      if (canView && userWithAccess && !userWithAccess.hasAllBranchesAccess) {
        if (item.branchIds && item.branchIds.length > 0) {
          canView = item.branchIds.some(bid => userWithAccess.allowedBranchIds.includes(bid));
        }
      }

      if (!canView) {
        return res.status(403).json({ message: "Access denied" });
      }

      await storage.createAccessViewLog({
        tenantId,
        accessItemId: id,
        viewedBy: user.id,
      });

      res.json({ success: true });
    } catch (error) {
      next(error);
    }
  });

