  // ==================== AVATAR WORK STATUS ====================
  app.post("/api/avatar-status/batch", requireAuth, async (req, res, next) => {
    try {
      const user = req.user as any;
      const tenantId = user.tenantId;
      const { date, branchId, scope, employeeIds } = req.body;

      if (!date || !employeeIds || !Array.isArray(employeeIds) || employeeIds.length === 0) {
        return res.status(400).json({ message: "date and employeeIds[] are required" });
      }

      const resolvedScope: "BRANCH" | "GLOBAL" = scope || (branchId ? "BRANCH" : "GLOBAL");
      const targetDate = date;

      const clockInConditions = [
        eq(timeEntries.tenantId, tenantId),
        inArray(timeEntries.employeeId, employeeIds),
        eq(timeEntries.shiftDate, targetDate),
        isNotNull(timeEntries.clockInAt),
        isNull(timeEntries.clockOutAt),
      ];
      if (resolvedScope === "BRANCH" && branchId) {
        clockInConditions.push(eq(timeEntries.branchId, branchId));
      }

      const activeClockIns = await db.select({
        employeeId: timeEntries.employeeId,
      }).from(timeEntries).where(and(...clockInConditions));

      const clockedInSet = new Set(activeClockIns.map(c => c.employeeId));

      const assignmentConditions = [
        eq(scheduleAssignments.tenantId, tenantId),
        inArray(scheduleAssignments.employeeId, employeeIds),
        eq(scheduleAssignments.shiftDate, targetDate),
      ];

      const assignmentResults = await db.select({
        employeeId: scheduleAssignments.employeeId,
        branchId: scheduleShiftRows.branchId,
      }).from(scheduleAssignments)
        .innerJoin(scheduleShiftRows, eq(scheduleAssignments.shiftRowId, scheduleShiftRows.id))
        .where(and(...assignmentConditions));

      const scheduledWorkSet = new Set<string>();
      for (const a of assignmentResults) {
        if (a.employeeId) {
          if (resolvedScope === "BRANCH" && branchId) {
            if (a.branchId === branchId) {
              scheduledWorkSet.add(a.employeeId);
            }
          } else {
            scheduledWorkSet.add(a.employeeId);
          }
        }
      }

      const dateAsTimestamp = new Date(targetDate + "T00:00:00Z");
      const dateEndAsTimestamp = new Date(targetDate + "T23:59:59Z");

      const timeOffConditions = [
        eq(employeeTimeOff.tenantId, tenantId),
        inArray(employeeTimeOff.employeeId, employeeIds),
        lte(employeeTimeOff.startDate, dateEndAsTimestamp),
        gte(employeeTimeOff.endDate, dateAsTimestamp),
      ];
      if (resolvedScope === "BRANCH" && branchId) {
        timeOffConditions.push(eq(employeeTimeOff.branchId, branchId));
      }

      const timeOffResults = await db.select({
        employeeId: employeeTimeOff.employeeId,
      }).from(employeeTimeOff).where(and(...timeOffConditions));

      const scheduledOffSet = new Set(timeOffResults.map(t => t.employeeId));

      const statusMap: Record<string, { status: string; color: string; tooltip: string }> = {};
      for (const empId of employeeIds) {
        if (clockedInSet.has(empId)) {
          statusMap[empId] = { status: "CLOCKED_IN", color: "green", tooltip: "Clocked in" };
        } else if (scheduledWorkSet.has(empId)) {
          statusMap[empId] = { status: "SCHEDULED_TO_WORK", color: "blue", tooltip: "Scheduled (not clocked in)" };
        } else if (scheduledOffSet.has(empId)) {
          statusMap[empId] = { status: "SCHEDULED_OFF", color: "gray", tooltip: "Scheduled off" };
        } else {
          statusMap[empId] = { status: "NOT_SCHEDULED", color: "red", tooltip: "Not scheduled" };
        }
      }

      res.json(statusMap);
    } catch (error) {
      next(error);
    }
  });

