  // Set module overrides for a specific user (admin only) - replaces all existing overrides
  app.put("/api/module-overrides/:userId", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const { userId } = req.params;
      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }

      const schema = z.object({
        overrides: z.array(z.object({
          moduleKey: z.enum(["today", "tasks", "checklists", "scheduling", "events", "hr", "hr_admin", "org_chart", "reports", "settings", "studio"]),
          enabled: z.boolean(),
          branchScopeType: z.enum(["HOME_ONLY", "ALL", "CUSTOM"]).default("HOME_ONLY"),
          branchIds: z.array(z.string()).default([]),
          notes: z.string().optional().nullable(),
        })),
      });

      const { overrides } = schema.parse(req.body);
      const tenantId = await resolveTenantId(req.user?.tenantId);
      const result = await storage.setModuleOverrides(userId, tenantId, overrides, req.user!.id);

      // Log activity
      await storage.createActivityLog({
        activityType: "user_permissions_updated",
        createdBy: req.user!.id,
        summaryText: `Module permission overrides updated for user ${userId} (${overrides.length} override(s))`,
        metadataJson: JSON.stringify({ overrideCount: overrides.length, modules: overrides.map(o => o.moduleKey) }),
      });

      res.json(result);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Validation error", errors: error.errors });
      }
      next(error);
    }
  });

