  // Get all people with their access policies for bulk permissions management (admin only)
  app.get("/api/permissions/bulk", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const tenantId = await resolveTenantId(req.user?.tenantId);
      const allPeople = await storage.getPeople();
      const activePeople = allPeople.filter(p => p.isActive);
      
      const allEmployees = await storage.getEmployees(tenantId);
      const allOverrides = await storage.getModuleOverridesByTenant(tenantId);
      const allUsers = await storage.getUsers();
      const allBranches = await storage.getBranches();
      const allDepartments = await storage.getDepartments();
      
      const getRoleDefaults = (role: string): Record<string, boolean> => {
        if (["global_admin", "admin", "operator_admin", "manager"].includes(role)) {
          return { core: true, hr: true, events: true, ops: true, setup: true };
        }
        return { core: true, hr: false, events: true, ops: true, setup: false };
      };

      const getRoleLevelLabel = (role: string): string => {
        if (["global_admin", "operator_admin"].includes(role)) return "ADMIN";
        if (role === "admin") return "ADMIN";
        if (role === "manager") return "MANAGER";
        return "STAFF";
      };

      const results = await Promise.all(activePeople.map(async (person) => {
        const accessPolicy = await storage.getAccessPolicy(person.id);
        const employee = allEmployees.find(e => e.personId === person.id);
        const user = employee?.userId ? allUsers.find(u => u.id === employee.userId) : 
          allUsers.find(u => u.email === person.email);
        const moduleOverrides = user ? allOverrides.filter(o => o.userId === user.id) : [];
        const branch = employee?.branchId ? allBranches.find(b => b.id === employee.branchId) : null;
        
        let effectivePolicy: any = null;
        if (accessPolicy) {
          effectivePolicy = {
            id: accessPolicy.id,
            accessLevel: accessPolicy.accessLevel,
            modules: accessPolicy.modules,
            branchScope: accessPolicy.branchScope,
            branchIds: accessPolicy.branchIds,
            coreAccountEnabled: accessPolicy.coreAccountEnabled,
            coreUserId: accessPolicy.coreUserId,
            provisioningStatus: accessPolicy.provisioningStatus,
            source: "policy",
          };
        } else if (user) {
          const roleModules = getRoleDefaults(user.role);
          let effectiveModules = { ...roleModules };
          for (const override of moduleOverrides) {
            if (override.moduleKey in effectiveModules) {
              effectiveModules[override.moduleKey] = override.enabled;
            }
          }
          effectivePolicy = {
            id: null,
            accessLevel: getRoleLevelLabel(user.role),
            modules: effectiveModules,
            branchScope: "ALL",
            branchIds: null,
            coreAccountEnabled: true,
            coreUserId: user.id,
            provisioningStatus: null,
            source: "role",
          };
        }

        return {
          personId: person.id,
          fullName: person.fullName,
          preferredName: person.preferredName,
          nickname: employee?.nickname || null,
          email: person.email,
          personType: person.personType,
          userId: user?.id || null,
          userRole: user?.role || null,
          branchId: employee?.branchId || null,
          branchName: branch?.name || null,
          departmentId: employee?.primaryDepartmentId || person.departmentId || null,
          departmentName: (() => {
            const deptId = employee?.primaryDepartmentId || person.departmentId;
            if (!deptId) return null;
            const dept = allDepartments.find(d => d.id === deptId);
            return dept?.name || null;
          })(),
          accessPolicy: effectivePolicy,
          moduleOverrides: moduleOverrides.map(o => ({
            moduleKey: o.moduleKey,
            enabled: o.enabled,
            branchScopeType: o.branchScopeType,
            branchIds: o.branchIds,
          })),
        };
      }));
      
      results.sort((a, b) => a.fullName.localeCompare(b.fullName));
      res.json(results);
    } catch (error) {
      next(error);
    }
  });

  // Bulk update module access for multiple people (admin only)
  app.put("/api/permissions/bulk-update", requireAuth, requireAdmin, async (req, res, next) => {
    try {
      const schema = z.object({
        personIds: z.array(z.string()).min(1),
        moduleKey: z.string(),
        enabled: z.boolean(),
      });
      const { personIds, moduleKey, enabled } = schema.parse(req.body);
      const resolvedTenantId = await resolveTenantId(req.user?.tenantId);

      let updated = 0;
      let skipped = 0;
      for (const personId of personIds) {
        const person = await storage.getPerson(personId);
        if (!person) { skipped++; continue; }

        const existingPolicy = await storage.getAccessPolicy(personId);
        if (existingPolicy) {
          const updatedModules = { ...existingPolicy.modules, [moduleKey]: enabled };
          await storage.updateAccessPolicy(personId, { modules: updatedModules });
          updated++;
        } else {
          const allEmployees = await storage.getEmployees(resolvedTenantId);
          const allUsers = await storage.getUsers();
          const employee = allEmployees.find(e => e.personId === personId);
          const user = employee?.userId ? allUsers.find(u => u.id === employee.userId) :
            allUsers.find(u => u.email === person.email);

          if (user) {
            const isAdmin = ["global_admin", "admin", "operator_admin", "manager"].includes(user.role);
            const defaultModules = {
              core: true,
              hr: isAdmin,
              studio: false,
              events: true,
              ops: true,
              setup: isAdmin,
            };
            const newModules = { ...defaultModules, [moduleKey]: enabled };
            const accessLevel = ["global_admin", "admin", "operator_admin"].includes(user.role) ? "ADMIN" :
              user.role === "manager" ? "MANAGER" : "STAFF";
            await storage.createAccessPolicy({
              personId,
              tenantId: resolvedTenantId,
              accessLevel,
              modules: newModules,
              branchScope: "ALL",
              branchIds: null,
            });
            updated++;
          } else {
            skipped++;
          }
        }
      }

      res.json({ updated, skipped });
    } catch (error) {
      next(error);
    }
  });

